INSERT INTO exercises (external_id, name, muscle_group, secondary_muscles, equipment, category, level, instructions) VALUES
('3_4_Sit-Up', '3/4 Sit-Up', 'core', ARRAY[]::text[], 'bodyweight', 'strength', 'beginner', 'Lie down on the floor and secure your feet. Your legs should be bent at the knees. Place your hands behind or to the side of your head. You will begin with your back on the ground. This will be your starting position. Flex your hips and spine to raise your torso toward your knees. At the top of the contraction your torso should be perpendicular to the ground. Reverse the motion, going only ¾ of the way down. Repeat for the recommended amount of repetitions.'),
('90_90_Hamstring', '90/90 Hamstring', 'legs', ARRAY['legs']::text[], 'bodyweight', 'stretching', 'beginner', 'Lie on your back, with one leg extended straight out. With the other leg, bend the hip and knee to 90 degrees. You may brace your leg with your hands if necessary. This will be your starting position. Extend your leg straight into the air, pausing briefly at the top. Return the leg to the starting position. Repeat for 10-20 repetitions, and then switch to the other leg.'),
('Ab_Crunch_Machine', 'Ab Crunch Machine', 'core', ARRAY[]::text[], 'machine', 'strength', 'intermediate', 'Select a light resistance and sit down on the ab machine placing your feet under the pads provided and grabbing the top handles. Your arms should be bent at a 90 degree angle as you rest the triceps on the pads provided. This will be your starting position. At the same time, begin to lift the legs up as you crunch your upper torso. Breathe out as you perform this movement. Tip: Be sure to use a slow and controlled motion. Concentrate on using your abs to move the weight while relaxing your legs '),
('Ab_Roller', 'Ab Roller', 'core', ARRAY['shoulders']::text[], 'other', 'strength', 'intermediate', 'Hold the Ab Roller with both hands and kneel on the floor. Now place the ab roller on the floor in front of you so that you are on all your hands and knees (as in a kneeling push up position). This will be your starting position. Slowly roll the ab roller straight forward, stretching your body into a straight position. Tip: Go down as far as you can without touching the floor with your body. Breathe in during this portion of the movement. After a pause at the stretched position, start pulling yo'),
('Adductor', 'Adductor', 'legs', ARRAY[]::text[], 'other', 'stretching', 'intermediate', 'Lie face down with one leg on a foam roll. Rotate the leg so that the foam roll contacts against your inner thigh. Shift as much weight onto the foam roll as can be tolerated. While trying to relax the muscles if the inner thigh, roll over the foam between your hip and knee, holding points of tension for 10-30 seconds. Repeat with the other leg.'),
('Adductor_Groin', 'Adductor/Groin', 'legs', ARRAY[]::text[], 'other', 'stretching', 'intermediate', 'Lie on your back with your feet raised towards the ceiling. Have your partner hold your feet or ankles. Abduct your legs as far as you can. This will be your starting position. Attempt to squeeze your legs together for 10 or more seconds, while your partner prevents you from doing so. Now, relax the muscles in your legs as your partner pushes your feet apart, stretching as far as is comfortable for you. Be sure to let your partner know when the stretch is adequate to prevent overstretching or in'),
('Advanced_Kettlebell_Windmill', 'Advanced Kettlebell Windmill', 'core', ARRAY['legs','legs','shoulders']::text[], 'kettlebell', 'strength', 'intermediate', 'Clean and press a kettlebell overhead with one arm. Keeping the kettlebell locked out at all times, push your butt out in the direction of the locked out kettlebell. Keep the non-working arm behind your back and turn your feet out at a forty-five degree angle from the arm with the kettlebell. Lower yourself as far as possible. Pause for a second and reverse the motion back to the starting position.'),
('Air_Bike', 'Air Bike', 'core', ARRAY[]::text[], 'bodyweight', 'strength', 'beginner', 'Lie flat on the floor with your lower back pressed to the ground. For this exercise, you will need to put your hands beside your head. Be careful however to not strain with the neck as you perform it. Now lift your shoulders into the crunch position. Bring knees up to where they are perpendicular to the floor, with your lower legs parallel to the floor. This will be your starting position. Now simultaneously, slowly go through a cycle pedal motion kicking forward with the right leg and bringing '),
('All_Fours_Quad_Stretch', 'All Fours Quad Stretch', 'legs', ARRAY['legs']::text[], 'bodyweight', 'stretching', 'intermediate', 'Start off on your hands and knees, then lift your leg off the floor and hold the foot with your hand. Use your hand to hold the foot or ankle, keeping the knee fully flexed, stretching the quadriceps and hip flexors. Focus on extending your hips, thrusting them towards the floor. Hold for 10-20 seconds and then switch sides.'),
('Alternate_Hammer_Curl', 'Alternate Hammer Curl', 'arms', ARRAY['arms']::text[], 'dumbbell', 'strength', 'beginner', 'Stand up with your torso upright and a dumbbell in each hand being held at arms length. The elbows should be close to the torso. The palms of the hands should be facing your torso. This will be your starting position. While holding the upper arm stationary, curl the right weight forward while contracting the biceps as you breathe out. Continue the movement until your biceps is fully contracted and the dumbbells are at shoulder level. Hold the contracted position for a second as you squeeze the b'),
('Alternate_Heel_Touchers', 'Alternate Heel Touchers', 'core', ARRAY[]::text[], 'bodyweight', 'strength', 'beginner', 'Lie on the floor with the knees bent and the feet on the floor around 18-24 inches apart. Your arms should be extended by your side. This will be your starting position. Crunch over your torso forward and up about 3-4 inches to the right side and touch your right heel as you hold the contraction for a second. Exhale while performing this movement. Now go back slowly to the starting position as you inhale. Now crunch over your torso forward and up around 3-4 inches to the left side and touch your'),
('Alternate_Incline_Dumbbell_Curl', 'Alternate Incline Dumbbell Curl', 'arms', ARRAY['arms']::text[], 'dumbbell', 'strength', 'beginner', 'Sit down on an incline bench with a dumbbell in each hand being held at arms length. Tip: Keep the elbows close to the torso.This will be your starting position. While holding the upper arm stationary, curl the right weight forward while contracting the biceps as you breathe out. As you do so, rotate the hand so that the palm is facing up. Continue the movement until your biceps is fully contracted and the dumbbells are at shoulder level. Hold the contracted position for a second as you squeeze '),
('Alternate_Leg_Diagonal_Bound', 'Alternate Leg Diagonal Bound', 'legs', ARRAY['legs','legs','legs','legs','legs']::text[], 'other', 'plyometrics', 'beginner', 'Assume a comfortable stance with one foot slightly in front of the other. Begin by pushing off with the front leg, driving the opposite knee forward and as high as possible before landing. Attempt to cover as much distance to each side with each bound. It may help to use a line on the ground to guage distance from side to side. Repeat the sequence with the other leg.'),
('Alternating_Cable_Shoulder_Press', 'Alternating Cable Shoulder Press', 'shoulders', ARRAY['arms']::text[], 'cable', 'strength', 'beginner', 'Move the cables to the bottom of the tower and select an appropriate weight. Grasp the cables and hold them at shoulder height, palms facing forward. This will be your starting position. Keeping your head and chest up, extend through the elbow to press one side directly over head. After pausing at the top, return to the starting position and repeat on the opposite side.'),
('Alternating_Deltoid_Raise', 'Alternating Deltoid Raise', 'shoulders', ARRAY[]::text[], 'dumbbell', 'strength', 'beginner', 'In a standing position, hold a pair of dumbbells at your side. Keeping your elbows slightly bent, raise the weights directly in front of you to shoulder height, avoiding any swinging or cheating. Return the weights to your side. On the next repetition, raise the weights laterally, raising them out to your side to about shoulder height. Return the weights to the starting position and continue alternating to the front and side.'),
('Alternating_Floor_Press', 'Alternating Floor Press', 'chest', ARRAY['core','shoulders','arms']::text[], 'kettlebell', 'strength', 'beginner', 'Lie on the floor with two kettlebells next to your shoulders. Position one in place on your chest and then the other, gripping the kettlebells on the handle with the palms facing forward. Extend both arms, so that the kettlebells are being held above your chest. Lower one kettlebell, bringing it to your chest and turn the wrist in the direction of the locked out kettlebell. Raise the kettlebell and repeat on the opposite side.'),
('Alternating_Hang_Clean', 'Alternating Hang Clean', 'legs', ARRAY['arms','legs','arms','legs','back','back']::text[], 'kettlebell', 'strength', 'intermediate', 'Place two kettlebells between your feet. To get in the starting position, push your butt back and look straight ahead. Clean one kettlebell to your shoulder and hold on to the other kettlebell in a hanging position. Clean the kettlebell to your shoulder by extending through the legs and hips as you pull the kettlebell towards your shoulders. Rotate your wrist as you do so. Lower the cleaned kettlebell to a hanging position and clean the alternate kettlebell. Repeat.'),
('Alternating_Kettlebell_Press', 'Alternating Kettlebell Press', 'shoulders', ARRAY['arms']::text[], 'kettlebell', 'strength', 'intermediate', 'Clean two kettlebells to your shoulders. Clean the kettlebells to your shoulders by extending through the legs and hips as you pull the kettlebells towards your shoulders. Rotate your wrists as you do so. Press one directly overhead by extending through the elbow, turning it so the palm faces forward while holding the other kettlebell stationary . Lower the pressed kettlebell to the starting position and immediately press with your other arm.'),
('Alternating_Kettlebell_Row', 'Alternating Kettlebell Row', 'back', ARRAY['arms','back']::text[], 'kettlebell', 'strength', 'intermediate', 'Place two kettlebells in front of your feet. Bend your knees slightly and push your butt out as much as possible. As you bend over to get into the starting position grab both kettlebells by the handles. Pull one kettlebell off of the floor while holding on to the other kettlebell. Retract the shoulder blade of the working side, as you flex the elbow, drawing the kettlebell towards your stomach or rib cage. Lower the kettlebell in the working arm and repeat with your other arm.'),
('Alternating_Renegade_Row', 'Alternating Renegade Row', 'back', ARRAY['core','arms','chest','back','arms']::text[], 'kettlebell', 'strength', 'expert', 'Place two kettlebells on the floor about shoulder width apart. Position yourself on your toes and your hands as though you were doing a pushup, with the body straight and extended. Use the handles of the kettlebells to support your upper body. You may need to position your feet wide for support. Push one kettlebell into the floor and row the other kettlebell, retracting the shoulder blade of the working side as you flex the elbow, pulling it to your side. Then lower the kettlebell to the floor a'),
('Ankle_Circles', 'Ankle Circles', 'legs', ARRAY[]::text[], 'other', 'stretching', 'beginner', 'Use a sturdy object like a squat rack to hold yourself. Lift the right leg in the air (just around 2 inches from the floor) and perform a circular motion with the big toe. Pretend that you are drawing a big circle with it. Tip: One circle equals 1 repetition. Breathe normally as you perform the movement. When you are done with the right foot, then repeat with the left leg.'),
('Ankle_On_The_Knee', 'Ankle On The Knee', 'legs', ARRAY[]::text[], 'other', 'stretching', 'beginner', 'From a lying position, bend your knees and keep your feet on the floor. Place your ankle of one foot on your opposite knee. Grasp the thigh or knee of the bottom leg and pull both of your legs into the chest. Relax your neck and shoulders. Hold for 10-20 seconds and then switch sides.'),
('Anterior_Tibialis-SMR', 'Anterior Tibialis-SMR', 'legs', ARRAY[]::text[], 'other', 'stretching', 'intermediate', 'Begin seated on the ground with your legs bent and your feet on the floor. Using a Muscle Roller or a rolling pin, apply pressure to the muscles on the outside of your shins. Work from just below the knee to above the ankle, pausing at points of tension for 10-30 seconds. Repeat on the other leg.'),
('Anti-Gravity_Press', 'Anti-Gravity Press', 'shoulders', ARRAY['back','back','arms']::text[], 'barbell', 'strength', 'beginner', 'Place a bar on the ground behind the head of an incline bench. Lay on the bench face down. With a pronated grip, pick the barbell up from the floor. Flex the elbows, performing a reverse curl to bring the bar near your chest. This will be your starting position. To begin, press the barbell out in front of your head by extending your elbows. Keep your arms parallel to the ground throughout the movement. Return to the starting position and repeat to complete the set.'),
('Arm_Circles', 'Arm Circles', 'shoulders', ARRAY['back']::text[], 'other', 'stretching', 'beginner', 'Stand up and extend your arms straight out by the sides. The arms should be parallel to the floor and perpendicular (90-degree angle) to your torso. This will be your starting position. Slowly start to make circles of about 1 foot in diameter with each outstretched arm. Breathe normally as you perform the movement. Continue the circular motion of the outstretched arms for about ten seconds. Then reverse the movement, going the opposite direction.'),
('Arnold_Dumbbell_Press', 'Arnold Dumbbell Press', 'shoulders', ARRAY['arms']::text[], 'dumbbell', 'strength', 'intermediate', 'Sit on an exercise bench with back support and hold two dumbbells in front of you at about upper chest level with your palms facing your body and your elbows bent. Tip: Your arms should be next to your torso. The starting position should look like the contracted portion of a dumbbell curl. Now to perform the movement, raise the dumbbells as you rotate the palms of your hands until they are facing forward. Continue lifting the dumbbells until your arms are extended above you in straight arm posit'),
('Around_The_Worlds', 'Around The Worlds', 'chest', ARRAY['shoulders']::text[], 'dumbbell', 'strength', 'intermediate', 'Lay down on a flat bench holding a dumbbell in each hand with the palms of the hands facing towards the ceiling. Tip: Your arms should be parallel to the floor and next to your thighs. To avoid injury, make sure that you keep your elbows slightly bent. This will be your starting position. Now move the dumbbells by creating a semi-circle as you displace them from the initial position to over the head. All of the movement should happen with the arms parallel to the floor at all times. Breathe in a'),
('Atlas_Stone_Trainer', 'Atlas Stone Trainer', 'back', ARRAY['arms','arms','legs','legs','legs']::text[], 'other', 'strongman', 'intermediate', 'This trainer is effective for developing Atlas Stone strength for those who don''t have access to stones, and are typically made from bar ends or heavy pipe. Begin by loading the desired weight onto the bar. Straddle the weight, wrapping your arms around the implement, bending at the hips. Begin by pulling the weight up past the knees, extending through the hips. As the weight clears the knees, it can be lapped by resting it on your thighs and sitting back, hugging it tightly to your chest. Fini'),
('Atlas_Stones', 'Atlas Stones', 'back', ARRAY['core','legs','arms','legs','arms','legs','legs','back','legs','back']::text[], 'other', 'strongman', 'expert', 'Begin with the atlas stone between your feet. Bend at the hips to wrap your arms vertically around the Atlas Stone, attempting to get your fingers underneath the stone. Many stones will have a small flat portion on the bottom, which will make the stone easier to hold. Pulling the stone into your torso, drive through the back half of your feet to pull the stone from the ground. As the stone passes the knees, lap it by sitting backward, pulling the stone on top of your thighs. Sit low, getting the'),
('Axle_Deadlift', 'Axle Deadlift', 'back', ARRAY['arms','legs','legs','back','legs','back']::text[], 'other', 'strongman', 'intermediate', 'Approach the bar so that it is centered over your feet. You feet should be about hip width apart. Bend at the hip to grip the bar at shoulder width, allowing your shoulder blades to protract. Typically, you would use an over/under grip. With your feet and your grip set, take a big breath and then lower your hips and flex the knees until your shins contact the bar. Look forward with your head, keep your chest up and your back arched, and begin driving through the heels to move the weight upward. '),
('Back_Flyes_-_With_Bands', 'Back Flyes - With Bands', 'shoulders', ARRAY['back','arms']::text[], 'bands', 'strength', 'beginner', 'Run a band around a stationary post like that of a squat rack. Grab the band by the handles and stand back so that the tension in the band rises. Extend and lift the arms straight in front of you. Tip: Your arms should be straight and parallel to the floor while perpendicular to your torso. Your feet should be firmly planted on the floor spread at shoulder width. This will be your starting position. As you exhale, move your arms to the sides and back. Keep your arms extended and parallel to the '),
('Backward_Drag', 'Backward Drag', 'legs', ARRAY['legs','arms','legs','legs','back']::text[], 'other', 'strongman', 'beginner', 'Load a sled with the desired weight, attaching a rope or straps to the sled that you can hold onto. Begin the exercise by moving backwards for a given distance. Leaning back, extend through the legs for short steps to move as quickly as possible.'),
('Backward_Medicine_Ball_Throw', 'Backward Medicine Ball Throw', 'shoulders', ARRAY[]::text[], 'other', 'plyometrics', 'beginner', 'This exercise is best done with a partner. If you lack a partner, the ball can be thrown and retrieved or thrown against a wall. Begin standing a few meters in front of your partner, both facing the same direction. Begin holding the ball between your legs. Squat down and then forcefully reverse direction, coming to full extension and you toss the ball over your head to your partner. Your partner can then roll the ball back to you. Repeat for the desired number of repetitions.'),
('Balance_Board', 'Balance Board', 'legs', ARRAY['legs','legs']::text[], 'other', 'strength', 'beginner', 'Place a balance board in front of you. Stand up on it and try to balance yourself. Hold the balance for as long as desired.'),
('Ball_Leg_Curl', 'Ball Leg Curl', 'legs', ARRAY['legs','legs']::text[], 'other', 'strength', 'beginner', 'Begin on the floor laying on your back with your feet on top of the ball. Position the ball so that when your legs are extended your ankles are on top of the ball. This will be your starting position. Raise your hips off of the ground, keeping your weight on the shoulder blades and your feet. Flex the knees, pulling the ball as close to you as you can, contracting the hamstrings. After a brief pause, return to the starting position.'),
('Band_Assisted_Pull-Up', 'Band Assisted Pull-Up', 'back', ARRAY['core','arms','back']::text[], 'other', 'strength', 'beginner', 'Choke the band around the center of the pullup bar. You can use different bands to provide varying levels of assistance. Pull the end of the band down, and place one bent knee into the loop, ensuring it won''t slip out. Take a medium to wide grip on the bar. This will be your starting position. Pull yourself upward by contracting the lats as you flex the elbow. The elbow should be driven to your side. Pull to the front, attempting to get your chin over the bar. Avoid swinging or jerking movement'),
('Band_Good_Morning', 'Band Good Morning', 'legs', ARRAY['legs','back']::text[], 'bands', 'powerlifting', 'beginner', 'Using a 41 inch band, stand on one end, spreading your feet a small amount. Bend at the hips to loop the end of the band behind your neck. This will be your starting position. Keeping your legs straight, extend through the hips to come to a near vertical position. Ensure that you do not round your back as you go down back to the starting position.'),
('Band_Good_Morning_Pull_Through', 'Band Good Morning (Pull Through)', 'legs', ARRAY['legs','back']::text[], 'bands', 'powerlifting', 'beginner', 'Loop the band around a post. Standing a little ways away, loop the opposite end around the neck. Your hands can help hold the band in position. Begin by bending at the hips, getting your butt back as far as possible. Keep your back flat and bend forward to about 90 degrees. Your knees should be only slightly bent. Return to the starting position be driving through with the hips to come back to a standing position.'),
('Band_Hip_Adductions', 'Band Hip Adductions', 'legs', ARRAY[]::text[], 'bands', 'strength', 'beginner', 'Anchor a band around a solid post or other object. Stand with your left side to the post, and put your right foot through the band, getting it around the ankle. Stand up straight and hold onto the post if needed. This will be your starting position. Keeping the knee straight, raise your right legs out to the side as far as you can. Return to the starting position and repeat for the desired rep count. Switch sides.'),
('Band_Pull_Apart', 'Band Pull Apart', 'shoulders', ARRAY['back','back']::text[], 'bands', 'strength', 'beginner', 'Begin with your arms extended straight out in front of you, holding the band with both hands. Initiate the movement by performing a reverse fly motion, moving your hands out laterally to your sides. Keep your elbows extended as you perform the movement, bringing the band to your chest. Ensure that you keep your shoulders back during the exercise. Pause as you complete the movement, returning to the starting position under control.'),
('Band_Skull_Crusher', 'Band Skull Crusher', 'arms', ARRAY[]::text[], 'bands', 'strength', 'beginner', 'Secure a band to the base of a rack or the bench. Lay on the bench so that the band is lined up with your head. Take hold of the band, raising your elbows so that the upper arm is perpendicular to the floor. With the elbow flexed, the band should be above your head. This will be your starting position. Extend through the elbow to straighten your arm, keeping your upper arm in place. Pause at the top of the motion, and return to the starting position.'),
('Barbell_Ab_Rollout', 'Barbell Ab Rollout', 'core', ARRAY['back','shoulders']::text[], 'barbell', 'strength', 'intermediate', 'For this exercise you will need to get into a pushup position, but instead of having your hands of the floor, you will be grabbing on to an Olympic barbell (loaded with 5-10 lbs on each side) instead. This will be your starting position. While keeping a slight arch on your back, lift your hips and roll the barbell towards your feet as you exhale. Tip: As you perform the movement, your glutes should be coming up, you should be keeping the abs tight and should maintain your back posture at all tim'),
('Barbell_Ab_Rollout_-_On_Knees', 'Barbell Ab Rollout - On Knees', 'core', ARRAY['back','shoulders']::text[], 'barbell', 'strength', 'expert', 'Hold an Olympic barbell loaded with 5-10lbs on each side and kneel on the floor. Now place the barbell on the floor in front of you so that you are on all your hands and knees (as in a kneeling push up position). This will be your starting position. Slowly roll the barbell straight forward, stretching your body into a straight position. Tip: Go down as far as you can without touching the floor with your body. Breathe in during this portion of the movement. After a second pause at the stretched p'),
('Barbell_Bench_Press_-_Medium_Grip', 'Barbell Bench Press - Medium Grip', 'chest', ARRAY['shoulders','arms']::text[], 'barbell', 'strength', 'beginner', 'Lie back on a flat bench. Using a medium width grip (a grip that creates a 90-degree angle in the middle of the movement between the forearms and the upper arms), lift the bar from the rack and hold it straight over you with your arms locked. This will be your starting position. From the starting position, breathe in and begin coming down slowly until the bar touches your middle chest. After a brief pause, push the bar back to the starting position as you breathe out. Focus on pushing the bar us'),
('Barbell_Curl', 'Barbell Curl', 'arms', ARRAY['arms']::text[], 'barbell', 'strength', 'beginner', 'Stand up with your torso upright while holding a barbell at a shoulder-width grip. The palm of your hands should be facing forward and the elbows should be close to the torso. This will be your starting position. While holding the upper arms stationary, curl the weights forward while contracting the biceps as you breathe out. Tip: Only the forearms should move. Continue the movement until your biceps are fully contracted and the bar is at shoulder level. Hold the contracted position for a second'),
('Barbell_Curls_Lying_Against_An_Incline', 'Barbell Curls Lying Against An Incline', 'arms', ARRAY[]::text[], 'barbell', 'strength', 'beginner', 'Lie against an incline bench, with your arms holding a barbell and hanging down in a horizontal line. This will be your starting position. While keeping the upper arms stationary, curl the weight up as high as you can while squeezing the biceps. Breathe out as you perform this portion of the movement. Tip: Only the forearms should move. Do not swing the arms. After a second contraction, slowly go back to the starting position as you inhale. Tip: Make sure that you go all of the way down. Repeat '),
('Barbell_Deadlift', 'Barbell Deadlift', 'back', ARRAY['legs','arms','legs','legs','back','back','legs','back']::text[], 'barbell', 'strength', 'intermediate', 'Stand in front of a loaded barbell. While keeping the back as straight as possible, bend your knees, bend forward and grasp the bar using a medium (shoulder width) overhand grip. This will be the starting position of the exercise. Tip: If it is difficult to hold on to the bar with this grip, alternate your grip or use wrist straps. While holding the bar, start the lift by pushing with your legs while simultaneously getting your torso to the upright position as you breathe out. In the upright pos'),
('Barbell_Full_Squat', 'Barbell Full Squat', 'legs', ARRAY['legs','legs','legs','back']::text[], 'barbell', 'strength', 'intermediate', 'This exercise is best performed inside a squat rack for safety purposes. To begin, first set the bar on a rack just above shoulder level. Once the correct height is chosen and the bar is loaded, step under the bar and place the back of your shoulders (slightly below the neck) across it. Hold on to the bar using both arms at each side and lift it off the rack by first pushing with your legs and at the same time straightening your torso. Step away from the rack and position your legs using a shoul'),
('Barbell_Glute_Bridge', 'Barbell Glute Bridge', 'legs', ARRAY['legs','legs']::text[], 'barbell', 'powerlifting', 'intermediate', 'Begin seated on the ground with a loaded barbell over your legs. Using a fat bar or having a pad on the bar can greatly reduce the discomfort caused by this exercise. Roll the bar so that it is directly above your hips, and lay down flat on the floor. Begin the movement by driving through with your heels, extending your hips vertically through the bar. Your weight should be supported by your upper back and the heels of your feet. Extend as far as possible, then reverse the motion to return to th'),
('Barbell_Guillotine_Bench_Press', 'Barbell Guillotine Bench Press', 'chest', ARRAY['shoulders','arms']::text[], 'barbell', 'strength', 'intermediate', 'Using a medium width grip (a grip that creates a 90-degree angle in the middle of the movement between the forearms and the upper arms), lift the bar from the rack and hold it straight over your neck with your arms locked. This will be your starting position. As you breathe in, bring the bar down slowly until it is about 1 inch from your neck. After a second pause, bring the bar back to the starting position as you breathe out and push the bar using your chest muscles. Lock your arms and squeeze')
INSERT INTO exercises (external_id, name, muscle_group, secondary_muscles, equipment, category, level, instructions) VALUES
('Barbell_Hack_Squat', 'Barbell Hack Squat', 'legs', ARRAY['legs','arms','legs']::text[], 'barbell', 'strength', 'intermediate', 'Stand up straight while holding a barbell behind you at arms length and your feet at shoulder width. Tip: A shoulder width grip is best with the palms of your hands facing back. You can use wrist wraps for this exercise for a better grip. This will be your starting position. While keeping your head and eyes up and back straight, squat until your upper thighs are parallel to the floor. Breathe in as you slowly go down. Pressing mainly with the heel of the foot and squeezing the thighs, go back up'),
('Barbell_Hip_Thrust', 'Barbell Hip Thrust', 'legs', ARRAY['legs','legs']::text[], 'barbell', 'powerlifting', 'intermediate', 'Begin seated on the ground with a bench directly behind you. Have a loaded barbell over your legs. Using a fat bar or having a pad on the bar can greatly reduce the discomfort caused by this exercise. Roll the bar so that it is directly above your hips, and lean back against the bench so that your shoulder blades are near the top of it. Begin the movement by driving through your feet, extending your hips vertically through the bar. Your weight should be supported by your shoulder blades and your'),
('Barbell_Incline_Bench_Press_-_Medium_Grip', 'Barbell Incline Bench Press - Medium Grip', 'chest', ARRAY['shoulders','arms']::text[], 'barbell', 'strength', 'beginner', 'Lie back on an incline bench. Using a medium-width grip (a grip that creates a 90-degree angle in the middle of the movement between the forearms and the upper arms), lift the bar from the rack and hold it straight over you with your arms locked. This will be your starting position. As you breathe in, come down slowly until you feel the bar on you upper chest. After a second pause, bring the bar back to the starting position as you breathe out and push the bar using your chest muscles. Lock your'),
('Barbell_Incline_Shoulder_Raise', 'Barbell Incline Shoulder Raise', 'shoulders', ARRAY['chest']::text[], 'barbell', 'strength', 'beginner', 'Lie back on an Incline Bench. Using a medium width grip (a grip that is slightly wider than shoulder width), lift the bar from the rack and hold it straight over you with your arms straight. This will be your starting position. While keeping the arms straight, lift the bar by protracting your shoulder blades, raising the shoulders from the bench as you breathe out. Bring back the bar to the starting position as you breathe in. Repeat for the recommended amount of repetitions.'),
('Barbell_Lunge', 'Barbell Lunge', 'legs', ARRAY['legs','legs','legs']::text[], 'barbell', 'strength', 'intermediate', 'This exercise is best performed inside a squat rack for safety purposes. To begin, first set the bar on a rack just below shoulder level. Once the correct height is chosen and the bar is loaded, step under the bar and place the back of your shoulders (slightly below the neck) across it. Hold on to the bar using both arms at each side and lift it off the rack by first pushing with your legs and at the same time straightening your torso. Step away from the rack and step forward with your right leg'),
('Barbell_Rear_Delt_Row', 'Barbell Rear Delt Row', 'shoulders', ARRAY['arms','back','back']::text[], 'barbell', 'strength', 'beginner', 'Stand up straight while holding a barbell using a wide (higher than shoulder width) and overhand (palms facing your body) grip. Bend knees slightly and bend over as you keep the natural arch of your back. Let the arms hang in front of you as they hold the bar. Once your torso is parallel to the floor, flare the elbows out and away from your body. Tip: Your torso and your arms should resemble the letter "T". Now you are ready to begin the exercise. While keeping the upper arms perpendicular to th'),
('Barbell_Rollout_from_Bench', 'Barbell Rollout from Bench', 'core', ARRAY['legs','legs','back','shoulders']::text[], 'barbell', 'strength', 'intermediate', 'Place a loaded barbell on the ground, near the end of a bench. Kneel with both legs on the bench, and take a medium to narrow grip on the barbell. This will be your starting position. To begin, extend through the hips to slowly roll the bar forward. As you roll out, flex the shoulder to roll the bar above your head. Ensure that your arms remain extended throughout the movement. When the bar has been moved as far forward as possible, return to the starting position.'),
('Barbell_Seated_Calf_Raise', 'Barbell Seated Calf Raise', 'legs', ARRAY[]::text[], 'barbell', 'strength', 'beginner', 'Place a block about 12 inches in front of a flat bench. Sit on the bench and place the ball of your feet on the block. Have someone place a barbell over your upper thighs about 3 inches above your knees and hold it there. This will be your starting position. Raise up on your toes as high as possible as you squeeze the calves and as you breathe out. After a second contraction, slowly go back to the starting position. Tip: To get maximum benefit stretch your calves as far as you can. Repeat for th'),
('Barbell_Shoulder_Press', 'Barbell Shoulder Press', 'shoulders', ARRAY['chest','arms']::text[], 'barbell', 'strength', 'intermediate', 'Sit on a bench with back support in a squat rack. Position a barbell at a height that is just above your head. Grab the barbell with a pronated grip (palms facing forward). Once you pick up the barbell with the correct grip width, lift the bar up over your head by locking your arms. Hold at about shoulder level and slightly in front of your head. This is your starting position. Lower the bar down to the shoulders slowly as you inhale. Lift the bar back up to the starting position as you exhale. '),
('Barbell_Shrug', 'Barbell Shrug', 'back', ARRAY[]::text[], 'barbell', 'strength', 'beginner', 'Stand up straight with your feet at shoulder width as you hold a barbell with both hands in front of you using a pronated grip (palms facing the thighs). Tip: Your hands should be a little wider than shoulder width apart. You can use wrist wraps for this exercise for a better grip. This will be your starting position. Raise your shoulders up as far as you can go as you breathe out and hold the contraction for a second. Tip: Refrain from trying to lift the barbell by using your biceps. Slowly ret'),
('Barbell_Shrug_Behind_The_Back', 'Barbell Shrug Behind The Back', 'back', ARRAY['arms','back']::text[], 'barbell', 'strength', 'beginner', 'Stand up straight with your feet at shoulder width as you hold a barbell with both hands behind your back using a pronated grip (palms facing back). Tip: Your hands should be a little wider than shoulder width apart. You can use wrist wraps for this exercise for better grip. This will be your starting position. Raise your shoulders up as far as you can go as you breathe out and hold the contraction for a second. Tip: Refrain from trying to lift the barbell by using your biceps. The arms should r'),
('Barbell_Side_Bend', 'Barbell Side Bend', 'core', ARRAY['back']::text[], 'barbell', 'strength', 'beginner', 'Stand up straight while holding a barbell placed on the back of your shoulders (slightly below the neck). Your feet should be shoulder width apart. This will be your starting position. While keeping your back straight and your head up, bend only at the waist to the right as far as possible. Breathe in as you bend to the side. Then hold for a second and come back up to the starting position as you exhale. Tip: Keep the rest of the body stationary. Now repeat the movement but bending to the left i'),
('Barbell_Side_Split_Squat', 'Barbell Side Split Squat', 'legs', ARRAY['legs','legs','back']::text[], 'barbell', 'strength', 'beginner', 'Stand up straight while holding a barbell placed on the back of your shoulders (slightly below the neck). Your feet should be placed wide apart with the foot of the lead leg angled out to the side. This will be your starting position. Lower your body towards the side of your angled foot by bending the knee and hip of your lead leg and while keeping the opposite leg only slightly bent. Breathe in as you lower your body. Return to the starting position by extending the hip and knee of the lead leg'),
('Barbell_Squat', 'Barbell Squat', 'legs', ARRAY['legs','legs','legs','back']::text[], 'barbell', 'strength', 'beginner', 'This exercise is best performed inside a squat rack for safety purposes. To begin, first set the bar on a rack to just below shoulder level. Once the correct height is chosen and the bar is loaded, step under the bar and place the back of your shoulders (slightly below the neck) across it. Hold on to the bar using both arms at each side and lift it off the rack by first pushing with your legs and at the same time straightening your torso. Step away from the rack and position your legs using a sh'),
('Barbell_Squat_To_A_Bench', 'Barbell Squat To A Bench', 'legs', ARRAY['legs','legs','legs','back']::text[], 'barbell', 'strength', 'expert', 'This exercise is best performed inside a squat rack for safety purposes. To begin, first place a flat bench or a box behind you. The flat bench is used to teach you to set your hips back and to hit depth.  Then, set the bar on a rack that best matches your height. Once the correct height is chosen and the bar is loaded, step under the bar and place the back of your shoulders (slightly below the neck) across it. Hold on to the bar using both arms at each side and lift it off the rack by first pus'),
('Barbell_Step_Ups', 'Barbell Step Ups', 'legs', ARRAY['legs','legs','legs','legs']::text[], 'barbell', 'strength', 'intermediate', 'Stand up straight while holding a barbell placed on the back of your shoulders (slightly below the neck) and stand upright behind an elevated platform (such as the one used for spotting behind a flat bench). This is your starting position. Place the right foot on the elevated platform. Step on the platform by extending the hip and the knee of your right leg. Use the heel mainly to lift the rest of your body up and place the foot of the left leg on the platform as well. Breathe out as you execute'),
('Barbell_Walking_Lunge', 'Barbell Walking Lunge', 'legs', ARRAY['legs','legs','legs']::text[], 'barbell', 'strength', 'beginner', 'Begin standing with your feet shoulder width apart and a barbell across your upper back. Step forward with one leg, flexing the knees to drop your hips. Descend until your rear knee nearly touches the ground. Your posture should remain upright, and your front knee should stay above the front foot. Drive through the heel of your lead foot and extend both knees to raise yourself back up. Step forward with your rear foot, repeating the lunge on the opposite leg.'),
('Battling_Ropes', 'Battling Ropes', 'shoulders', ARRAY['chest','arms']::text[], 'other', 'strength', 'beginner', 'For this exercise you will need a heavy rope anchored at its center 15-20 feet away. Standing in front of the rope, take an end in each hand with your arms extended at your side. This will be your starting position. Initiate the movement by rapidly raising one arm to shoulder level as quickly as you can. As you let that arm drop to the starting position, raise the opposite side. Continue alternating your left and right arms, whipping the ropes up and down as fast as you can.'),
('Bear_Crawl_Sled_Drags', 'Bear Crawl Sled Drags', 'legs', ARRAY['legs','legs','legs']::text[], 'other', 'strongman', 'beginner', 'Wearing either a harness or a loose weight belt, attach the chain to the back so that you will be facing away from the sled. Bend down so that your hands are on the ground. Your back should be flat and knees bent. This is your starting position. Begin by driving with legs, alternating left and right. Use your hands to maintain balance and to help pull. Try to keep your back flat as you move over a given distance.'),
('Behind_Head_Chest_Stretch', 'Behind Head Chest Stretch', 'chest', ARRAY['shoulders']::text[], 'other', 'stretching', 'expert', 'Sit upright on the floor with your partner behind you. Place your hands behind your hand, and push your elbows back as far as you can. Your partner should hold your elbows. This will be your starting position. Gently attempt to pull your elbows forward with your hands still behind your head for 10 or more seconds. Your partner should prevent your elbows from moving. Now, relax your muscles and have your partner gently pull the elbows back as far as it comfortable for you. Be sure to let your par'),
('Bench_Dips', 'Bench Dips', 'arms', ARRAY['chest','shoulders']::text[], 'bodyweight', 'strength', 'beginner', 'For this exercise you will need to place a bench behind your back. With the bench perpendicular to your body, and while looking away from it, hold on to the bench on its edge with the hands fully extended, separated at shoulder width. The legs will be extended forward, bent at the waist and perpendicular to your torso. This will be your starting position. Slowly lower your body as you inhale by bending at the elbows until you lower yourself far enough to where there is an angle slightly smaller '),
('Bench_Jump', 'Bench Jump', 'legs', ARRAY['legs','legs','legs']::text[], 'bodyweight', 'plyometrics', 'intermediate', 'Begin with a box or bench 1-2 feet in front of you. Stand with your feet shoulder width apart. This will be your starting position. Perform a short squat in preparation for the jump; swing your arms behind you. Rebound out of this position, extending through the hips, knees, and ankles to jump as high as possible. Swing your arms forward and up. Jump over the bench, landing with the knees bent, absorbing the impact through the legs. Turn around and face the opposite direction, then jump back ove'),
('Bench_Press_-_Powerlifting', 'Bench Press - Powerlifting', 'arms', ARRAY['chest','arms','back','shoulders']::text[], 'barbell', 'powerlifting', 'intermediate', 'Begin by lying on the bench, getting your head beyond the bar if possible. Tuck your feet underneath you and arch your back. Using the bar to help support your weight, lift your shoulder off the bench and retract them, squeezing the shoulder blades together. Use your feet to drive your traps into the bench. Maintain this tight body position throughout the movement. However wide your grip, it should cover the ring on the bar. Pull the bar out of the rack without protracting your shoulders. Focus '),
('Bench_Press_-_With_Bands', 'Bench Press - With Bands', 'chest', ARRAY['shoulders','arms']::text[], 'bands', 'strength', 'beginner', 'Using a flat bench secure a band under the leg of the bench that is nearest to your head. Once the band is secure, grab it by both handles and lie down on the bench. Extend your arms so that you are holding the band handles in front of you at shoulder width. Once at shoulder width, rotate your wrists forward so that the palms of your hands are facing away from you. This will be your starting position. Bring down the handles slowly until your elbow forms a 90 degree angle. Keep full control at al'),
('Bench_Press_with_Chains', 'Bench Press with Chains', 'arms', ARRAY['chest','back','shoulders']::text[], 'barbell', 'powerlifting', 'expert', 'Adjust the leader chain, shortening it to the desired length.Place the chains on the sleeves of the bar. Lying on the bench, get your head beyond the bar if possible. Tuck your feet underneath you and arch your back. Using the bar to help support your weight, lift your shoulder off the bench and retract them, squeezing the shoulder blades together. Use your feet to drive your traps into the bench. Maintain this tight body position throughout the movement. However wide your grip, it should cover '),
('Bench_Sprint', 'Bench Sprint', 'legs', ARRAY['legs','legs','legs']::text[], 'other', 'plyometrics', 'beginner', 'Stand on the ground with one foot resting on a bench or box with your heel close to the edge. Push off with your foot on top of the bench, extending through the hip and knee. Land with the opposite foot on top of the box, returning your other foot back to the start position. Continue alternating from one foot to another to complete the set.'),
('Bent-Arm_Barbell_Pullover', 'Bent-Arm Barbell Pullover', 'back', ARRAY['chest','back','shoulders','arms']::text[], 'barbell', 'strength', 'intermediate', 'Lie on a flat bench with a barbell using a shoulder grip width. Hold the bar straight over your chest with a bend in your arms. This will be your starting position. While keeping your arms in the bent arm position, lower the weight slowly in an arc behind your head while breathing in until you feel a stretch on the chest. At that point, bring the barbell back to the starting position using the arc through which the weight was lowered and exhale as you perform this movement. Hold the weight on th'),
('Bent-Arm_Dumbbell_Pullover', 'Bent-Arm Dumbbell Pullover', 'chest', ARRAY['back','shoulders','arms']::text[], 'dumbbell', 'strength', 'intermediate', 'Place a dumbbell standing up on a flat bench. Ensuring that the dumbbell stays securely placed at the top of the bench, lie perpendicular to the bench (torso across it as in forming a cross) with only your shoulders lying on the surface. Hips should be below the bench and legs bent with feet firmly on the floor. The head will be off the bench as well. Grasp the dumbbell with both hands and hold it straight over your chest with a bend in your arms. Both palms should be pressing against the unders'),
('Bent-Knee_Hip_Raise', 'Bent-Knee Hip Raise', 'core', ARRAY[]::text[], 'bodyweight', 'strength', 'beginner', 'Lay flat on the floor with your arms next to your sides. Now bend your knees at around a 75 degree angle and lift your feet off the floor by around 2 inches. Using your lower abs, bring your knees in towards you as you maintain the 75 degree angle bend in your legs. Continue this movement until you raise your hips off of the floor by rolling your pelvis backward. Breathe out as you perform this portion of the movement. Tip: At the end of the movement your knees will be over your chest. Squeeze y'),
('Bent_Over_Barbell_Row', 'Bent Over Barbell Row', 'back', ARRAY['arms','back','shoulders']::text[], 'barbell', 'strength', 'beginner', 'Holding a barbell with a pronated grip (palms facing down), bend your knees slightly and bring your torso forward, by bending at the waist, while keeping the back straight until it is almost parallel to the floor. Tip: Make sure that you keep the head up. The barbell should hang directly in front of you as your arms hang perpendicular to the floor and your torso. This is your starting position. Now, while keeping the torso stationary, breathe out and lift the barbell to you. Keep the elbows clos'),
('Bent_Over_Dumbbell_Rear_Delt_Raise_With_Head_On_Bench', 'Bent Over Dumbbell Rear Delt Raise With Head On Bench', 'shoulders', ARRAY[]::text[], 'dumbbell', 'strength', 'beginner', 'Stand up straight while holding a dumbbell in each hand and with an incline bench in front of you. While keeping your back straight and maintaining the natural arch of your back, lean forward until your forehead touches the bench in front of you. Let the arms hang in front of you perpendicular to the ground. The palms of your hands should be facing each other and your torso should be parallel to the floor. This will be your starting position. Keeping your torso forward and stationary, and the ar'),
('Bent_Over_Low-Pulley_Side_Lateral', 'Bent Over Low-Pulley Side Lateral', 'shoulders', ARRAY['back','back','back']::text[], 'cable', 'strength', 'beginner', 'Select a weight and hold the handle of the low pulley with your right hand. Bend at the waist until your torso is nearly parallel to the floor. Your legs should be slightly bent with your left hand placed on your lower left thigh. Your right arm should be hanging from your shoulder in front of you and with a slight bend at the elbow. This will be your starting position. Raise your right arm, elbow slightly bent, to the side until the arm is parallel to the floor and in line with your right ear. '),
('Bent_Over_One-Arm_Long_Bar_Row', 'Bent Over One-Arm Long Bar Row', 'back', ARRAY['arms','back','back','back']::text[], 'barbell', 'strength', 'beginner', 'Put weight on one of the ends of an Olympic barbell. Make sure that you either place the other end of the barbell in the corner of two walls; or put a heavy object on the ground so the barbell cannot slide backward. Bend forward until your torso is as close to parallel with the floor as you can and keep your knees slightly bent. Now grab the bar with one arm just behind the plates on the side where the weight was placed and put your other hand on your knee. This will be your starting position. P'),
('Bent_Over_Two-Arm_Long_Bar_Row', 'Bent Over Two-Arm Long Bar Row', 'back', ARRAY['arms','back']::text[], 'barbell', 'strength', 'intermediate', 'Put weight on one of the ends of an Olympic barbell. Make sure that you either place the other end of the barbell in the corner of two walls; or put a heavy object on the ground so the barbell cannot slide backward. Bend forward until your torso is as close to parallel with the floor as you can and keep your knees slightly bent. Now grab the bar with both arms just behind the plates on the side where the weight was placed and put your other hand on your knee. This will be your starting position.'),
('Bent_Over_Two-Dumbbell_Row', 'Bent Over Two-Dumbbell Row', 'back', ARRAY['arms','back','shoulders']::text[], 'dumbbell', 'strength', 'beginner', 'With a dumbbell in each hand (palms facing your torso), bend your knees slightly and bring your torso forward by bending at the waist; as you bend make sure to keep your back straight until it is almost parallel to the floor. Tip: Make sure that you keep the head up. The weights should hang directly in front of you as your arms hang perpendicular to the floor and your torso. This is your starting position. While keeping the torso stationary, lift the dumbbells to your side (as you breathe out), '),
('Bent_Over_Two-Dumbbell_Row_With_Palms_In', 'Bent Over Two-Dumbbell Row With Palms In', 'back', ARRAY['arms','back']::text[], 'dumbbell', 'strength', 'beginner', 'With a dumbbell in each hand (palms facing each other), bend your knees slightly and bring your torso forward, by bending at the waist, while keeping the back straight until it is almost parallel to the floor. Tip: Make sure that you keep the head up. The weights should hang directly in front of you as your arms hang perpendicular to the floor and your torso. This is your starting position. While keeping the torso stationary, lift the dumbbells to your side as you breathe out, squeezing your sho'),
('Bent_Press', 'Bent Press', 'core', ARRAY['legs','legs','back','legs','shoulders','arms']::text[], 'kettlebell', 'strength', 'expert', 'Clean a kettlebell to your shoulder. Clean the kettlebell to your shoulders by extending through the legs and hips as you raise the kettlebell towards your shoulder. The wrist should rotate as you do so. This will be your starting position. Begin my leaning to the side opposite the kettlebell, continuing until you are able to touch the ground with your free hand, keeping your eyes on the kettlebell. As you do so, press the weight vertically be extending through the elbow, keeping your arm perpen'),
('Bicycling', 'Bicycling', 'legs', ARRAY['legs','legs','legs']::text[], 'other', 'cardio', 'beginner', 'To begin, seat yourself on the bike and adjust the seat to your height.'),
('Bicycling_Stationary', 'Bicycling, Stationary', 'legs', ARRAY['legs','legs','legs']::text[], 'machine', 'cardio', 'beginner', 'To begin, seat yourself on the bike and adjust the seat to your height. Select the desired option from the menu. You may have to start pedaling to turn it on. You can use the manual setting, or you can select a program to use. Typically, you can enter your age and weight to estimate the amount of calories burned during exercise. The level of resistance can be changed throughout the workout. The handles can be used to monitor your heart rate to help you stay at an appropriate intensity.'),
('Board_Press', 'Board Press', 'arms', ARRAY['chest','arms','back','shoulders']::text[], 'barbell', 'powerlifting', 'intermediate', 'Begin by lying on the bench, getting your head beyond the bar if possible. One to five boards, made out of 2x6''s, can be screwed together and held in place by a training partner, bands, or just tucked under your shirt. Tuck your feet underneath you and arch your back. Using the bar to help support your weight, lift your shoulder off the bench and retract them, squeezing the shoulder blades together. Use your feet to drive your traps into the bench. Maintain this tight body position throughout t'),
('Body-Up', 'Body-Up', 'arms', ARRAY['core','arms']::text[], 'bodyweight', 'strength', 'intermediate', 'Assume a plank position on the ground. You should be supporting your bodyweight on your toes and forearms, keeping your torso straight. Your forearms should be shoulder-width apart. This will be your starting position. Pressing your palms firmly into the ground, extend through the elbows to raise your body from the ground. Keep your torso rigid as you perform the movement. Slowly lower your forearms back to the ground by allowing the elbows to flex. Repeat.'),
('Body_Tricep_Press', 'Body Tricep Press', 'arms', ARRAY[]::text[], 'bodyweight', 'strength', 'beginner', 'Position a bar in a rack at chest height. Standing, take a shoulder width grip on the bar and step a yard or two back, feet together and arms extended so that you are leaning on the bar. This will be your starting position. Begin by flexing the elbow, lowering yourself towards the bar. Pause, and then reverse the motion by extending the elbows. Progress from bodyweight by adding chains over your shoulders.'),
('Bodyweight_Flyes', 'Bodyweight Flyes', 'chest', ARRAY['core','shoulders','arms']::text[], 'barbell', 'strength', 'intermediate', 'Position two equally loaded EZ bars on the ground next to each other. Ensure they are able to roll. Assume a push-up position over the bars, supporting your weight on your toes and hands with your arms extended and body straight. Place your hands on the bars. This will be your starting position. Using a slow and controlled motion, move your hands away from the midline of your body, rolling the bars apart. Inhale during this portion of the motion. After moving the bars as far apart as you can, re'),
('Bodyweight_Mid_Row', 'Bodyweight Mid Row', 'back', ARRAY['arms','back']::text[], 'other', 'strength', 'intermediate', 'Begin by taking a medium to wide grip on a pull-up apparatus with your palms facing away from you. From a hanging position, tuck your knees to your chest, leaning back and getting your legs over your side of the pull-up apparatus. This will be your starting position. Beginning with your arms straight, flex the elbows and retract the shoulder blades to raise your body up until your legs contact the pull-up apparatus. After a brief pause, return to the starting position.'),
('Bodyweight_Squat', 'Bodyweight Squat', 'legs', ARRAY['legs','legs']::text[], 'bodyweight', 'strength', 'beginner', 'Stand with your feet shoulder width apart. You can place your hands behind your head. This will be your starting position. Begin the movement by flexing your knees and hips, sitting back with your hips. Continue down to full depth if you are able,and quickly reverse the motion until you return to the starting position. As you squat, keep your head and chest up and push your knees out.'),
('Bodyweight_Walking_Lunge', 'Bodyweight Walking Lunge', 'legs', ARRAY['legs','legs','legs']::text[], 'other', 'strength', 'beginner', 'Begin standing with your feet shoulder width apart and your hands on your hips. Step forward with one leg, flexing the knees to drop your hips. Descend until your rear knee nearly touches the ground. Your posture should remain upright, and your front knee should stay above the front foot. Drive through the heel of your lead foot and extend both knees to raise yourself back up. Step forward with your rear foot, repeating the lunge on the opposite leg.'),
('Bosu_Ball_Cable_Crunch_With_Side_Bends', 'Bosu Ball Cable Crunch With Side Bends', 'core', ARRAY[]::text[], 'cable', 'strength', 'beginner', 'Connect a standard handle to each arm of a cable machine, and position them in the most downward position. Grab a Bosu Ball and position it in front and center of the cable machine. Lie down on the Bosu Ball with the small of your back arched around the ball. Your rear end should be close to the floor without touching it. With both hands, reach back and grab the handle of each cable. With your feet positioned in a wide stance, extend your arms straight out in front of you and in between your kne'),
('Bottoms-Up_Clean_From_The_Hang_Position', 'Bottoms-Up Clean From The Hang Position', 'arms', ARRAY['arms','shoulders']::text[], 'kettlebell', 'strength', 'intermediate', 'Initiate the exercise by standing upright with a kettlebell in one hand. Swing the kettlebell back forcefully and then reverse the motion forcefully. Crush the kettlebell handle as hard as possible and raise the kettlebell to your shoulder.'),
('Bottoms_Up', 'Bottoms Up', 'core', ARRAY[]::text[], 'bodyweight', 'strength', 'beginner', 'Begin by lying on your back on the ground. Your legs should be straight and your arms at your side. This will be your starting position. To perform the movement, tuck the knees toward your chest by flexing the hips and knees. Following this, extend your legs directly above you so that they are perpendicular to the ground. Rotate and elevate your pelvis to raise your glutes from the floor. After a brief pause, return to the starting position.'),
('Box_Jump_Multiple_Response', 'Box Jump (Multiple Response)', 'legs', ARRAY['legs','legs','legs','legs','legs']::text[], 'other', 'plyometrics', 'beginner', 'Assume a relaxed stance facing the box or platform approximately an arm''s length away. Arms should be down at the sides and legs slightly bent. Using the arms to aid in the initial burst, jump upward and forward, landing with feet simultaneously on top of the box or platform. Immediately drop or jump back down to the original starting place; then repeat the sequence.')
INSERT INTO exercises (external_id, name, muscle_group, secondary_muscles, equipment, category, level, instructions) VALUES
('Box_Skip', 'Box Skip', 'legs', ARRAY['legs','legs','legs','legs','legs']::text[], 'other', 'plyometrics', 'beginner', 'You will need several boxes lined up about 8 feet apart. Begin facing the first box with one leg slightly behind the other. Drive off the back leg, attempting to gain as much height with the hips as possible. Immediately upon landing on the box, drive the other leg forward and upward to gain height and distance, leaping from the box. Land between the first two boxes with the same leg that landed on the first box. Then, step to the next box and repeat.'),
('Box_Squat', 'Box Squat', 'legs', ARRAY['legs','legs','legs','legs','back']::text[], 'barbell', 'powerlifting', 'intermediate', 'The box squat allows you to squat to desired depth and develop explosive strength in the squat movement. Begin in a power rack with a box at the appropriate height behind you. Typically, you would aim for a box height that brings you to a parallel squat, but you can train higher or lower if desired. Begin by stepping under the bar and placing it across the back of the shoulders. Squeeze your shoulder blades together and rotate your elbows forward, attempting to bend the bar across your shoulders'),
('Box_Squat_with_Bands', 'Box Squat with Bands', 'legs', ARRAY['legs','legs','legs','legs','legs','back']::text[], 'barbell', 'powerlifting', 'expert', 'Begin in a power rack with a box at the appropriate height behind you. Set up the bands on the sleeves, secured to either band pegs, the rack, or dumbbells so that there is appropriate tension. If dumbbells are used, secure them so that they don''t move. Also, ensure that the dumbbells you are using are heavy enough for the bands that you are using. Additional plates can be used to hold the dumbbells down. If more tension is needed, you can either widen the base on the floor or choke the bands. '),
('Box_Squat_with_Chains', 'Box Squat with Chains', 'legs', ARRAY['legs','legs','legs','legs','legs','back']::text[], 'barbell', 'strength', 'expert', 'Begin in a power rack with a box at the appropriate height behind you. Typically, you would aim for a box height that brings you to a parallel squat, but you can train higher or lower if desired. To set up the chains, begin by looping the leader chain over the sleeves of the bar. The heavy chain should be attached using a snap hook. Adjust the length of the lead chain so that a few links are still on the floor at the top of the movement. Begin by stepping under the bar and placing it across the '),
('Brachialis-SMR', 'Brachialis-SMR', 'arms', ARRAY[]::text[], 'other', 'stretching', 'intermediate', 'Lie on your side, with your upper arm against the foam roller. The upper arm should be more or less aligned with your body, with the outside of the bicep pressed against the foam roller. Raise your hips off of the floor, supporting your weight on your arm and on your feet. Hold for 10-30 seconds, and then switch sides.'),
('Bradford_Rocky_Presses', 'Bradford/Rocky Presses', 'shoulders', ARRAY['arms']::text[], 'barbell', 'strength', 'beginner', 'Sit on a Military Press Bench with a bar at shoulder level with a pronated grip (palms facing forward). Tip: Your grip should be wider than shoulder width and it should create a 90-degree angle between the forearm and the upper arm as the barbell goes down. This is your starting position. Once you pick up the barbell with the correct grip, lift the bar up over your head by locking your arms. Now lower the bar down to the back of the head slowly as you inhale. Lift the bar back up to the starting'),
('Butt-Ups', 'Butt-Ups', 'core', ARRAY[]::text[], 'bodyweight', 'strength', 'beginner', 'Begin a pushup position but with your elbows on the ground and resting on your forearms. Your arms should be bent at a 90 degree angle. Arch your back slightly out rather than keeping your back completely straight. Raise your glutes toward the ceiling, squeezing your abs tightly to close the distance between your ribcage and hips. The end result will be that you''ll end up in a high bridge position. Exhale as you perform this portion of the movement. Lower back down slowly to your starting posit'),
('Butt_Lift_Bridge', 'Butt Lift (Bridge)', 'legs', ARRAY['legs']::text[], 'bodyweight', 'strength', 'beginner', 'Lie flat on the floor on your back with the hands by your side and your knees bent. Your feet should be placed around shoulder width. This will be your starting position. Pushing mainly with your heels, lift your hips off the floor while keeping your back straight. Breathe out as you perform this part of the motion and hold at the top for a second. Slowly go back to the starting position as you breathe in.'),
('Butterfly', 'Butterfly', 'chest', ARRAY[]::text[], 'machine', 'strength', 'beginner', 'Sit on the machine with your back flat on the pad. Take hold of the handles. Tip: Your upper arms should be positioned parallel to the floor; adjust the machine accordingly. This will be your starting position. Push the handles together slowly as you squeeze your chest in the middle. Breathe out during this part of the motion and hold the contraction for a second. Return back to the starting position slowly as you inhale until your chest muscles are fully stretched. Repeat for the recommended am'),
('Cable_Chest_Press', 'Cable Chest Press', 'chest', ARRAY['shoulders','arms']::text[], 'cable', 'strength', 'beginner', 'Adjust the weight to an appropriate amount and be seated, grasping the handles. Your upper arms should be about 45 degrees to the body, with your head and chest up. The elbows should be bent to about 90 degrees. This will be your starting position. Begin by extending through the elbow, pressing the handles together straight in front of you. Keep your shoulder blades retracted as you execute the movement. After pausing at full extension, return to th starting position, keeping tension on the cabl'),
('Cable_Crossover', 'Cable Crossover', 'chest', ARRAY['shoulders']::text[], 'cable', 'strength', 'beginner', 'To get yourself into the starting position, place the pulleys on a high position (above your head), select the resistance to be used and hold the pulleys in each hand. Step forward in front of an imaginary straight line between both pulleys while pulling your arms together in front of you. Your torso should have a small forward bend from the waist. This will be your starting position. With a slight bend on your elbows in order to prevent stress at the biceps tendon, extend your arms to the side '),
('Cable_Crunch', 'Cable Crunch', 'core', ARRAY[]::text[], 'cable', 'strength', 'beginner', 'Kneel below a high pulley that contains a rope attachment. Grasp cable rope attachment and lower the rope until your hands are placed next to your face. Flex your hips slightly and allow the weight to hyperextend the lower back. This will be your starting position. With the hips stationary, flex the waist as you contract the abs so that the elbows travel towards the middle of the thighs. Exhale as you perform this portion of the movement and hold the contraction for a second. Slowly return to th'),
('Cable_Deadlifts', 'Cable Deadlifts', 'legs', ARRAY['arms','legs','legs','back']::text[], 'cable', 'strength', 'beginner', 'Move the cables to the bottom of the towers and select an appropriate weight. Stand directly in between the uprights. To begin, squat down be flexing your hips and knees until you can reach the handles. After grasping them, begin your ascent. Driving through your heels extend your hips and knees keeping your hands hanging at your side. Keep your head and chest up throughout the movement. After reaching a full standing position, Return to the starting position and repeat.'),
('Cable_Hammer_Curls_-_Rope_Attachment', 'Cable Hammer Curls - Rope Attachment', 'arms', ARRAY[]::text[], 'cable', 'strength', 'beginner', 'Attach a rope attachment to a low pulley and stand facing the machine about 12 inches away from it. Grasp the rope with a neutral (palms-in) grip and stand straight up keeping the natural arch of the back and your torso stationary. Put your elbows in by your side and keep them there stationary during the entire movement. Tip: Only the forearms should move; not your upper arms. This will be your starting position. Using your biceps, pull your arms up as you exhale until your biceps touch your for'),
('Cable_Hip_Adduction', 'Cable Hip Adduction', 'legs', ARRAY[]::text[], 'cable', 'strength', 'beginner', 'Stand in front of a low pulley facing forward with one leg next to the pulley and the other one away. Attach the ankle cuff to the cable and also to the ankle of the leg that is next to the pulley. Now step out and away from the stack with a wide stance and grasp the bar of the pulley system. Stand on the foot that does not have the ankle cuff (the far foot) and allow the leg with the cuff to be pulled towards the low pulley. This will be your starting position. Now perform the movement by movin'),
('Cable_Incline_Pushdown', 'Cable Incline Pushdown', 'back', ARRAY[]::text[], 'cable', 'strength', 'beginner', 'Lie on incline an bench facing away from a high pulley machine that has a straight bar attachment on it. Grasp the straight bar attachment overhead with a pronated (overhand; palms down) shoulder width grip and extend your arms in front of you. The bar should be around 2 inches away from your upper thighs. This will be your starting position. Keeping the upper arms stationary, lift your arms back in a semi circle until the bar is straight over your head. Breathe in during this portion of the mov'),
('Cable_Incline_Triceps_Extension', 'Cable Incline Triceps Extension', 'arms', ARRAY[]::text[], 'cable', 'strength', 'beginner', 'Lie on incline an bench facing away from a high pulley machine that has a straight bar attachment on it. Grasp the straight bar attachment overhead with a pronated (overhand; palms down) narrow grip (less than shoulder width) and keep your elbows tucked in to your sides. Your upper arms should create around a 25 degree angle when measured from the floor. Keeping the upper arms stationary, extend the arms as you flex the triceps. Breathe out during this portion of the movement and hold the contra'),
('Cable_Internal_Rotation', 'Cable Internal Rotation', 'shoulders', ARRAY[]::text[], 'cable', 'strength', 'beginner', 'Sit next to a low pulley sideways (with legs stretched in front of you or crossed) and grasp the single hand cable attachment with the arm nearest to the cable. Tip: If you can adjust the pulley''s height, you can use a flat bench to sit on instead. Position the elbow against your side with the elbow bent at 90° and the arm pointing towards the pulley. This will be your starting position. Pull the single hand cable attachment toward your body by internally rotating your shoulder until your forea'),
('Cable_Iron_Cross', 'Cable Iron Cross', 'chest', ARRAY[]::text[], 'cable', 'strength', 'beginner', 'Begin by moving the pulleys to the high position, select the resistance to be used, and take a handle in each hand. Stand directly between both pulleys with your arms extended out to your sides. Your head and chest should be up while your arms form a "T". This will be your starting position. Keeping the elbows extended, pull your arms straight to your sides. Return your arms back to the starting position after a pause at the peak contraction. Continue the movement for the prescribed number of re'),
('Cable_Judo_Flip', 'Cable Judo Flip', 'core', ARRAY[]::text[], 'cable', 'strength', 'beginner', 'Connect a rope attachment to a tower, and move the cable to the lowest pulley position. Stand with your side to the cable with a wide stance, and grab the rope with both hands. Twist your body away from the pulley as you bring the rope over your shoulder like you''re performing a judo flip. Shift your weight between your feet as you twist and crunch forward, pulling the cable downward. Return to the starting position and repeat until failure. Then, reposition and repeat the same series of moveme'),
('Cable_Lying_Triceps_Extension', 'Cable Lying Triceps Extension', 'arms', ARRAY[]::text[], 'cable', 'strength', 'beginner', 'Lie on a flat bench and grasp the straight bar attachment of a low pulley with a narrow overhand grip. Tip: The easiest way to do this is to have someone hand you the bar as you lay down. With your arms extended, position the bar over your torso. Your arms and your torso should create a 90-degree angle. This will be your starting position. Lower the bar by bending at the elbow while keeping the upper arms stationary and elbows in. Go down until the bar lightly touches your forehead. Breathe in a'),
('Cable_One_Arm_Tricep_Extension', 'Cable One Arm Tricep Extension', 'arms', ARRAY[]::text[], 'cable', 'strength', 'beginner', 'With your right hand, grasp a single handle attached to the high-cable pulley using a supinated (underhand; palms facing up) grip. You should be standing directly in front of the weight stack. Now pull the handle down so that your upper arm and elbow are locked in to the side of your body. Your upper arm and forearm should form an acute angle (less than 90-degrees). You can keep the other arm by the waist and you can have one leg in front of you and the other one back for better balance. This wi'),
('Cable_Preacher_Curl', 'Cable Preacher Curl', 'arms', ARRAY['arms']::text[], 'cable', 'strength', 'beginner', 'Place a preacher bench about 2 feet in front of a pulley machine. Attach a straight bar to the low pulley. Sit at the preacher bench with your elbow and upper arms firmly on top of the bench pad and have someone hand you the bar from the low pulley. Grab the bar and fully extend your arms on top of the preacher bench pad. This will be your starting position. Now start pilling the weight up towards your shoulders and squeeze the biceps hard at the top of the movement. Exhale as you perform this m'),
('Cable_Rear_Delt_Fly', 'Cable Rear Delt Fly', 'shoulders', ARRAY[]::text[], 'cable', 'strength', 'beginner', 'Adjust the pulleys to the appropriate height and adjust the weight. The pulleys should be above your head. Grab the left pulley with your right hand and the right pulley with your left hand, crossing them in front of you. This will be your starting position. Initiate the movement by moving your arms back and outward, keeping your arms straight as you execute the movement. Pause at the end of the motion before returning the handles to the start position.'),
('Cable_Reverse_Crunch', 'Cable Reverse Crunch', 'core', ARRAY[]::text[], 'cable', 'strength', 'beginner', 'Connect an ankle strap attachment to a low pulley cable and position a mat on the floor in front of it. Sit down with your feet toward the pulley and attach the cable to your ankles. Lie down, elevate your legs and bend your knees at a 90-degree angle. Your legs and the cable should be aligned. If not, adjust the pulley up or down until they are. With your hands behind your head, bring your knees inward to your torso and elevate your hips off the floor. Pause for a moment and in a slow and contr'),
('Cable_Rope_Overhead_Triceps_Extension', 'Cable Rope Overhead Triceps Extension', 'arms', ARRAY[]::text[], 'cable', 'strength', 'beginner', 'Attach a rope to the bottom pulley of the pulley machine. Grasping the rope with both hands, extend your arms with your hands directly above your head using a neutral grip (palms facing each other). Your elbows should be in close to your head and the arms should be perpendicular to the floor with the knuckles aimed at the ceiling. This will be your starting position. Slowly lower the rope behind your head as you hold the upper arms stationary. Inhale as you perform this movement and pause when y'),
('Cable_Rope_Rear-Delt_Rows', 'Cable Rope Rear-Delt Rows', 'shoulders', ARRAY['arms','back']::text[], 'cable', 'strength', 'beginner', 'Sit in the same position on a low pulley row station as you would if you were doing seated cable rows for the back. Attach a rope to the pulley and grasp it with an overhand grip. Your arms should be extended and parallel to the floor with the elbows flared out. Keep your lower back upright and slide your hips back so that your knees are slightly bent. This will be your starting position. Pull the cable attachment towards your upper chest, just below the neck, as you keep your elbows up and out '),
('Cable_Russian_Twists', 'Cable Russian Twists', 'core', ARRAY[]::text[], 'cable', 'strength', 'beginner', 'Connect a standard handle attachment, and position the cable to a middle pulley position. Lie on a stability ball perpendicular to the cable and grab the handle with one hand. You should be approximately arm''s length away from the pulley, with the tension of the weight on the cable. Grab the handle with both hands and fully extend your arms above your chest. You hands should be directly in-line with the pulley. If not, adjust the pulley up or down until they are. Keep your hips elevated and abs'),
('Cable_Seated_Crunch', 'Cable Seated Crunch', 'core', ARRAY[]::text[], 'cable', 'strength', 'beginner', 'Seat on a flat bench with your back facing a high pulley. Grasp the cable rope attachment with both hands (with the palms of the hands facing each other) and place your hands securely over both shoulders. Tip: Allow the weight to hyperextend the lower back slightly. This will be your starting position. With the hips stationary, flex the waist so the elbows travel toward the hips. Breathe out as you perform this step. As you inhale, go back to the initial position slowly. Repeat for the recommend'),
('Cable_Seated_Lateral_Raise', 'Cable Seated Lateral Raise', 'shoulders', ARRAY['back','back']::text[], 'cable', 'strength', 'beginner', 'Stand in the middle of two low pulleys that are opposite to each other and place a flat bench right behind you (in perpendicular fashion to you; the narrow edge of the bench should be the one behind you). Select the weight to be used on each pulley. Now sit at the edge of the flat bench behind you with your feet placed in front of your knees. Bend forward while keeping your back flat and rest your torso on the thighs. Have someone give you the single handles attached to the pulleys. Grasp the le'),
('Cable_Shoulder_Press', 'Cable Shoulder Press', 'shoulders', ARRAY['arms']::text[], 'cable', 'strength', 'beginner', 'Move the cables to the bottom of the towers and select an appropriate weight. Stand directly in between the uprights. Grasp the cables and hold them at shoulder height, palms facing forward. This will be your starting position. Keeping your head and chest up, extend through the elbow to press the handles directly over head. After pausing at the top, return to the starting position and repeat.'),
('Cable_Shrugs', 'Cable Shrugs', 'back', ARRAY[]::text[], 'cable', 'strength', 'beginner', 'Grasp a cable bar attachment that is attached to a low pulley with a shoulder width or slightly wider overhand (palms facing down) grip. Stand erect close to the pulley with your arms extended in front of you holding the bar. This will be your starting position. Lift the bar by elevating the shoulders as high as possible as you exhale. Hold the contraction at the top for a second. Tip: The arms should remain extended at all times. Refrain from using the biceps to help lift the bar. Only the shou'),
('Cable_Wrist_Curl', 'Cable Wrist Curl', 'arms', ARRAY[]::text[], 'cable', 'strength', 'beginner', 'Start out by placing a flat bench in front of a low pulley cable that has a straight bar attachment. Use your arms to grab the cable bar with a narrow to shoulder width supinated grip (palms up) and bring them up so that your forearms are resting against the top of your thighs. Your wrists should be hanging just beyond your knees. Start out by curling your wrist upwards and exhaling. Keep the contraction for a second. Slowly lower your wrists back down to the starting position while inhaling. Yo'),
('Calf-Machine_Shoulder_Shrug', 'Calf-Machine Shoulder Shrug', 'back', ARRAY[]::text[], 'machine', 'strength', 'beginner', 'Position yourself on the calf machine so that the shoulder pads are above your shoulders. Your torso should be straight with the arms extended normally by your side. This will be your starting position. Raise your shoulders up towards your ears as you exhale and hold the contraction for a full second. Slowly return to the starting position as you inhale. Repeat for the recommended amount of repetitions.'),
('Calf_Press', 'Calf Press', 'legs', ARRAY[]::text[], 'machine', 'strength', 'beginner', 'Adjust the seat so that your legs are only slightly bent in the start position. The balls of your feet should be firmly on the platform. Select an appropriate weight, and grasp the handles. This will be your starting position. Straighten the legs by extending the knees, just barely lifting the weight from the stack. Your ankle should be fully flexed, toes pointing up. Execute the movement by pressing downward through the balls of your feet as far as possible. After a brief pause, reverse the mot'),
('Calf_Press_On_The_Leg_Press_Machine', 'Calf Press On The Leg Press Machine', 'legs', ARRAY[]::text[], 'machine', 'strength', 'beginner', 'Using a leg press machine, sit down on the machine and place your legs on the platform directly in front of you at a medium (shoulder width) foot stance. Lower the safety bars holding the weighted platform in place and press the platform all the way up until your legs are fully extended in front of you without locking your knees. (Note: In some leg press units you can leave the safety bars on for increased safety. If your leg press unit allows for this, then this is the preferred method of perfo'),
('Calf_Raise_On_A_Dumbbell', 'Calf Raise On A Dumbbell', 'legs', ARRAY[]::text[], 'dumbbell', 'strength', 'intermediate', 'Hang on to a sturdy object for balance and stand on a dumbbell handle, preferably one with round plates so that it rolls as in this manner you have to work harder to stabilize yourself; thus increasing the effectiveness of the exercise. Now roll your foot slightly forward so that you can get a nice stretch of the calf. This will be your starting position. Lift the calf as you roll your foot over the top of the handle so that you get a full extension. Exhale during the execution of this movement.'),
('Calf_Raises_-_With_Bands', 'Calf Raises - With Bands', 'legs', ARRAY[]::text[], 'bands', 'strength', 'beginner', 'Grab an exercise band and stand on it with your toes making sure that the length of the band between the foot and the arms is the same for both sides. While holding the handles of the band, raise the arms to the side of your head as if you were getting ready to perform a shoulder press. The palms should be facing forward with the elbows bent and to the sides. This movement will create tension on the band. This will be your starting position. Keeping the hands by your shoulder, stand up on your t'),
('Calf_Stretch_Elbows_Against_Wall', 'Calf Stretch Elbows Against Wall', 'legs', ARRAY[]::text[], 'other', 'stretching', 'beginner', 'Stand facing a wall from a couple feet away. Lean against the wall, placing your weight on your forearms. Attempt to keep your heels on the ground. Hold for 10-20 seconds. You may move further or closer the wall, making it more or less difficult, respectively.'),
('Calf_Stretch_Hands_Against_Wall', 'Calf Stretch Hands Against Wall', 'legs', ARRAY[]::text[], 'other', 'stretching', 'beginner', 'Stand facing a wall from several feet away. Stagger your stance, placing one foot forward. Lean forward and rest your hands on the wall, keeping your heel, hip and head in a straight line. Attempt to keep your heel on the ground. Hold for 10-20 seconds and then switch sides.'),
('Calves-SMR', 'Calves-SMR', 'legs', ARRAY[]::text[], 'other', 'stretching', 'intermediate', 'Begin seated on the floor. Place a foam roller underneath your lower leg. Your other leg can either be crossed over the opposite or be placed on the floor, supporting some of your weight. This will be your starting position. Place your hands to your side or just behind you, and press down to raise your hips off of the floor, placing much of your weight against your calf muscle. Roll from below the knee to above the ankle, pausing at points of tension for 10-30 seconds. Repeat for the other leg.'),
('Car_Deadlift', 'Car Deadlift', 'legs', ARRAY['arms','legs','legs','back','back']::text[], 'other', 'strongman', 'intermediate', 'This event apparatus typically has neutral grip handles, however some have a straight bar that you can approach like a normal deadlift. The apparatus can be loaded with a vehicle or other heavy objects such as tractor tires or kegs. Center yourself between the handles if you are a strong squatter, or back a couple inches if you are a strong deadlifter. You feet should be about hip width apart. Bend at the hip to grip the handles. With your feet and your grip set, take a big breath and then lower'),
('Car_Drivers', 'Car Drivers', 'shoulders', ARRAY['arms']::text[], 'barbell', 'strength', 'beginner', 'While standing upright, hold a barbell plate in both hands at the 3 and 9 o''clock positions. Your palms should be facing each other and your arms should be extended straight out in front of you. This will be your starting position. Initiate the movement by rotating the plate as far to one side as possible. Use the same type of movement you would use to turn a steering wheel to one side. Reverse the motion, turning it all the way to the opposite side. Repeat for the recommended amount of repetit'),
('Carioca_Quick_Step', 'Carioca Quick Step', 'legs', ARRAY['core','legs','legs','legs','legs','legs']::text[], 'other', 'plyometrics', 'beginner', 'Begin with your feet a few inches apart and your left arm up in a relaxed, athletic position. With your right foot, quick step behind and pull the knee up. Fire your arms back up when you pull the right knee, being sure that your knee goes straight up and down. Avoid turning your feet as you move and continue to look forward as you move to the side.'),
('Cat_Stretch', 'Cat Stretch', 'back', ARRAY['back','back']::text[], 'other', 'stretching', 'beginner', 'Position yourself on the floor on your hands and knees. Pull your belly in and round your spine, lower back, shoulders, and neck, letting your head drop. Hold for 15 seconds.'),
('Catch_and_Overhead_Throw', 'Catch and Overhead Throw', 'back', ARRAY['core','chest','shoulders']::text[], 'other', 'plyometrics', 'beginner', 'Begin standing while facing a wall or a partner. Using both hands, position the ball behind your head, stretching as much as possible, and forcefully throw the ball forward. Ensure that you follow your throw through, being prepared to receive your rebound from your throw. If you are throwing against the wall, make sure that you stand close enough to the wall to receive the rebound, and aim a little higher than you would with a partner.'),
('Chain_Handle_Extension', 'Chain Handle Extension', 'arms', ARRAY[]::text[], 'other', 'powerlifting', 'intermediate', 'You will need two cable handle attachments and a flat bench, as well as chains, for this exercise. Clip the middle of the chains to the handles, and position yourself on the flat bench. Your elbows should be pointing straight up. Begin by extending through the elbow, keeping your upper arm still, with your wrists pronated. Pause at the lockout, and reverse the motion to return to the starting position.'),
('Chain_Press', 'Chain Press', 'chest', ARRAY['shoulders','arms']::text[], 'other', 'powerlifting', 'intermediate', 'Begin by connecting the chains to the cable handle attachments. Position yourself on the flat bench in the same position as for a dumbbell press. Your wrists should be pronated and arms perpendicular to the floor. This will be your starting position. Lower the chains by flexing the elbows, unloading some of the chain onto the floor. Continue until your elbow forms a 90 degree angle, and then reverse the motion by extending through the elbow to lockout.'),
('Chair_Leg_Extended_Stretch', 'Chair Leg Extended Stretch', 'legs', ARRAY['legs']::text[], 'other', 'stretching', 'beginner', 'Sit upright in a chair and grip the seat on the sides. Raise one leg, extending the knee, flexing the ankle as you do so. Slowly move that leg outward as far as you can, and then back to the center and down. Repeat for your other leg.'),
('Chair_Lower_Back_Stretch', 'Chair Lower Back Stretch', 'back', ARRAY['back']::text[], 'other', 'stretching', 'beginner', 'Sit upright on a chair. Bend to one side with your arm over your head. You can hold onto the chair with your free hand. Hold for 10 seconds, and repeat for your other side.')
INSERT INTO exercises (external_id, name, muscle_group, secondary_muscles, equipment, category, level, instructions) VALUES
('Chair_Squat', 'Chair Squat', 'legs', ARRAY['legs','legs','legs']::text[], 'machine', 'strength', 'beginner', 'To begin, first set the bar to a position that best matches your height. Once the bar is loaded, step under it and position it across the back of your shoulders. Take the bar with your hands facing forward, unlock it and lift it off the rack by extending your legs. Move your feet forward about 18 inches in front of the bar. Position your legs using a shoulder width stance with the toes slightly pointed out. Look forward at all times and maintain a neutral or slightly arched spine. This will be y'),
('Chair_Upper_Body_Stretch', 'Chair Upper Body Stretch', 'shoulders', ARRAY['arms','chest']::text[], 'other', 'stretching', 'beginner', 'Sit on the edge of a chair, gripping the back of it. Straighten your arms, keeping your back straight, and pull your upper body forward so you feel a stretch. Hold for 20-30 seconds.'),
('Chest_And_Front_Of_Shoulder_Stretch', 'Chest And Front Of Shoulder Stretch', 'chest', ARRAY['shoulders']::text[], 'other', 'stretching', 'beginner', 'Start off by standing with your legs together, holding a bodybar or a broomstick. Take a slightly wider than shoulder width grip on the pole and hold it in front of you with your palms facing down. Carefully lift the pole up and behind your head.'),
('Chest_Push_from_3_point_stance', 'Chest Push from 3 point stance', 'chest', ARRAY['core','shoulders','arms']::text[], 'other', 'plyometrics', 'beginner', 'Begin in a three point stance, squatted down with your back flat and one hand on the ground. Place the medicine ball directly in front of you. To begin, take your first step as you pull the ball to your chest, positioning both hands to prepare for the throw. As you execute the second step, explosively release the ball forward as hard as possible.'),
('Chest_Push_multiple_response', 'Chest Push (multiple response)', 'chest', ARRAY['core','shoulders','arms']::text[], 'other', 'plyometrics', 'beginner', 'Begin in a kneeling position facing a wall or utilize a partner. Hold the ball with both hands tight into the chest. Execute the pass by exploding forward and outward with the hips while pushing the ball as hard as possible. Follow through by falling forward, catching yourself with your hands. Immediately return to an upright position. Repeat for the desired number of repetitions.'),
('Chest_Push_single_response', 'Chest Push (single response)', 'chest', ARRAY['core','shoulders','arms']::text[], 'other', 'plyometrics', 'beginner', 'Begin in a kneeling position holding the medicine ball with both hands tightly into the chest. Execute the pass by exploding forward and outward with the hips while pushing the ball as far as possible. Follow through by falling forward, catching yourself with your hands.'),
('Chest_Push_with_Run_Release', 'Chest Push with Run Release', 'chest', ARRAY['core','shoulders','arms']::text[], 'other', 'plyometrics', 'beginner', 'Begin in an athletic stance with the knees bent, hips back, and back flat. Hold the medicine ball near your legs. This will be your starting position. While taking your first step draw the medicine ball into your chest. As you take the second step, explosively push the ball forward, immediately sprinting for 10 yards after the release. If you are really fast, you can catch your own pass!'),
('Chest_Stretch_on_Stability_Ball', 'Chest Stretch on Stability Ball', 'chest', ARRAY[]::text[], 'other', 'stretching', 'beginner', 'Get on your hands and knees next to an exercise ball. Place your elbows on top of the ball, keeping your arm out to your side. This will be your starting position. Lower your torso towards the floor, keeping your elbow on top of the ball. Hold the stretch for 20-30 seconds, and repeat with the other arm.'),
('Childs_Pose', 'Child''s Pose', 'back', ARRAY['legs','back']::text[], 'other', 'stretching', 'beginner', 'Get on your hands and knees, walk your hands in front of you. Lower your buttocks down to sit on your heels. Let your arms drag along the floor as you sit back to stretch your entire spine. Once you settle onto your heels, bring your hands next to your feet and relax. "breathe" into your back. Rest your forehead on the floor. Avoid this position if you have knee problems.'),
('Chin-Up', 'Chin-Up', 'back', ARRAY['arms','arms','back']::text[], 'bodyweight', 'strength', 'beginner', 'Grab the pull-up bar with the palms facing your torso and a grip closer than the shoulder width. As you have both arms extended in front of you holding the bar at the chosen grip width, keep your torso as straight as possible while creating a curvature on your lower back and sticking your chest out. This is your starting position. Tip: Keeping the torso as straight as possible maximizes biceps stimulation while minimizing back involvement. As you breathe out, pull your torso up until your head i'),
('Chin_To_Chest_Stretch', 'Chin To Chest Stretch', 'other', ARRAY['back']::text[], 'other', 'stretching', 'beginner', 'Get into a seated position on the floor. Place both hands at the rear of your head, fingers interlocked, thumbs pointing down and elbows pointing straight ahead. Slowly pull your head down to your chest. Hold for 20-30 seconds.'),
('Circus_Bell', 'Circus Bell', 'shoulders', ARRAY['arms','legs','legs','back','back','arms']::text[], 'other', 'strongman', 'expert', 'The circus bell is an oversized dumbbell with a thick handle. Begin with the dumbbell between your feet, and grip the handle with both hands. Clean the dumbbell by extending through your hips and knees to deliver the implement to the desired shoulder, letting go with the extra hand. Ensure that you get one of the dumbbell heads behind the shoulder to keep from being thrown off balance. To raise it overhead, dip by flexing the knees, and the drive upwards as you extend the dumbbell overhead, lean'),
('Clean', 'Clean', 'legs', ARRAY['legs','arms','legs','back','legs','shoulders','back']::text[], 'barbell', 'olympic weightlifting', 'intermediate', 'With a barbell on the floor close to the shins, take an overhand (or hook) grip just outside the legs. Lower your hips with the weight focused on the heels, back straight, head facing forward, chest up, with your shoulders just in front of the bar. This will be your starting position.  Begin the first pull by driving through the heels, extending your knees. Your back angle should stay the same, and your arms should remain straight. Move the weight with control as you continue to above the knees.'),
('Clean_Deadlift', 'Clean Deadlift', 'legs', ARRAY['arms','legs','back','back','legs','back']::text[], 'barbell', 'olympic weightlifting', 'beginner', 'Begin standing with a barbell close to your shins. Your feet should be directly under your hips with your feet turned out slightly. Grip the bar with a double overhand grip or hook grip, about shoulder width apart. Squat down to the bar. Your spine should be in full extension, with a back angle that places your shoulders in front of the bar and your back as vertical as possible. Begin by driving through the floor through the front of your heels. As the bar travels upward, maintain a constant bac'),
('Clean_Pull', 'Clean Pull', 'legs', ARRAY['arms','legs','legs','back','back']::text[], 'barbell', 'olympic weightlifting', 'intermediate', 'With a barbell on the floor close to the shins, take an overhand or hook grip just outside the legs. Lower your hips with the weight focused on the heels, back straight, head facing forward, chest up, with your shoulders just in front of the bar. This will be your starting position. Begin the first pull by driving through the heels, extending your knees. Your back angle should stay the same, and your arms should remain straight and elbows out. Move the weight with control as you continue to abov'),
('Clean_Shrug', 'Clean Shrug', 'back', ARRAY['arms','shoulders']::text[], 'barbell', 'olympic weightlifting', 'beginner', 'Begin with a shoulder width, double overhand or hook grip, with the bar hanging at the mid thigh position. Your back should be straight and inclined slightly forward. Shrug your shoulders towards your ears. While this exercise can usually by loaded with heavier weight than a clean, avoid overloading to the point that the execution slows down.'),
('Clean_and_Jerk', 'Clean and Jerk', 'shoulders', ARRAY['core','legs','legs','back','legs','back','arms']::text[], 'barbell', 'olympic weightlifting', 'expert', 'With a barbell on the floor close to the shins, take an overhand or hook grip just outside the legs. Lower your hips with the weight focused on the heels, back straight, head facing forward, chest up, with your shoulders just in front of the bar. This will be your starting position. Begin the first pull by driving through the heels, extending your knees. Your back angle should stay the same, and your arms should remain straight. Move the weight with control as you continue to above the knees. Ne'),
('Clean_and_Press', 'Clean and Press', 'shoulders', ARRAY['core','legs','legs','legs','back','back','legs','shoulders','back','arms']::text[], 'barbell', 'strength', 'intermediate', 'Assume a shoulder-width stance, with knees inside the arms. Now while keeping the back flat, bend at the knees and hips so that you can grab the bar with the arms fully extended and a pronated grip that is slightly wider than shoulder width. Point the elbows out to sides. The bar should be close to the shins. Position the shoulders over or slightly ahead of the bar. Establish a flat back posture. This will be your starting position. Begin to pull the bar by extending the knees. Move your hips fo'),
('Clean_from_Blocks', 'Clean from Blocks', 'legs', ARRAY['legs','legs','legs','shoulders','back']::text[], 'barbell', 'olympic weightlifting', 'intermediate', 'With a barbell on boxes or stands of the desired height, take an overhand or hook grip just outside the legs. Lower your hips with the weight focused on the heels, back straight, head facing forward, chest up, with your shoulders just in front of the bar. This will be your starting position. Begin the first pull by driving through the heels, extending your knees. Your back angle should stay the same, and your arms should remain straight with the elbows pointed out. As full extension is achieved,'),
('Clock_Push-Up', 'Clock Push-Up', 'chest', ARRAY['shoulders','arms']::text[], 'bodyweight', 'strength', 'intermediate', 'Move into a prone position on the floor, supporting your weight on your hands and toes. Your arms should be fully extended with the hands around shoulder width. Keep your body straight throughout the movement. This will be your starting position. Descend by flexing at the elbow, lowering your chest toward the ground. At the bottom, reverse the motion by pushing yourself up through elbow extension as quickly as possible until you are air borne. Aim to "jump" 12-18 inches to one side. As you accel'),
('Close-Grip_Barbell_Bench_Press', 'Close-Grip Barbell Bench Press', 'arms', ARRAY['chest','shoulders']::text[], 'barbell', 'strength', 'beginner', 'Lie back on a flat bench. Using a close grip (around shoulder width), lift the bar from the rack and hold it straight over you with your arms locked. This will be your starting position. As you breathe in, come down slowly until you feel the bar on your middle chest. Tip: Make sure that - as opposed to a regular bench press - you keep the elbows close to the torso at all times in order to maximize triceps involvement. After a second pause, bring the bar back to the starting position as you breat'),
('Close-Grip_Dumbbell_Press', 'Close-Grip Dumbbell Press', 'arms', ARRAY['chest','shoulders']::text[], 'dumbbell', 'strength', 'beginner', 'Place a dumbbell standing up on a flat bench. Ensuring that the dumbbell stays securely placed at the top of the bench, lie perpendicular to the bench with only your shoulders lying on the surface. Hips should be below the bench and your legs bent with your feet firmly on the floor. Grasp the dumbbell with both hands and hold it straight over your chest at arm''s length. Both palms should be pressing against the underside of the sides of the dumbbell. This will be your starting position. Initiat'),
('Close-Grip_EZ-Bar_Curl_with_Band', 'Close-Grip EZ-Bar Curl with Band', 'arms', ARRAY['arms']::text[], 'barbell', 'strength', 'beginner', 'Attach a band to each end of the bar. Take the bar, placing a foot on the middle of the band. Stand upright with a narrow, supinated grip on the EZ bar. The elbows should be close to the torso. This will be your starting position. While keeping the upper arms in place, flex the elbows to execute the curl. Exhale as the weight is lifted. Continue the movement until your biceps are fully contracted and the bar is at shoulder level. Hold the contracted position for a second and squeeze the biceps h'),
('Close-Grip_EZ-Bar_Press', 'Close-Grip EZ-Bar Press', 'arms', ARRAY['chest','shoulders']::text[], 'barbell', 'strength', 'beginner', 'Lie on a flat bench with an EZ bar loaded to an appropriate weight. Using a narrow grip lift the bar and hold it straight over your torso with your elbows in. The arms should be perpendicular to the floor. This will be your starting position. Now lower the bar down to your lower chest as you breathe in. Keep the elbows in as you perform this movement. Using the triceps to push the bar back up, press it back to the starting position by extending the elbows as you exhale. Repeat.'),
('Close-Grip_EZ_Bar_Curl', 'Close-Grip EZ Bar Curl', 'arms', ARRAY['arms']::text[], 'barbell', 'strength', 'beginner', 'Stand up with your torso upright while holding an E-Z Curl Bar at the closer inner handle. The palm of your hands should be facing forward and they should be slightly tilted inwards due to the shape of the bar. The elbows should be close to the torso. This will be your starting position. While holding the upper arms stationary, curl the weights forward while contracting the biceps as you breathe out. Tip: Only the forearms should move. Continue the movement until your biceps are fully contracted'),
('Close-Grip_Front_Lat_Pulldown', 'Close-Grip Front Lat Pulldown', 'back', ARRAY['arms','back','shoulders']::text[], 'cable', 'strength', 'beginner', 'Sit down on a pull-down machine with a wide bar attached to the top pulley. Make sure that you adjust the knee pad of the machine to fit your height. These pads will prevent your body from being raised by the resistance attached to the bar. Grab the bar with the palms facing forward using the prescribed grip. Note on grips: For a wide grip, your hands need to be spaced out at a distance wider than your shoulder width. For a medium grip, your hands need to be spaced out at a distance equal to you'),
('Close-Grip_Push-Up_off_of_a_Dumbbell', 'Close-Grip Push-Up off of a Dumbbell', 'arms', ARRAY['core','chest','shoulders']::text[], 'bodyweight', 'strength', 'intermediate', 'Lie on the floor and place your hands on an upright dumbbell. Supporting your weight on your toes and hands, keep your torso rigid and your elbows in with your arms straight. This will be your starting position. Lower your body, allowing the elbows to flex while you inhale. Keep your body straight, not allowing your hips to rise or sag. Press yourself back up to the starting position by extending the elbows. Breathe out as you perform this step. After a pause at the contracted position, repeat t'),
('Close-Grip_Standing_Barbell_Curl', 'Close-Grip Standing Barbell Curl', 'arms', ARRAY['arms']::text[], 'barbell', 'strength', 'beginner', 'Hold a barbell with both hands, palms up and a few inches apart. Stand with your torso straight and your head up. Your feet should be about shoulder width and your elbows close to your torso. This will be your starting position. Tip: You will keep your upper arms and elbows stationary throughout the movement. Curl the bar up in a semicircular motion until the forearms touch your biceps. Exhale as you perform this portion of the movement and contract your biceps hard for a second at the top. Tip:'),
('Cocoons', 'Cocoons', 'core', ARRAY[]::text[], 'bodyweight', 'strength', 'beginner', 'Begin by lying on your back on the ground. Your legs should be straight and your arms extended behind your head. This will be your starting position. To perform the movement, tuck the knees toward your chest, rotating your pelvis to lift your glutes from the floor. As you do so, flex the spine, bringing your arms back over your head to perform a simultaneous crunch motion. After a brief pause, return to the starting position.'),
('Conans_Wheel', 'Conan''s Wheel', 'legs', ARRAY['core','arms','legs','arms','back','shoulders','back']::text[], 'other', 'strongman', 'intermediate', 'With the weight loaded, take a zurcher hold on the end of the implement. Place the bar in the crook of the elbow and hold onto your wrist. Try to keep the weight off of the forearms. Begin by lifting the weight from the ground. Keep a tight, upright posture as you being to walk, taking short, fast steps. Look up and away as you turn in a circle. Do not hold your breath during the event. Continue walking until you complete one or more complete turns.'),
('Concentration_Curls', 'Concentration Curls', 'arms', ARRAY['arms']::text[], 'dumbbell', 'strength', 'beginner', 'Sit down on a flat bench with one dumbbell in front of you between your legs. Your legs should be spread with your knees bent and feet on the floor. Use your right arm to pick the dumbbell up. Place the back of your right upper arm on the top of your inner right thigh. Rotate the palm of your hand until it is facing forward away from your thigh. Tip: Your arm should be extended and the dumbbell should be above the floor. This will be your starting position. While holding the upper arm stationary'),
('Cross-Body_Crunch', 'Cross-Body Crunch', 'core', ARRAY[]::text[], 'bodyweight', 'strength', 'beginner', 'Lie flat on your back and bend your knees about 60 degrees. Keep your feet flat on the floor and place your hands loosely behind your head. This will be your starting position. Now curl up and bring your right elbow and shoulder across your body while bring your left knee in toward your left shoulder at the same time. Reach with your elbow and try to touch your knee. Exhale as you perform this movement. Tip: Try to bring your shoulder up towards your knee rather than just your elbow and remember'),
('Cross_Body_Hammer_Curl', 'Cross Body Hammer Curl', 'arms', ARRAY['arms']::text[], 'dumbbell', 'strength', 'beginner', 'Stand up straight with a dumbbell in each hand. Your hands should be down at your side with your palms facing in. While keeping your palms facing in and without twisting your arm, curl the dumbbell of the right arm up towards your left shoulder as you exhale. Touch the top of the dumbbell to your shoulder and hold the contraction for a second. Slowly lower the dumbbell along the same path as you inhale and then repeat the same movement for the left arm. Continue alternating in this fashion until'),
('Cross_Over_-_With_Bands', 'Cross Over - With Bands', 'chest', ARRAY['arms','shoulders']::text[], 'bands', 'strength', 'beginner', 'Secure an exercise band around a stationary post. While facing away from the post, grab the handles on both ends of the band and step forward enough to create tension on the band. Raise your arms to the sides, parallel to the floor, perpendicular to your torso (your torso and the arms should resemble the letter "T") and with the palms facing forward. Have them extended with a slight bend at the elbows. This will be your starting position. While keeping your arms straight, bring them across your '),
('Crossover_Reverse_Lunge', 'Crossover Reverse Lunge', 'back', ARRAY['core','legs','legs','legs','legs']::text[], 'other', 'stretching', 'intermediate', 'Stand with your feet shoulder width apart. This will be your starting position. Perform a rear lunge by stepping back with one foot and flexing the hips and front knee. As you do so, rotate your torso across the front leg. After a brief pause, return to the starting position and repeat on the other side, continuing in an alternating fashion.'),
('Crucifix', 'Crucifix', 'shoulders', ARRAY['arms']::text[], 'other', 'strongman', 'beginner', 'In the crucifix, you statically hold weights out to the side for time. While the event can be practiced using dumbbells, it is best to practice with one of the various implements used, such as axes and hammers, as it feels different. Begin standing, and raise your arms out to the side holding the implements. Your arms should be parallel to the ground. In competition, judges or sensors are used to let you know when you break parallel. Hold for as long as you can. Typically, the weights should be '),
('Crunch_-_Hands_Overhead', 'Crunch - Hands Overhead', 'core', ARRAY[]::text[], 'bodyweight', 'strength', 'beginner', 'Lie on the floor with your back flat and knees bent with around a 60-degree angle between the hamstrings and the calves. Keep your feet flat on the floor and stretch your arms overhead with your palms crossed. This will be your starting position. Curl your upper body forward and bring your shoulder blades just off the floor. At all times, keep your arms aligned with your head, neck and shoulder. Don''t move them forward from that position. Exhale as you perform this portion of the movement and h'),
('Crunch_-_Legs_On_Exercise_Ball', 'Crunch - Legs On Exercise Ball', 'core', ARRAY[]::text[], 'bodyweight', 'strength', 'beginner', 'Lie flat on your back with your feet resting on an exercise ball and your knees bent at a 90 degree angle. Place your feet three to four inches apart and point your toes inward so they touch. Place your hands lightly on either side of your head keeping your elbows in. Tip: Don''t lock your fingers behind your head. Push the small of your back down in the floor in order to better isolate your abdominal muscles. This will be your starting position. Begin to roll your shoulders off the floor and co'),
('Crunches', 'Crunches', 'core', ARRAY[]::text[], 'bodyweight', 'strength', 'beginner', 'Lie flat on your back with your feet flat on the ground, or resting on a bench with your knees bent at a 90 degree angle. If you are resting your feet on a bench, place them three to four inches apart and point your toes inward so they touch. Now place your hands lightly on either side of your head keeping your elbows in. Tip: Don''t lock your fingers behind your head. While pushing the small of your back down in the floor to better isolate your abdominal muscles, begin to roll your shoulders of'),
('Cuban_Press', 'Cuban Press', 'shoulders', ARRAY['back']::text[], 'dumbbell', 'strength', 'intermediate', 'Take a dumbbell in each hand with a pronated grip in a standing position. Raise your upper arms so that they are parallel to the floor, allowing your lower arms to hang in the "scarecrow" position. This will be your starting position. To initiate the movement, externally rotate the shoulders to move the upper arm 180 degrees. Keep the upper arms in place, rotating the upper arms until the wrists are directly above the elbows, the forearms perpendicular to the floor. Now press the dumbbells by ex'),
('Dancers_Stretch', 'Dancer''s Stretch', 'back', ARRAY['legs','legs']::text[], 'other', 'stretching', 'beginner', 'Sit up on the floor. Cross your right leg over your left, keeping the knee bent. Your left leg is straight and down on the floor. Place your left arm on your right leg and your right hand on the floor. Rotate your upper body to the right, and hold for 10-20 seconds. Switch sides.'),
('Dead_Bug', 'Dead Bug', 'core', ARRAY[]::text[], 'bodyweight', 'strength', 'beginner', 'Begin lying on your back with your hands extended above you toward the ceiling. Bring your feet, knees, and hips up to 90 degrees. Exhale hard to bring your ribcage down and flatten your back onto the floor, rotating your pelvis up and squeezing your glutes. Hold this position throughout the movement. This will be your starting position. Initiate the exercise by extending one leg, straightening the knee and hip to bring the leg just above the ground. Maintain the position of your lumbar and pelv'),
('Deadlift_with_Bands', 'Deadlift with Bands', 'back', ARRAY['arms','legs','legs','back','legs','back']::text[], 'barbell', 'powerlifting', 'expert', 'To deadlift with short bands, simply loop them over the bar before you start, and step into them to set up. For long bands, they will need to be anchored to a secure base, such as heavy dumbbells or a rack. With your feet, and your grip set, take a big breath and then lower your hips and bend the knees until your shins contact the bar. Look forward with your head, keep your chest up and your back arched, and begin driving through the heels to move the weight upward. After the bar passes the knee'),
('Deadlift_with_Chains', 'Deadlift with Chains', 'back', ARRAY['arms','legs','legs','back','legs','back']::text[], 'barbell', 'powerlifting', 'expert', 'You can attach the chains to the sleeves of the bar, or just drape the middle over the bar so there is a greater weight increase as you lift. Approach the bar so that it is centered over your feet. You feet should be about hip width apart. Bend at the hip to grip the bar at shoulder width, allowing your shoulder blades to protract. Typically, you would use an overhand grip or an over/under grip on heavier sets. With your feet, and your grip set, take a big breath and then lower your hips and ben'),
('Decline_Barbell_Bench_Press', 'Decline Barbell Bench Press', 'chest', ARRAY['shoulders','arms']::text[], 'barbell', 'strength', 'beginner', 'Secure your legs at the end of the decline bench and slowly lay down on the bench. Using a medium width grip (a grip that creates a 90-degree angle in the middle of the movement between the forearms and the upper arms), lift the bar from the rack and hold it straight over you with your arms locked. The arms should be perpendicular to the floor. This will be your starting position. Tip: In order to protect your rotator cuff, it is best if you have a spotter help you lift the barbell off the rack.'),
('Decline_Close-Grip_Bench_To_Skull_Crusher', 'Decline Close-Grip Bench To Skull Crusher', 'arms', ARRAY['chest','shoulders']::text[], 'barbell', 'strength', 'intermediate', 'Secure your legs at the end of the decline bench and slowly lay down on the bench. Using a close grip (a grip that is slightly less than shoulder width), lift the bar from the rack and hold it straight over you with your arms locked and elbows in. The arms should be perpendicular to the floor. This will be your starting position. Tip: In order to protect your rotator cuff, it is best if you have a spotter help you lift the barbell off the rack. Now lower the bar down to your lower chest as you b'),
('Decline_Crunch', 'Decline Crunch', 'core', ARRAY[]::text[], 'bodyweight', 'strength', 'intermediate', 'Secure your legs at the end of the decline bench and lie down. Now place your hands lightly on either side of your head keeping your elbows in. Tip: Don''t lock your fingers behind your head. While pushing the small of your back down in the bench to better isolate your abdominal muscles, begin to roll your shoulders off it. Continue to push down as hard as you can with your lower back as you contract your abdominals and exhale. Your shoulders should come up off the bench only about four inches, '),
('Decline_Dumbbell_Bench_Press', 'Decline Dumbbell Bench Press', 'chest', ARRAY['shoulders','arms']::text[], 'dumbbell', 'strength', 'beginner', 'Secure your legs at the end of the decline bench and lie down with a dumbbell on each hand on top of your thighs. The palms of your hand will be facing each other. Once you are laying down, move the dumbbells in front of you at shoulder width. Once at shoulder width, rotate your wrists forward so that the palms of your hands are facing away from you. This will be your starting position. Bring down the weights slowly to your side as you breathe out. Keep full control of the dumbbells at all times'),
('Decline_Dumbbell_Flyes', 'Decline Dumbbell Flyes', 'chest', ARRAY[]::text[], 'dumbbell', 'strength', 'beginner', 'Secure your legs at the end of the decline bench and lie down with a dumbbell on each hand on top of your thighs. The palms of your hand will be facing each other. Once you are laying down, move the dumbbells in front of you at shoulder width. The palms of the hands should be facing each other and the arms should be perpendicular to the floor and fully extended. This will be your starting position. With a slight bend on your elbows in order to prevent stress at the biceps tendon, lower your arms'),
('Decline_Dumbbell_Triceps_Extension', 'Decline Dumbbell Triceps Extension', 'arms', ARRAY[]::text[], 'dumbbell', 'strength', 'beginner', 'Secure your legs at the end of the decline bench and lie down with a dumbbell on each hand on top of your thighs. The palms of your hand will be facing each other. Once you are laying down, move the dumbbells in front of you at shoulder width. The palms of the hands should be facing each other and the arms should be perpendicular to the floor and fully extended. This will be your starting position. As you breathe in and you keep the upper arms stationary (and elbows in), bring the dumbbells down')
INSERT INTO exercises (external_id, name, muscle_group, secondary_muscles, equipment, category, level, instructions) VALUES
('Decline_EZ_Bar_Triceps_Extension', 'Decline EZ Bar Triceps Extension', 'arms', ARRAY[]::text[], 'barbell', 'strength', 'beginner', 'Secure your legs at the end of the decline bench and slowly lay down on the bench. Using a close grip (a grip that is slightly less than shoulder width), lift the EZ bar from the rack and hold it straight over you with your arms locked and elbows in. The arms should be perpendicular to the floor. This will be your starting position. Tip: In order to protect your rotator cuff, it is best if you have a spotter help you lift the barbell off the rack. As you breathe in and you keep the upper arms st'),
('Decline_Oblique_Crunch', 'Decline Oblique Crunch', 'core', ARRAY[]::text[], 'bodyweight', 'strength', 'beginner', 'Secure your legs at the end of the decline bench and slowly lay down on the bench. Raise your upper body off the bench until your torso is about 35-45 degrees if measured from the floor. Put one hand beside your head and the other on your thigh. This will be your starting position. Raise your upper body slowly from the starting position while turning your torso to the left. Continue crunching up as you exhale until your right elbow touches your left knee. Hold this contracted position for a seco'),
('Decline_Push-Up', 'Decline Push-Up', 'chest', ARRAY['shoulders','arms']::text[], 'other', 'strength', 'beginner', 'Lie on the floor face down and place your hands about 36 inches apart while holding your torso up at arms length. Move your feet up to a box or bench. This will be your starting position. Next, lower yourself downward until your chest almost touches the floor as you inhale. Now breathe out and press your upper body back up to the starting position while squeezing your chest. After a brief pause at the top contracted position, you can begin to lower yourself downward again for as many repetitions'),
('Decline_Reverse_Crunch', 'Decline Reverse Crunch', 'core', ARRAY[]::text[], 'bodyweight', 'strength', 'beginner', 'Lie on your back on a decline bench and hold on to the top of the bench with both hands. Don''t let your body slip down from this position. Hold your legs parallel to the floor using your abs to hold them there while keeping your knees and feet together. Tip: Your legs should be fully extended with a slight bend on the knee. This will be your starting position. While exhaling, move your legs towards the torso as you roll your pelvis backwards and you raise your hips off the bench. At the end of '),
('Decline_Smith_Press', 'Decline Smith Press', 'chest', ARRAY['shoulders','arms']::text[], 'machine', 'strength', 'beginner', 'Place a decline bench underneath the Smith machine. Now place the barbell at a height that you can reach when lying down and your arms are almost fully extended. Using a pronated grip that is wider than shoulder width, unlock the bar from the rack and hold it straight over you with your arms extended. This will be your starting position. As you inhale, lower the bar under control by allowing the elbows to flex, lightly contacting the torso. After a brief pause, bring the bar back to the starting'),
('Deficit_Deadlift', 'Deficit Deadlift', 'back', ARRAY['arms','legs','legs','back','legs','back']::text[], 'barbell', 'powerlifting', 'intermediate', 'Begin by having a platform or weight plates that you can stand on, usually 1-3 inches in height. Approach the bar so that it is centered over your feet. You feet should be about hip width apart. Bend at the hip to grip the bar at shoulder width, allowing your shoulder blades to protract. Typically, you would use an overhand grip or an over/under grip on heavier sets. With your feet, and your grip set, take a big breath and then lower your hips and bend the knees until your shins contact the bar.'),
('Depth_Jump_Leap', 'Depth Jump Leap', 'legs', ARRAY['legs','legs','legs','legs','legs']::text[], 'other', 'plyometrics', 'beginner', 'For this drill you will need two boxes or benches, one 12 to 16 inches high and the other 22 to 26 inches high. Stand on one of the two boxes with arms at the sides; feet should be together and slightly off the edge as in the depth jump. Place the other box approximately two or three feet in front of and facing the performer. Begin by dropping off the initial box, landing and simultaneously taking off with both feet. Rebound by driving upward and outward as intensely as possible, using the arms '),
('Dip_Machine', 'Dip Machine', 'arms', ARRAY['chest','shoulders']::text[], 'machine', 'strength', 'beginner', 'Sit securely in a dip machine, select the weight and firmly grasp the handles. Now keep your elbows in at your sides in order to place emphasis on the triceps. The elbows should be bent at a 90 degree angle. As you contract the triceps, extend your arms downwards as you exhale. Tip: At the bottom of the movement, focus on keeping a little bend in your arms to keep tension on the triceps muscle. Now slowly let your arms come back up to the starting position as you inhale. Repeat for the recommend'),
('Dips_-_Chest_Version', 'Dips - Chest Version', 'chest', ARRAY['shoulders','arms']::text[], 'other', 'strength', 'intermediate', 'For this exercise you will need access to parallel bars. To get yourself into the starting position, hold your body at arms length (arms locked) above the bars. While breathing in, lower yourself slowly with your torso leaning forward around 30 degrees or so and your elbows flared out slightly until you feel a slight stretch in the chest. Once you feel the stretch, use your chest to bring your body back to the starting position as you breathe out. Tip: Remember to squeeze the chest at the top of'),
('Dips_-_Triceps_Version', 'Dips - Triceps Version', 'arms', ARRAY['chest','shoulders']::text[], 'bodyweight', 'strength', 'beginner', 'To get into the starting position, hold your body at arm''s length with your arms nearly locked above the bars. Now, inhale and slowly lower yourself downward. Your torso should remain upright and your elbows should stay close to your body. This helps to better focus on tricep involvement. Lower yourself until there is a 90 degree angle formed between the upper arm and forearm. Then, exhale and push your torso back up using your triceps to bring your body back to the starting position. Repeat th'),
('Donkey_Calf_Raises', 'Donkey Calf Raises', 'legs', ARRAY[]::text[], 'other', 'strength', 'intermediate', 'For this exercise you will need access to a donkey calf raise machine. Start by positioning your lower back and hips under the padded lever provided. The tailbone area should be the one making contact with the pad. Place both of your arms on the side handles and place the balls of your feet on the calf block with the heels extending off. Align the toes forward, inward or outward, depending on the area you wish to target, and straighten the knees without locking them. This will be your starting p'),
('Double_Kettlebell_Alternating_Hang_Clean', 'Double Kettlebell Alternating Hang Clean', 'legs', ARRAY['arms','legs','arms','legs','back','legs','back']::text[], 'kettlebell', 'strength', 'intermediate', 'Place two kettlebells between your feet. To get in the starting position, push your butt back and look straight ahead. Clean one kettlebell to your shoulder and hold on to the other kettlebell. With a fluid motion, lower the top kettlebell while driving the bottom kettlebell up.'),
('Double_Kettlebell_Jerk', 'Double Kettlebell Jerk', 'shoulders', ARRAY['legs','legs','arms']::text[], 'kettlebell', 'strength', 'intermediate', 'Hold a kettlebell by the handle in each hand. Clean the kettlebells to your shoulders by extending through the legs and hips as you pull the kettlebells towards your shoulders. Rotate your wrists as you do so, so that the palms face forward. This will be your starting position. Dip your body by bending the knees, keeping your torso upright. Immediately reverse direction, driving through the heels, in essence jumping to create momentum. As you do so, press the kettlebells overhead to lockout by e'),
('Double_Kettlebell_Push_Press', 'Double Kettlebell Push Press', 'shoulders', ARRAY['legs','legs','arms']::text[], 'kettlebell', 'strength', 'intermediate', 'Clean two kettlebells to your shoulders. Squat down a few inches and reverse the motion rapidly. Use the momentum from the legs to drive the kettlebells overhead. Once the kettlebells are locked out, lower the kettlebells to your shoulders and repeat.'),
('Double_Kettlebell_Snatch', 'Double Kettlebell Snatch', 'shoulders', ARRAY['legs','legs','legs']::text[], 'kettlebell', 'strength', 'expert', 'Place two kettlebells behind your feet. Bend your knees and sit back to pick up the kettlebells. Swing the kettlebells between your legs forcefully and reverse the direction. Drive through with your hips and lock the ketttlebells overhead in one uninterrupted motion.'),
('Double_Kettlebell_Windmill', 'Double Kettlebell Windmill', 'core', ARRAY['legs','legs','shoulders','arms']::text[], 'kettlebell', 'strength', 'intermediate', 'Place a kettlebell in front of your front foot and clean and press a kettlebell overhead with your opposite arm. Clean the kettlebell to your shoulder by extending through the legs and hips as you pull the kettlebell towards your shoulders. Rotate your wrist as you do so, so that the palm faces forward. Keeping the kettlebell locked out at all times, push your butt out in the direction of the locked out kettlebell. Turn your feet out at a forty-five degree angle from the arm with the locked out '),
('Double_Leg_Butt_Kick', 'Double Leg Butt Kick', 'legs', ARRAY['legs','legs','legs','legs','legs']::text[], 'bodyweight', 'plyometrics', 'beginner', 'Begin standing with your knees slightly bent. Quickly squat a short distance, flexing the hips and knees, and immediately extend to jump for maximum vertical height. As you go up, tuck your heels by flexing the knees, attempting to touch the buttocks. Finish the motion by landing with the knees only partially bent, using your legs to absorb the impact.'),
('Downward_Facing_Balance', 'Downward Facing Balance', 'legs', ARRAY['core','legs']::text[], 'other', 'strength', 'intermediate', 'Lie facedown on top of an exercise ball. While resting on your stomach on the ball, walk your hands forward along the floor and lift your legs, extending your elbows and knees.'),
('Drag_Curl', 'Drag Curl', 'arms', ARRAY['arms']::text[], 'barbell', 'strength', 'intermediate', 'Grab a barbell with a supinated grip (palms facing forward) and get your elbows close to your torso and back. This will be your starting position. As you exhale, curl the bar up while keeping the elbows to the back as you "Drag" the bar up by keeping it in contact with your torso. Tip: As you can see, you will not be keeping the elbows pinned to your sides, but instead you will be bringing them back. Also, do not lift your shoulders. Slowly go back to the starting position as you keep the bar in'),
('Drop_Push', 'Drop Push', 'chest', ARRAY['shoulders','arms']::text[], 'other', 'plyometrics', 'intermediate', 'Position low boxes or other platforms 2-3 feet apart. Move to a pushup position between them, supporting yourself by placing your hands on the boxes. With good posture, drop from the platforms by pressing up and moving your hands to shoulder width, cushioning your landing by absorbing the impact through the arm.'),
('Dumbbell_Alternate_Bicep_Curl', 'Dumbbell Alternate Bicep Curl', 'arms', ARRAY['arms']::text[], 'dumbbell', 'strength', 'beginner', 'Stand (torso upright) with a dumbbell in each hand held at arms length. The elbows should be close to the torso and the palms of your hand should be facing your thighs. While holding the upper arm stationary, curl the right weight as you rotate the palm of the hands until they are facing forward. At this point continue contracting the biceps as you breathe out until your biceps is fully contracted and the dumbbells are at shoulder level. Hold the contracted position for a second as you squeeze t'),
('Dumbbell_Bench_Press', 'Dumbbell Bench Press', 'chest', ARRAY['shoulders','arms']::text[], 'dumbbell', 'strength', 'beginner', 'Lie down on a flat bench with a dumbbell in each hand resting on top of your thighs. The palms of your hands will be facing each other. Then, using your thighs to help raise the dumbbells up, lift the dumbbells one at a time so that you can hold them in front of you at shoulder width. Once at shoulder width, rotate your wrists forward so that the palms of your hands are facing away from you. The dumbbells should be just to the sides of your chest, with your upper arm and forearm creating a 90 de'),
('Dumbbell_Bench_Press_with_Neutral_Grip', 'Dumbbell Bench Press with Neutral Grip', 'chest', ARRAY['shoulders','arms']::text[], 'dumbbell', 'strength', 'beginner', 'Take a dumbbell in each hand and lay back onto a flat bench. Your feet should be flat on the floor and your shoulder blades retracted. Maintaining a neutral grip, palms facing each other, begin with your arms extended directly above you, perpendicular to the floor. This will be your starting position. Begin the movement by flexing the elbow, lowering the upper arms to the side. Descend until the dumbbells are to your torso. Pause, then extend the elbow and return to the starting position.'),
('Dumbbell_Bicep_Curl', 'Dumbbell Bicep Curl', 'arms', ARRAY['arms']::text[], 'dumbbell', 'strength', 'beginner', 'Stand up straight with a dumbbell in each hand at arm''s length. Keep your elbows close to your torso and rotate the palms of your hands until they are facing forward. This will be your starting position. Now, keeping the upper arms stationary, exhale and curl the weights while contracting your biceps. Continue to raise the weights until your biceps are fully contracted and the dumbbells are at shoulder level. Hold the contracted position for a brief pause as you squeeze your biceps. Then, inhal'),
('Dumbbell_Clean', 'Dumbbell Clean', 'legs', ARRAY['legs','arms','legs','back','legs','shoulders','back']::text[], 'dumbbell', 'strength', 'intermediate', 'Begin standing with a dumbbell in each hand with your feet shoulder width apart. Lower the weights to the floor by flexing at the hips and knees, pushing your hips back until the dumbbells reach the floor. This will be your starting position. To initiate the movement, violently jump upward by extending the hips, knees, and ankles to acclerate the weights upward. Maintaining a neutral grip on the dumbbells, keep the arms straight until full extension is reached. After full extension, rebend the h'),
('Dumbbell_Floor_Press', 'Dumbbell Floor Press', 'arms', ARRAY['chest','shoulders']::text[], 'dumbbell', 'powerlifting', 'intermediate', 'Lay on the floor holding dumbbells in your hands. Your knees can be bent. Begin with the weights fully extended above you. Lower the weights until your upper arm comes in contact with the floor. You can tuck your elbows to emphasize triceps size and strength, or to focus on your chest angle your arms to the side. Pause at the bottom, and then bring the weight together at the top by extending through the elbows.'),
('Dumbbell_Flyes', 'Dumbbell Flyes', 'chest', ARRAY[]::text[], 'dumbbell', 'strength', 'beginner', 'Lie down on a flat bench with a dumbbell on each hand resting on top of your thighs. The palms of your hand will be facing each other. Then using your thighs to help raise the dumbbells, lift the dumbbells one at a time so you can hold them in front of you at shoulder width with the palms of your hands facing each other. Raise the dumbbells up like you''re pressing them, but stop and hold just before you lock out. This will be your starting position. With a slight bend on your elbows in order to'),
('Dumbbell_Incline_Row', 'Dumbbell Incline Row', 'back', ARRAY['arms','arms','back','shoulders']::text[], 'dumbbell', 'strength', 'beginner', 'Using a neutral grip, lean into an incline bench. Take a dumbbell in each hand with a neutral grip, beginning with the arms straight. This will be your starting position. Retract the shoulder blades and flex the elbows to row the dumbbells to your side. Pause at the top of the motion, and then return to the starting position.'),
('Dumbbell_Incline_Shoulder_Raise', 'Dumbbell Incline Shoulder Raise', 'shoulders', ARRAY['arms']::text[], 'dumbbell', 'strength', 'beginner', 'Sit on an Incline Bench while holding a dumbbell on each hand on top of your thighs. Lift your legs up to kick the weights to your shoulders and lean back. Position the dumbbells above your shoulders with your arms extended. The arms should be perpendicular to the floor with your palms facing forward and knuckles pointing towards the ceiling. This will be your starting position. While keeping the arms straight and locked, lift the dumbbells by raising the shoulders from the bench as you breathe '),
('Dumbbell_Lunges', 'Dumbbell Lunges', 'legs', ARRAY['legs','legs','legs']::text[], 'dumbbell', 'strength', 'beginner', 'Stand with your torso upright holding two dumbbells in your hands by your sides. This will be your starting position. Step forward with your right leg around 2 feet or so from the foot being left stationary behind and lower your upper body down, while keeping the torso upright and maintaining balance. Inhale as you go down. Note: As in the other exercises, do not allow your knee to go forward beyond your toes as you come down, as this will put undue stress on the knee joint. Make sure that you k'),
('Dumbbell_Lying_One-Arm_Rear_Lateral_Raise', 'Dumbbell Lying One-Arm Rear Lateral Raise', 'shoulders', ARRAY['back']::text[], 'dumbbell', 'strength', 'intermediate', 'While holding a dumbbell in one hand, lay with your chest down on a slightly inclined (around 15 degrees when measured from the floor) adjustable bench. The other hand can be used to hold to the leg of the bench for stability. Position the palm of the hand that is holding the dumbbell in a neutral manner (palms facing your torso) as you keep the arm extended with the elbow slightly bent. This will be your starting position. Now raise the arm with the dumbbell to the side until your elbow is at s'),
('Dumbbell_Lying_Pronation', 'Dumbbell Lying Pronation', 'arms', ARRAY[]::text[], 'dumbbell', 'strength', 'intermediate', 'Lie on a flat bench face down with one arm holding a dumbbell and the other hand on top of the bench folded so that you can rest your head on it. Bend the elbows of the arm holding the dumbbell so that it creates a 90-degree angle between the upper arm and the forearm. Now raise the upper arm so that the forearm is perpendicular to the floor and the upper arm is perpendicular to your torso. Tip: The upper arm should be parallel to the floor and also creating a 90-degree angle with your torso. Th'),
('Dumbbell_Lying_Rear_Lateral_Raise', 'Dumbbell Lying Rear Lateral Raise', 'shoulders', ARRAY[]::text[], 'dumbbell', 'strength', 'intermediate', 'While holding a dumbbell in each hand, lay with your chest down on a slightly inclined (around 15 degrees when measured from the floor) adjustable bench. Position the palms of the hands in a neutral manner (palms facing your torso) as you keep the arms extended with the elbows slightly bent. This will be your starting position. Now raise the arms to the side until your elbows are at shoulder height and your arms are roughly parallel to the floor as you exhale. Tip: Maintain your arms perpendicul'),
('Dumbbell_Lying_Supination', 'Dumbbell Lying Supination', 'arms', ARRAY[]::text[], 'dumbbell', 'strength', 'intermediate', 'Lie sideways on a flat bench with one arm holding a dumbbell and the other hand on top of the bench folded so that you can rest your head on it. Bend the elbows of the arm holding the dumbbell so that it creates a 90-degree angle between the upper arm and the forearm. Now raise the upper arm so that the forearm is parallel to the floor and perpendicular to your torso (Tip: So the forearm will be directly in front of you). The upper arm will be stationary by your torso and should be parallel to t'),
('Dumbbell_One-Arm_Shoulder_Press', 'Dumbbell One-Arm Shoulder Press', 'shoulders', ARRAY['arms']::text[], 'dumbbell', 'strength', 'intermediate', 'Grab a dumbbell and either sit on a military press bench or a utility bench that has a back support on it as you place the dumbbells upright on top of your thighs or stand up straight. Clean the dumbbell up to bring it to shoulder height. The other hand can be kept fully extended to the side, by the waist or grabbing a fixed surface. Rotate the wrist so that the palm of your hand is facing forward. This is your starting position. As you exhale, push the dumbbell up until your arm is fully extend'),
('Dumbbell_One-Arm_Triceps_Extension', 'Dumbbell One-Arm Triceps Extension', 'arms', ARRAY[]::text[], 'dumbbell', 'strength', 'intermediate', 'Grab a dumbbell and either sit on a military press bench or a utility bench that has a back support on it as you place the dumbbells upright on top of your thighs or stand up straight. Clean the dumbbell up to bring it to shoulder height and then extend the arm over your head so that the whole arm is perpendicular to the floor and next to your head. The dumbbell should be on top of you. The other hand can be kept fully extended to the side, by the waist, supporting the upper arm that has the dum'),
('Dumbbell_One-Arm_Upright_Row', 'Dumbbell One-Arm Upright Row', 'shoulders', ARRAY['arms','back']::text[], 'dumbbell', 'strength', 'intermediate', 'Grab a dumbbell and stand up straight with your arm extended in front of you with a slight bend at the elbows and your back straight. This will be your starting position. Tip: The dumbbell should be resting on top of your thigh with the palm of your hands facing your thighs. Keep the other hand can be kept fully extended to the side, by the waist or grabbing a fixed surface. This will be your starting position. Use your side shoulders to lift the dumbbell as you exhale. The dumbbell should be cl'),
('Dumbbell_Prone_Incline_Curl', 'Dumbbell Prone Incline Curl', 'arms', ARRAY[]::text[], 'dumbbell', 'strength', 'intermediate', 'Grab a dumbbell on each hand and lie face down on an incline bench with your shoulders near top of the incline. Your knees can rest on the seat or your legs can be straddled to the sides (my preferred way). Let your arms extend and hang naturally in front of you so that they are perpendicular to the floor. Now keep your elbows in by your side and face the palms forward. This will be your starting position. Raise the dumbbells by contracting the biceps until your arms are fully flexed. Exhale as '),
('Dumbbell_Raise', 'Dumbbell Raise', 'shoulders', ARRAY['arms']::text[], 'dumbbell', 'strength', 'beginner', 'Grab a dumbbell in each arm and stand up straight with your arms extended by your sides with a slight bend at the elbows and your back straight. This will be your starting position. Tip: The dumbbell should be next to your thighs with the palm of your hands facing back. Use your side shoulders to lift the dumbbells as you exhale. The dumbbells should be to the side of the body as you move them up. Continue to lift it until the dumbbells are nearly in line with your chin. Tip: Your elbows should '),
('Dumbbell_Rear_Lunge', 'Dumbbell Rear Lunge', 'legs', ARRAY['legs','legs','legs']::text[], 'dumbbell', 'strength', 'intermediate', 'Stand with your torso upright holding two dumbbells in your hands by your sides. This will be your starting position. Step backward with your right leg around two feet or so from the left foot and lower your upper body down, while keeping the torso upright and maintaining balance. Inhale as you go down. Tip: As in the other exercises, do not allow your knee to go forward beyond your toes as you come down, as this will put undue stress on the knee joint. Make sure that you keep your front shin pe'),
('Dumbbell_Scaption', 'Dumbbell Scaption', 'shoulders', ARRAY['back']::text[], 'dumbbell', 'strength', 'beginner', 'This corrective exercise strengthens the muscles that stabilize your shoulder blade. Hold a light weight in each hand, hanging at your sides. Your thumbs should pointing up. Begin the movement raising your arms out in front of you, about 30 degrees off center. Your arms should be fully extended as you perform the movement. Continue until your arms are parallel to the ground, and then return to the starting position.'),
('Dumbbell_Seated_Box_Jump', 'Dumbbell Seated Box Jump', 'legs', ARRAY['legs','legs','legs']::text[], 'dumbbell', 'plyometrics', 'intermediate', 'Position a box a couple feet to the side of a bench. Hold a dumbbell to your chest with both hands and seat yourself on the bench facing the box. This will be your starting position. Plant your feet firmly on the ground as you lean forward, extending through the hips and knees to jump up and forward. Land on the box with both feet, absorbing the impact by allowing the hips and knees to bend. Step down and return to the starting position.'),
('Dumbbell_Seated_One-Leg_Calf_Raise', 'Dumbbell Seated One-Leg Calf Raise', 'legs', ARRAY[]::text[], 'dumbbell', 'strength', 'beginner', 'Place a block on the floor about 12 inches from a flat bench. Sit on a flat bench and place a dumbbell on your upper left thigh about 3 inches above your knee. Now place the ball of your left foot on the block. This will be your starting position. Raise your toes up as high as possible as you exhale and you contract your calf muscle. Hold the contraction for a second. Slowly return to the starting position, stretching as far down as possible. Repeat for your prescribed number of repetitions and '),
('Dumbbell_Shoulder_Press', 'Dumbbell Shoulder Press', 'shoulders', ARRAY['arms']::text[], 'dumbbell', 'strength', 'intermediate', 'While holding a dumbbell in each hand, sit on a military press bench or utility bench that has back support. Place the dumbbells upright on top of your thighs. Now raise the dumbbells to shoulder height one at a time using your thighs to help propel them up into position. Make sure to rotate your wrists so that the palms of your hands are facing forward. This is your starting position. Now, exhale and push the dumbbells upward until they touch at the top. Then, after a brief pause at the top con'),
('Dumbbell_Shrug', 'Dumbbell Shrug', 'back', ARRAY[]::text[], 'dumbbell', 'strength', 'beginner', 'Stand erect with a dumbbell on each hand (palms facing your torso), arms extended on the sides. Lift the dumbbells by elevating the shoulders as high as possible while you exhale. Hold the contraction at the top for a second. Tip: The arms should remain extended at all times. Refrain from using the biceps to help lift the dumbbells. Only the shoulders should be moving up and down. Lower the dumbbells back to the original position. Repeat for the recommended amount of repetitions.'),
('Dumbbell_Side_Bend', 'Dumbbell Side Bend', 'core', ARRAY[]::text[], 'dumbbell', 'strength', 'beginner', 'Stand up straight while holding a dumbbell on the left hand (palms facing the torso) as you have the right hand holding your waist. Your feet should be placed at shoulder width. This will be your starting position. While keeping your back straight and your head up, bend only at the waist to the right as far as possible. Breathe in as you bend to the side. Then hold for a second and come back up to the starting position as you exhale. Tip: Keep the rest of the body stationary. Now repeat the move'),
('Dumbbell_Squat', 'Dumbbell Squat', 'legs', ARRAY['legs','legs','legs','back']::text[], 'dumbbell', 'strength', 'beginner', 'Stand up straight while holding a dumbbell on each hand (palms facing the side of your legs). Position your legs using a shoulder width medium stance with the toes slightly pointed out. Keep your head up at all times as looking down will get you off balance and also maintain a straight back. This will be your starting position. Note: For the purposes of this discussion we will use the medium stance described above which targets overall development; however you can choose any of the three stances'),
('Dumbbell_Squat_To_A_Bench', 'Dumbbell Squat To A Bench', 'legs', ARRAY['legs','legs','legs','back']::text[], 'dumbbell', 'strength', 'intermediate', 'Stand up straight with a flat bench behind you while holding a dumbbell on each hand (palms facing the side of your legs). Position your legs using a shoulder width medium stance with the toes slightly pointed out. Keep your head up at all times as looking down will get you off balance and also maintain a straight back. This will be your starting position. Note: For the purposes of this discussion we will use the medium stance described above which targets overall development; however you can ch'),
('Dumbbell_Step_Ups', 'Dumbbell Step Ups', 'legs', ARRAY['legs','legs','legs']::text[], 'dumbbell', 'strength', 'intermediate', 'Stand up straight while holding a dumbbell on each hand (palms facing the side of your legs). Place the right foot on the elevated platform. Step on the platform by extending the hip and the knee of your right leg. Use the heel mainly to lift the rest of your body up and place the foot of the left leg on the platform as well. Breathe out as you execute the force required to come up. Step down with the left leg by flexing the hip and knee of the right leg as you inhale. Return to the original sta'),
('Dumbbell_Tricep_Extension_-Pronated_Grip', 'Dumbbell Tricep Extension -Pronated Grip', 'arms', ARRAY[]::text[], 'dumbbell', 'strength', 'beginner', 'Lie down on a flat bench holding two dumbbells directly above your shoulders. Your arms should be fully extended and form a 90 degree angle from your torso and the floor. The palms of your hands should be facing forward, and your elbows should be tucked in. This will be your starting position. Now, inhale and slowly lower the dumbbells until they are near your ears. Be sure to keep your upper arms stationary and your elbows tucked in. Then, exhale and use your triceps to return the weight to the')
INSERT INTO exercises (external_id, name, muscle_group, secondary_muscles, equipment, category, level, instructions) VALUES
('Dynamic_Back_Stretch', 'Dynamic Back Stretch', 'back', ARRAY[]::text[], 'other', 'stretching', 'beginner', 'Stand with your feet shoulder width apart. This will be your starting position. Keeping your arms straight, swing them straight up in front of you 5-10 times, increasing the range of motion each time until your arms are above your head.'),
('Dynamic_Chest_Stretch', 'Dynamic Chest Stretch', 'chest', ARRAY['back']::text[], 'other', 'stretching', 'beginner', 'Stand with your hands together, arms extended directly in front of you. This will be your starting position. Keeping your arms straight, quickly move your arms back as far as possible and back in again, similar to an exaggerated clapping motion. Repeat 5-10 times, increasing speed as you do so.'),
('EZ-Bar_Curl', 'EZ-Bar Curl', 'arms', ARRAY[]::text[], 'barbell', 'strength', 'beginner', 'Stand up straight while holding an EZ curl bar at the wide outer handle. The palms of your hands should be facing forward and slightly tilted inward due to the shape of the bar. Keep your elbows close to your torso. This will be your starting position. Now, while keeping your upper arms stationary, exhale and curl the weights forward while contracting the biceps. Focus on only moving your forearms. Continue to raise the weight until your biceps are fully contracted and the bar is at shoulder lev'),
('EZ-Bar_Skullcrusher', 'EZ-Bar Skullcrusher', 'arms', ARRAY['arms']::text[], 'barbell', 'strength', 'beginner', 'Using a close grip, lift the EZ bar and hold it with your elbows in as you lie on the bench. Your arms should be perpendicular to the floor. This will be your starting position. Keeping the upper arms stationary, lower the bar by allowing the elbows to flex. Inhale as you perform this portion of the movement. Pause once the bar is directly above the forehead. Lift the bar back to the starting position by extending the elbow and exhaling. Repeat.'),
('Elbow_Circles', 'Elbow Circles', 'shoulders', ARRAY['back']::text[], 'other', 'stretching', 'beginner', 'Sit or stand with your feet slightly apart. Place your hands on your shoulders with your elbows at shoulder level and pointing out. Slowly make a circle with your elbows. Breathe out as you start the circle and breathe in as you complete the circle.'),
('Elbow_to_Knee', 'Elbow to Knee', 'core', ARRAY[]::text[], 'bodyweight', 'strength', 'beginner', 'Lie on the floor, crossing your right leg across your bent left knee. Clasp your hands behind your head, beginning with your shoulder blades on the ground. This will be your starting position. Perform the motion by flexing the spine and rotating your torso to bring the left elbow to the right knee. Return to the starting position and repeat the movement for the desired number of repetitions before switching sides.'),
('Elbows_Back', 'Elbows Back', 'chest', ARRAY['shoulders']::text[], 'other', 'stretching', 'beginner', 'Stand up straight. Place both hands on your lower back, fingers pointing downward and elbows out. Then gently pull your elbows back aiming to touch them together.'),
('Elevated_Back_Lunge', 'Elevated Back Lunge', 'legs', ARRAY['legs','legs']::text[], 'barbell', 'strength', 'intermediate', 'Position a bar onto a rack at shoulder height loaded to an appropriate weight. Place a short, raised platform behind you. Rack the bar onto your upper back, keeping your back arched and tight. Step onto your raised platform with both feet. This will be your starting position. Begin by stepping backwards with one leg. Descend by flexing your hips and knees until your knee touches the floor. Pause, and extend through the hips and knees to rise up, returning all the way to the starting position bef'),
('Elevated_Cable_Rows', 'Elevated Cable Rows', 'back', ARRAY['back','back']::text[], 'cable', 'strength', 'intermediate', 'Get a platform of some sort (it can be an aerobics or calf raise platform) that is around 4-6 inches in height. Place it on the seat of the cable row machine. Sit down on the machine and place your feet on the front platform or crossbar provided making sure that your knees are slightly bent and not locked. Lean over as you keep the natural alignment of your back and grab the V-bar handles. With your arms extended pull back until your torso is at a 90-degree angle from your legs. Your back should'),
('Elliptical_Trainer', 'Elliptical Trainer', 'legs', ARRAY['legs','legs','legs']::text[], 'machine', 'cardio', 'intermediate', 'To begin, step onto the elliptical and select the desired option from the menu. Most ellipticals have a manual setting, or you can select a program to run. Typically, you can enter your age and weight to estimate the amount of calories burned during exercise. Elevation can be adjusted to change the intensity of the workout. The handles can be used to monitor your heart rate to help you stay at an appropriate intensity.'),
('Exercise_Ball_Crunch', 'Exercise Ball Crunch', 'core', ARRAY[]::text[], 'other', 'strength', 'beginner', 'Lie on an exercise ball with your lower back curvature pressed against the spherical surface of the ball. Your feet should be bent at the knee and pressed firmly against the floor. The upper torso should be hanging off the top of the ball. The arms should either be kept alongside the body or crossed on top of your chest as these positions avoid neck strains (as opposed to the hands behind the back of the head position). Lower your torso into a stretch position keeping the neck stationary at all '),
('Exercise_Ball_Pull-In', 'Exercise Ball Pull-In', 'core', ARRAY[]::text[], 'other', 'strength', 'beginner', 'Place an exercise ball nearby and lay on the floor in front of it with your hands on the floor shoulder width apart in a push-up position. Now place your lower shins on top of an exercise ball. Tip: At this point your legs should be fully extended with the shins on top of the ball and the upper body should be in a push-up type of position being supported by your two extended arms in front of you. This will be your starting position. While keeping your back completely straight and the upper body '),
('Extended_Range_One-Arm_Kettlebell_Floor_Press', 'Extended Range One-Arm Kettlebell Floor Press', 'chest', ARRAY['shoulders','arms']::text[], 'kettlebell', 'strength', 'beginner', 'Lie on the floor and position a kettlebell for one arm to press. The kettlebell should be held by the handle. The leg on the same side that you are pressing should be bent, with the knee crossing over the midline of the body. Press the kettlebell by extending the elbow and adducting the arm, pressing it above your body. Return to the starting position.'),
('External_Rotation', 'External Rotation', 'shoulders', ARRAY[]::text[], 'dumbbell', 'strength', 'beginner', 'Lie sideways on a flat bench with one arm holding a dumbbell and the other hand on top of the bench folded so that you can rest your head on it. Bend the elbows of the arm holding the dumbbell so that it creates a 90-degree angle between the upper arm and the forearm. Tip: Keep the arm parallel to your torso. Now bend the elbow while keeping the upper arm stationary. In this manner, the forearm will be parallel to the floor and perpendicular to your torso (Tip: So the forearm will be directly in'),
('External_Rotation_with_Band', 'External Rotation with Band', 'shoulders', ARRAY[]::text[], 'bands', 'strength', 'beginner', 'Choke the band around a post. The band should be at the same height as your elbow. Stand with your left side to the band a couple of feet away. Grasp the end of the band with your right hand, and keep your elbow pressed firmly to your side. We recommend you hold a pad or foam roll in place with your elbow to keep it firmly in position. With your upper arm in position, your elbow should be flexed to 90 degrees with your hand reaching across the front of your torso. This will be your starting posi'),
('External_Rotation_with_Cable', 'External Rotation with Cable', 'shoulders', ARRAY[]::text[], 'cable', 'strength', 'beginner', 'Adjust the cable to the same height as your elbow. Stand with your left side to the band a couple of feet away. Grasp the handle with your right hand, and keep your elbow pressed firmly to your side. We recommend you hold a pad or foam roll in place with your elbow to keep it firmly in position. With your upper arm in position, your elbow should be flexed to 90 degrees with your hand reaching across the front of your torso. This will be your starting position. Execute the movement by rotating yo'),
('Face_Pull', 'Face Pull', 'shoulders', ARRAY['back']::text[], 'cable', 'strength', 'intermediate', 'Facing a high pulley with a rope or dual handles attached, pull the weight directly towards your face, separating your hands as you do so. Keep your upper arms parallel to the ground.'),
('Farmers_Walk', 'Farmer''s Walk', 'arms', ARRAY['core','legs','legs','back','legs','back']::text[], 'other', 'strongman', 'intermediate', 'There are various implements that can be used for the farmers walk. These can also be performed with heavy dumbbells or short bars if these implements aren''t available. Begin by standing between the implements. After gripping the handles, lift them up by driving through your heels, keeping your back straight and your head up. Walk taking short, quick steps, and don''t forget to breathe. Move for a given distance, typically 50-100 feet, as fast as possible.'),
('Fast_Skipping', 'Fast Skipping', 'legs', ARRAY['legs','legs','legs','legs','legs']::text[], 'bodyweight', 'plyometrics', 'beginner', 'Start in a relaxed position with one leg slightly forward. This will be your starting position. Skip by executing a step-hop pattern of right-right-step to left-left-step, and so on, alternating back and forth. Perform fast skips by maintaining close contact with the ground and reduce air time, moving as quickly as possible.'),
('Finger_Curls', 'Finger Curls', 'arms', ARRAY[]::text[], 'barbell', 'strength', 'beginner', 'Hold a barbell with both hands and your palms facing up; hands spaced about shoulder width. Place your feet flat on the floor, at a distance that is slightly wider than shoulder width apart. This will be your starting position. Lower the bar as far as possible by extending the fingers. Allowing the bar to roll down the hands, catch the bar with the final joint in the fingers. Now curl bar up as high as possible by closing your hands while exhaling. Hold the contraction at the top.'),
('Flat_Bench_Cable_Flyes', 'Flat Bench Cable Flyes', 'chest', ARRAY[]::text[], 'cable', 'strength', 'intermediate', 'Position a flat bench between two low pulleys so that when you are laying on it, your chest will be lined up with the cable pulleys. Lay flat on the bench and keep your feet on the ground. Have someone hand you the handles on each hand. You will grab each single handle attachment with a palms up grip. Extend your arms by your side with a slight bend on your elbows. Tip: You will keep this bend constant through the whole movement. Your arms should be parallel to the floor. This is your starting p'),
('Flat_Bench_Leg_Pull-In', 'Flat Bench Leg Pull-In', 'core', ARRAY[]::text[], 'bodyweight', 'strength', 'beginner', 'Lie on an exercise mat or a flat bench with your legs off the end. Place your hands either under your glutes with your palms down or by the sides holding on to the bench (or with palms down by the side on an exercise mat). Also extend your legs straight out. This will be your starting position. Bend your knees and pull your upper thighs into your midsection as you breathe out. Continue this movement until your knees are near your chest. Hold the contracted position for a second. As you breathe i'),
('Flat_Bench_Lying_Leg_Raise', 'Flat Bench Lying Leg Raise', 'core', ARRAY[]::text[], 'bodyweight', 'strength', 'beginner', 'Lie with your back flat on a bench and your legs extended in front of you off the end. Place your hands either under your glutes with your palms down or by the sides holding on to the bench. This will be your starting position. As you keep your legs extended, straight as possible with your knees slightly bent but locked raise your legs until they make a 90-degree angle with the floor. Exhale as you perform this portion of the movement and hold the contraction at the top for a second. Now, as you'),
('Flexor_Incline_Dumbbell_Curls', 'Flexor Incline Dumbbell Curls', 'arms', ARRAY[]::text[], 'dumbbell', 'strength', 'beginner', 'Hold the dumbbell towards the side farther from you so that you have more weight on the side closest to you. (This can be done for a good effect on all bicep dumbbell exercises). Now do a normal incline dumbbell curl, but keep your wrists as far back as possible so as to neutralize any stress that is placed on them. Sit on an incline bench that is angled at 45-degrees while holding a dumbbell on each hand. Let your arms hang down on your sides, with the elbows in, and turn the palms of your hand'),
('Floor_Glute-Ham_Raise', 'Floor Glute-Ham Raise', 'legs', ARRAY['legs','legs']::text[], 'other', 'strength', 'intermediate', 'You can use a partner for this exercise or brace your feet under something stable. Begin on your knees with your upper legs and torso upright. If using a partner, they will firmly hold your feet to keep you in position. This will be your starting position. Lower yourself by extending at the knee, taking care to NOT flex the hips as you go forward. Place your hands in front of you as you reach the floor. This movement is very difficult and you may be unable to do it unaided. Use your arms to ligh'),
('Floor_Press', 'Floor Press', 'arms', ARRAY['chest','shoulders']::text[], 'barbell', 'powerlifting', 'intermediate', 'Adjust the j-hooks so they are at the appropriate height to rack the bar. Begin lying on the floor with your head near the end of a power rack. Keeping your shoulder blades pulled together; pull the bar off of the hooks. Lower the bar towards the bottom of your chest or upper stomach, squeezing the bar and attempting to pull it apart as you do so. Ensure that you tuck your elbows throughout the movement. Lower the bar until your upper arm contacts the ground and pause, preventing any slamming or'),
('Floor_Press_with_Chains', 'Floor Press with Chains', 'arms', ARRAY['chest','shoulders']::text[], 'barbell', 'powerlifting', 'intermediate', 'Adjust the j-hooks so they are at the appropriate height to rack the bar. For this exercise, drape the chains directly over the end of the bar, trying to keep the ends away from the plates. Begin lying on the floor with your head near the end of a power rack. Keeping your shoulder blades pulled together, pull the bar off of the hooks. Lower the bar towards the bottom of your chest or upper stomach, squeezing the bar and attempting to pull it apart as you do so. Ensure that you tuck your elbows t'),
('Flutter_Kicks', 'Flutter Kicks', 'legs', ARRAY['legs']::text[], 'bodyweight', 'strength', 'beginner', 'On a flat bench lie facedown with the hips on the edge of the bench, the legs straight with toes high off the floor and with the arms on top of the bench holding on to the front edge. Squeeze your glutes and hamstrings and straighten the legs until they are level with the hips. This will be your starting position. Start the movement by lifting the left leg higher than the right leg. Then lower the left leg as you lift the right leg. Continue alternating in this manner (as though you are doing a '),
('Foot-SMR', 'Foot-SMR', 'legs', ARRAY[]::text[], 'other', 'stretching', 'intermediate', 'This exercise stretches the fascia of the muscles in the feet. Start off seated with your shoes removed. Using a foot roller or a similar object, such as a small section of pvc pipe, place your foot against the roller across the arch of your foot. This will be your starting position. Press down firmly, rolling across the arch of your foot. Hold for 10-30 seconds, and then switch feet.'),
('Forward_Drag_with_Press', 'Forward Drag with Press', 'chest', ARRAY['legs','legs','legs','legs','shoulders','arms']::text[], 'other', 'strongman', 'intermediate', 'Attach a dual handled chain or rope attachment to the sled. You should be facing away from the sled, holding a handle in each hand. Begin the movement by moving forward for one step. Leaning forward, extend through the legs and hips to move, pausing with each step to extend through the elbows, pressing your hands forward. Step forward until you return to the start position prepared to press.'),
('Frankenstein_Squat', 'Frankenstein Squat', 'legs', ARRAY['core','legs','legs','legs']::text[], 'barbell', 'olympic weightlifting', 'intermediate', 'This drill teaches you the proper positioning of both the bar and your body during the clean and front squat. Place the barbell on the front of the shoulders, releasing your grip and extending your arms out in front of you. The shoulders should be pushed forward to create a shelf, and the bar should be in contact with the throat. Ensure that you only move your shoulder blades forward; don''t round the thoracic spine. Squat by flexing the knees and hips, sitting in between your legs. Keep the tor'),
('Freehand_Jump_Squat', 'Freehand Jump Squat', 'legs', ARRAY['legs','legs','legs']::text[], 'bodyweight', 'strength', 'intermediate', 'Cross your arms over your chest. With your head up and your back straight, position your feet at shoulder width. Keeping your back straight and chest up, squat down as you inhale until your upper thighs are parallel, or lower, to the floor. Now pressing mainly with the ball of your feet, jump straight up in the air as high as possible, using the thighs like springs. Exhale during this portion of the movement. When you touch the floor again, immediately squat down and jump again. Repeat for the r'),
('Frog_Hops', 'Frog Hops', 'legs', ARRAY['legs','legs','legs']::text[], 'other', 'stretching', 'intermediate', 'Stand with your hands behind your head, and squat down keeping your torso upright and your head up. This will be your starting position. Jump forward several feet, avoiding jumping unnecessarily high. As your feet contact the ground, absorb the impact through your legs, and jump again. Repeat this action 5-10 times.'),
('Frog_Sit-Ups', 'Frog Sit-Ups', 'core', ARRAY[]::text[], 'bodyweight', 'strength', 'intermediate', 'Lie with your back flat on the floor (or exercise mat) and your legs extended in front of you. Now bend at the knees and place your outer thighs by the floor (or mat) as you make the soles of your feet touch each other. Now try pushing both soles and bringing them up as near you as possible while you keep the outer thighs on the floor (or at least almost touching it). Tip: In this position your legs should create a diamond shape. Now, cross your arms in front of you by touching the opposite shou'),
('Front_Barbell_Squat', 'Front Barbell Squat', 'legs', ARRAY['legs','legs','legs']::text[], 'barbell', 'strength', 'expert', 'This exercise is best performed inside a squat rack for safety purposes. To begin, first set the bar on a rack that best matches your height. Once the correct height is chosen and the bar is loaded, bring your arms up under the bar while keeping the elbows high and the upper arm slightly above parallel to the floor. Rest the bar on top of the deltoids and cross your arms while grasping the bar for total control. Lift the bar off the rack by first pushing with your legs and at the same time strai'),
('Front_Barbell_Squat_To_A_Bench', 'Front Barbell Squat To A Bench', 'legs', ARRAY['legs','legs','legs']::text[], 'barbell', 'strength', 'expert', 'This exercise is best performed inside a squat rack for safety purposes. To begin, first set a flat bench behind you and set the bar on a rack that best matches your height. Once the correct height is chosen and the bar is loaded, bring your arms up under the bar while keeping the elbows high and the upper arm slightly above parallel to the floor. Rest the bar on top of the deltoids and cross your arms while grasping the bar for total control. Lift the bar off the rack by first pushing with your'),
('Front_Box_Jump', 'Front Box Jump', 'legs', ARRAY['legs','legs','legs','legs','legs']::text[], 'other', 'plyometrics', 'beginner', 'Begin with a box of an appropriate height 1-2 feet in front of you. Stand with your feet should width apart. This will be your starting position. Perform a short squat in preparation for jumping, swinging your arms behind you. Rebound out of this position, extending through the hips, knees, and ankles to jump as high as possible. Swing your arms forward and up. Land on the box with the knees bent, absorbing the impact through the legs. You can jump from the box back to the ground, or preferably '),
('Front_Cable_Raise', 'Front Cable Raise', 'shoulders', ARRAY[]::text[], 'cable', 'strength', 'beginner', 'Select the weight on a low pulley machine and grasp the single hand cable attachment that is attached to the low pulley with your left hand. Face away from the pulley and put your arm straight down with the hand cable attachment in front of your thighs at arms'' length with the palms of the hand facing your thighs. This will be your starting position. While maintaining the torso stationary (no swinging), lift the left arm to the front with a slight bend on the elbow and the palms of the hand alw'),
('Front_Cone_Hops_or_hurdle_hops', 'Front Cone Hops (or hurdle hops)', 'legs', ARRAY['legs','legs','legs','legs','legs']::text[], 'other', 'plyometrics', 'beginner', 'Set up a row of cones or other small barriers, placing them a few feet apart. Stand in front of the first cone with your feet shoulder width apart. This will be your starting position. Begin by jumping with both feet over the first cone, swinging both arms as you jump. Absorb the impact of landing by bending the knees, rebounding out of the first leap by jumping over the next cone. Continue until you have jumped over all of the cones.'),
('Front_Dumbbell_Raise', 'Front Dumbbell Raise', 'shoulders', ARRAY[]::text[], 'dumbbell', 'strength', 'beginner', 'Pick a couple of dumbbells and stand with a straight torso and the dumbbells on front of your thighs at arms length with the palms of the hand facing your thighs. This will be your starting position. While maintaining the torso stationary (no swinging), lift the left dumbbell to the front with a slight bend on the elbow and the palms of the hands always facing down. Continue to go up until you arm is slightly above parallel to the floor. Exhale as you execute this portion of the movement and pau'),
('Front_Incline_Dumbbell_Raise', 'Front Incline Dumbbell Raise', 'shoulders', ARRAY[]::text[], 'dumbbell', 'strength', 'beginner', 'Sit down on an incline bench with the incline set anywhere between 30 to 60 degrees while holding a dumbbell on each hand. Tip: You can change the angle to hit the muscle a little differently each time. Extend your arms straight in front of you and have your palms facing down with the dumbbells raised about 1 inch above your thighs. This will be your starting position. Slowly raise the dumbbells straight up until they are slightly above your shoulders, while keeping your elbows locked. Squeeze a'),
('Front_Leg_Raises', 'Front Leg Raises', 'legs', ARRAY[]::text[], 'bodyweight', 'stretching', 'beginner', 'Stand next to a chair or other support, holding on with one hand. Swing your leg forward, keeping the leg straight. Continue with a downward swing, bringing the leg as far back as your flexibility allows. Repeat 5-10 times, and then switch legs.'),
('Front_Plate_Raise', 'Front Plate Raise', 'shoulders', ARRAY[]::text[], 'other', 'strength', 'intermediate', 'While standing straight, hold a barbell plate in both hands at the 3 and 9 o''clock positions. Your palms should be facing each other and your arms should be extended and locked with a slight bend at the elbows and the plate should be down near your waist in front of you as far as you can go. Tip: The arms will remain in this position throughout the exercise. This will be your starting position. Slowly raise the plate as you exhale until it is a little above shoulder level. Hold the contraction '),
('Front_Raise_And_Pullover', 'Front Raise And Pullover', 'chest', ARRAY['back','shoulders','arms']::text[], 'barbell', 'strength', 'beginner', 'Lie on a flat bench while holding a barbell using a palms down grip that is about 15 inches apart. Place the bar on your upper thighs, extend your arms and lock them while keeping a slight bend on the elbows. This will be your starting position. Now raise the weight using a semicircular motion and keeping your arms straight as you inhale. Continue the same movement until the bar is on the other side above your head . (Tip: the bar will travel approximately 180-degrees). At this point your arms s'),
('Front_Squat_Clean_Grip', 'Front Squat (Clean Grip)', 'legs', ARRAY['core','legs','legs']::text[], 'barbell', 'strength', 'intermediate', 'To begin, first set the bar in a rack slightly below shoulder level. Rest the bar on top of the deltoids, pushing into the clavicles, and lightly touching the throat. Your hands should be in a clean grip, touching the bar only with your fingers to help keep it in position. Lift the bar off the rack by first pushing with your legs and at the same time straightening your torso. Step away from the rack and position your legs using a shoulder width medium stance with the toes slightly pointed out. K'),
('Front_Squats_With_Two_Kettlebells', 'Front Squats With Two Kettlebells', 'legs', ARRAY['legs','legs']::text[], 'kettlebell', 'strength', 'intermediate', 'Clean two kettlebells to your shoulders. Clean the kettlebells to your shoulders by extending through the legs and hips as you pull the kettlebells towards your shoulders. Rotate your wrists as you do so. Looking straight ahead at all times, squat as low as you can and pause at the bottom. As you squat down, push your knees out. You should squat between your legs, keeping an upright torso, with your head and chest up. Rise back up by driving through your heels and repeat.'),
('Front_Two-Dumbbell_Raise', 'Front Two-Dumbbell Raise', 'shoulders', ARRAY[]::text[], 'dumbbell', 'strength', 'beginner', 'Pick a couple of dumbbells and stand with a straight torso and the dumbbells on front of your thighs at arms length with the palms of the hand facing your thighs. This will be your starting position. While maintaining the torso stationary (no swinging), lift the dumbbells to the front with a slight bend on the elbow and the palms of the hands always facing down. Continue to go up until you arms are slightly above parallel to the floor. Exhale as you execute this portion of the movement and pause'),
('Full_Range-Of-Motion_Lat_Pulldown', 'Full Range-Of-Motion Lat Pulldown', 'back', ARRAY['arms','back','shoulders']::text[], 'cable', 'strength', 'intermediate', 'Either standing or seated on a high bench, grasp two stirrup cables that are attached to the high pulleys. Grab with the opposing hand so your arms are crisscrossed about you and your palms are facing forward. Keeping your chest up and maintaining a slight arch in your lower back, pull the handles down as if you were doing a regular pulldown. The range of motion will be more of an arc. During the movement, rotate your hands so that in the bottom position your palms face each other rather than fo'),
('Gironda_Sternum_Chins', 'Gironda Sternum Chins', 'back', ARRAY['arms','back']::text[], 'other', 'strength', 'intermediate', 'Grasp the pull-up bar with a shoulder width underhand grip. Now hang with your arms fully extended and stick your chest out and lean back. Tip: You will be leaning back throughout the entire movement. This will be your starting position. Start pulling yourself towards the bar with your spine arched throughout the movement and your head leaning back as far away from the bar as possible. Exhale as you perform this portion of the movement. Tip: At the upper end of the movement, your hips and legs w'),
('Glute_Ham_Raise', 'Glute Ham Raise', 'legs', ARRAY['legs','legs']::text[], 'machine', 'powerlifting', 'intermediate', 'Begin by adjusting the equipment to fit your body. Place your feet against the footplate in between the rollers as you lie facedown. Your knees should be just behind the pad. Start from the bottom of the movement. Keep your back arched as you begin the movement by flexing the knees. Drive your toes into the foot plate as you do so. Keep your upper body straight, and continue until your body is upright. Return to the starting position, keeping your descent under control.')
INSERT INTO exercises (external_id, name, muscle_group, secondary_muscles, equipment, category, level, instructions) VALUES
('Glute_Kickback', 'Glute Kickback', 'legs', ARRAY['legs']::text[], 'bodyweight', 'strength', 'beginner', 'Kneel on the floor or an exercise mat and bend at the waist with your arms extended in front of you (perpendicular to the torso) in order to get into a kneeling push-up position but with the arms spaced at shoulder width. Your head should be looking forward and the bend of the knees should create a 90-degree angle between the hamstrings and the calves. This will be your starting position. As you exhale, lift up your right leg until the hamstrings are in line with the back while maintaining the 9'),
('Goblet_Squat', 'Goblet Squat', 'legs', ARRAY['legs','legs','legs','shoulders']::text[], 'kettlebell', 'strength', 'beginner', 'Stand holding a light kettlebell by the horns close to your chest. This will be your starting position. Squat down between your legs until your hamstrings are on your calves. Keep your chest and head up and your back straight. At the bottom position, pause and use your elbows to push your knees out. Return to the starting position, and repeat for 10-20 repetitions.'),
('Good_Morning', 'Good Morning', 'legs', ARRAY['core','legs','back']::text[], 'barbell', 'powerlifting', 'intermediate', 'Begin with a bar on a rack at shoulder height. Rack the bar across the rear of your shoulders as you would a power squat, not on top of your shoulders. Keep your back tight, shoulder blades pinched together, and your knees slightly bent. Step back from the rack. Begin by bending at the hips, moving them back as you bend over to near parallel. Keep your back arched and your cervical spine in proper alignment. Reverse the motion by extending through the hips with your glutes and hamstrings. Contin'),
('Good_Morning_off_Pins', 'Good Morning off Pins', 'legs', ARRAY['core','legs','back']::text[], 'barbell', 'powerlifting', 'intermediate', 'Begin with a bar on a rack at about the same height as your stomach. Bend over underneath the bar and rack the bar across the rear of your shoulders as you would a power squat, not on top of your shoulders. At the proper height, you should be near parallel to the floor when bent over. Keep your back tight, shoulder blades pinched together, and your knees slightly bent. Keep your back arched and your cervical spine in proper alignment. Begin the motion by extending through the hips with your glut'),
('Gorilla_Chin_Crunch', 'Gorilla Chin/Crunch', 'core', ARRAY['arms','back']::text[], 'bodyweight', 'strength', 'intermediate', 'Hang from a chin-up bar using an underhand grip (palms facing you) that is slightly wider than shoulder width. Now bend your knees at a 90 degree angle so that the calves are parallel to the floor while the thighs remain perpendicular to it. This will be your starting position. As you exhale, pull yourself up while crunching your knees up at the same time until your knees are at chest level. You will stop going up as soon as your nose is at the same level as the bar. Tip: When you get to this po'),
('Groin_and_Back_Stretch', 'Groin and Back Stretch', 'legs', ARRAY[]::text[], 'other', 'stretching', 'intermediate', 'Sit on the floor with your knees bent and feet together. Interlock your fingers behind your head. This will be your starting position. Curl downwards, bringing your elbows to the inside of your thighs. After a brief pause, return to the starting position with your head up and your back straight. Repeat for 10-20 repetitions.'),
('Groiners', 'Groiners', 'legs', ARRAY[]::text[], 'bodyweight', 'stretching', 'intermediate', 'Begin in a pushup position on the floor. This will be your starting position. Using both legs, jump forward landing with your feet next to your hands. Keep your head up as you do so. Return to the starting position and immediately repeat the movement, continuing for 10-20 repetitions.'),
('Hack_Squat', 'Hack Squat', 'legs', ARRAY['legs','legs','legs']::text[], 'machine', 'strength', 'beginner', 'Place the back of your torso against the back pad of the machine and hook your shoulders under the shoulder pads provided. Position your legs in the platform using a shoulder width medium stance with the toes slightly pointed out. Tip: Keep your head up at all times and also maintain the back on the pad at all times. Place your arms on the side handles of the machine and disengage the safety bars (which on most designs is done by moving the side handles from a facing front position to a diagonal'),
('Hammer_Curls', 'Hammer Curls', 'arms', ARRAY[]::text[], 'dumbbell', 'strength', 'beginner', 'Stand up with your torso upright and a dumbbell on each hand being held at arms length. The elbows should be close to the torso. The palms of the hands should be facing your torso. This will be your starting position. Now, while holding your upper arm stationary, exhale and curl the weight forward while contracting the biceps. Continue to raise the weight until the biceps are fully contracted and the dumbbell is at shoulder level. Hold the contracted position for a brief moment as you squeeze th'),
('Hammer_Grip_Incline_DB_Bench_Press', 'Hammer Grip Incline DB Bench Press', 'chest', ARRAY['shoulders','arms']::text[], 'dumbbell', 'strength', 'beginner', 'Lie back on an incline bench with a dumbbell on each hand on top of your thighs. The palms of your hand will be facing each other. By using your thighs to help you get the dumbbells up, clean the dumbbells one arm at a time so that you can hold them at shoulder width. Once at shoulder width, keep the palms of your hands with a neutral grip (palms facing each other). Keep your elbows flared out with the upper arms in line with the shoulders (perpendicular to the torso) and the elbows bent creatin'),
('Hamstring-SMR', 'Hamstring-SMR', 'legs', ARRAY[]::text[], 'other', 'stretching', 'beginner', 'In a seated position, extend your legs over a foam roll so that it is position on the back of the upper legs. Place your hands to the side or behind you to help support your weight. This will be your starting position. Using your hands, lift your hips off of the floor and shift your weight on the foam roll to one leg. Relax the hamstrings of the leg you are stretching. Roll over the foam from below the hip to above the back of the knee, pausing at points of tension for 10-30 seconds. Repeat for '),
('Hamstring_Stretch', 'Hamstring Stretch', 'legs', ARRAY[]::text[], 'other', 'stretching', 'beginner', 'Lie on your back with one leg extended above you, with the hip at ninety degrees. Keep the other leg flat on the floor. Loop a belt, band, or rope over the ball of your foot. This will be your starting position. Pull on the belt to create tension in the calves and hamstrings. Hold this stretch for 10-30 seconds, and repeat with the other leg.'),
('Handstand_Push-Ups', 'Handstand Push-Ups', 'shoulders', ARRAY['arms']::text[], 'bodyweight', 'strength', 'expert', 'With your back to the wall bend at the waist and place both hands on the floor at shoulder width. Kick yourself up against the wall with your arms straight. Your body should be upside down with the arms and legs fully extended. Keep your whole body as straight as possible. Tip: If doing this for the first time, have a spotter help you. Also, make sure that you keep facing the wall with your head, rather than looking down. Slowly lower yourself to the ground as you inhale until your head almost t'),
('Hang_Clean', 'Hang Clean', 'legs', ARRAY['legs','arms','legs','legs','back','shoulders','back']::text[], 'barbell', 'olympic weightlifting', 'intermediate', 'Begin with a shoulder width, double overhand or hook grip, with the bar hanging at the mid thigh position. Your back should be straight and inclined slightly forward. Begin by aggressively extending through the hips, knees and ankles, driving the weight upward. As you do so, shrug your shoulders towards your ears. Immediately recover by driving through the heels, keeping the torso upright and elbows up. Continue until you have risen to a standing position.'),
('Hang_Clean_-_Below_the_Knees', 'Hang Clean - Below the Knees', 'legs', ARRAY['legs','arms','legs','legs','back','shoulders','back']::text[], 'barbell', 'olympic weightlifting', 'intermediate', 'Begin with a shoulder width, double overhand or hook grip, with the bar hanging just below the knees. Your back should be straight and inclined slightly forward. Begin by aggressively extending through the hips, knees and ankles, driving the weight upward. As you do so, shrug your shoulders towards your ears. As full extension is achieved, transition into the third pull by aggressively shrugging and flexing the arms with the elbows up and out. At peak extension, aggressively pull yourself down, '),
('Hang_Snatch', 'Hang Snatch', 'legs', ARRAY['core','legs','arms','legs','back','legs','shoulders','back']::text[], 'barbell', 'olympic weightlifting', 'expert', 'Begin with a wide grip on the bar, with an overhand or hook grip. The feet should be directly below the hips with the feet turned out. Your knees should be slightly bent, and the torso inclined forward. The spine should be fully extended and the head facing forward. The bar should be at the hips. This will be your starting position. Aggressively extend through the legs and hips. At peak extension, shrug the shoulders and allow the elbows to flex to the side. As you move your feet into the receiv'),
('Hang_Snatch_-_Below_Knees', 'Hang Snatch - Below Knees', 'legs', ARRAY['core','legs','arms','legs','back','legs','shoulders','back']::text[], 'barbell', 'olympic weightlifting', 'expert', 'Begin with a wide grip on the bar, with an overhand or hook grip. The feet should be directly below the hips with the feet turned out. Your knees should be slightly bent, and the torso inclined forward. The spine should be fully extended and the head facing forward. The bar should be just below the knees. This will be your starting position. Aggressively extend through the legs and hips. At peak extension, shrug the shoulders and allow the elbows to flex to the side. As you move your feet into t'),
('Hanging_Bar_Good_Morning', 'Hanging Bar Good Morning', 'legs', ARRAY['core','legs','back']::text[], 'barbell', 'powerlifting', 'intermediate', 'Begin with a bar on a rack at about the same height as your stomach. Suspend the bar using chains or suspension straps. Bend over underneath the bar and rack the bar across the rear of your shoulders as you would a power squat, not on top of your traps. At the proper height, you should be near parallel to the floor when bent over. Keep your back tight, shoulder blades pinched together, and your knees slightly bent. Keep your back arched and your cervical spine in proper alignment. Begin the moti'),
('Hanging_Leg_Raise', 'Hanging Leg Raise', 'core', ARRAY[]::text[], 'bodyweight', 'strength', 'expert', 'Hang from a chin-up bar with both arms extended at arms length in top of you using either a wide grip or a medium grip. The legs should be straight down with the pelvis rolled slightly backwards. This will be your starting position. Raise your legs until the torso makes a 90-degree angle with the legs. Exhale as you perform this movement and hold the contraction for a second or so. Go back slowly to the starting position as you breathe in. Repeat for the recommended amount of repetitions.'),
('Hanging_Pike', 'Hanging Pike', 'core', ARRAY[]::text[], 'bodyweight', 'strength', 'expert', 'Hang from a chin-up bar with your legs and feet together using an overhand grip (palms facing away from you) that is slightly wider than shoulder width. Tip: You may use wrist wraps in order to facilitate holding on to the bar. Now bend your knees at a 90 degree angle and bring the upper legs forward so that the calves are perpendicular to the floor while the thighs remain parallel to it. This will be your starting position. Pull your legs up as you exhale until you almost touch your shins with '),
('Heaving_Snatch_Balance', 'Heaving Snatch Balance', 'legs', ARRAY['core','arms','legs','legs','shoulders','arms']::text[], 'barbell', 'olympic weightlifting', 'intermediate', 'This drill helps you learn the snatch. Begin by holding a light weight across the back of the shoulders. Your feet should be slightly wider than hip width apart with the feet turned out, the same position that you would perform a squat with. Begin by dipping with the knees slightly, and popping back up to briefly unload the bar. Drive yourself underneath the bar, elevating it overhead as you descend into a full squat. Return to a standing position.'),
('Heavy_Bag_Thrust', 'Heavy Bag Thrust', 'chest', ARRAY['core','shoulders','arms']::text[], 'other', 'plyometrics', 'beginner', 'Utilize a heavy bag for this exercise. Assume an upright stance next to the bag, with your feet staggered, fairly wide apart. Place your hand on the bag at about chest height. This will be your starting position. Begin by twisting at the waist, pushing the bag forward as hard as possible. Perform this move quickly, pushing the bag away from your body. Receive the bag as it swings back by reversing these steps.'),
('High_Cable_Curls', 'High Cable Curls', 'arms', ARRAY[]::text[], 'cable', 'strength', 'intermediate', 'Stand between a couple of high pulleys and grab a handle in each arm. Position your upper arms in a way that they are parallel to the floor with the palms of your hands facing you. This will be your starting position. Curl the handles towards you until they are next to your ears. Make sure that as you do so you flex your biceps and exhale. The upper arms should remain stationary and only the forearms should move. Hold for a second in the contracted position as you squeeze the biceps. Slowly brin'),
('Hip_Circles_prone', 'Hip Circles (prone)', 'legs', ARRAY['legs']::text[], 'bodyweight', 'stretching', 'beginner', 'Position yourself on your hands and knees on the ground. Maintaining good posture, raise one bent knee off of the ground. This will be your starting position. Keeping the knee in a bent position, rotate the femur in an arc, attempting to make a big circle with your knee. Perform this slowly for a number of repetitions, and repeat on the other side.'),
('Hip_Extension_with_Bands', 'Hip Extension with Bands', 'legs', ARRAY['legs']::text[], 'bands', 'strength', 'beginner', 'Secure one end of the band to the lower portion of a post and attach the other to one ankle. Facing the attachment point of the band, hold on to the column to stabilize yourself. Keeping your head and your chest up, move the resisted leg back as far as you can while keeping the knee straight. Return the leg to the starting position.'),
('Hip_Flexion_with_Band', 'Hip Flexion with Band', 'legs', ARRAY[]::text[], 'bands', 'strength', 'beginner', 'Secure one end of the band to the lower portion of a post and attach the other to one ankle. Face away from the attachment point of the band. Keeping your head and your chest up, raise your knee up to 90 degrees and pause. Return the leg to the starting position.'),
('Hip_Lift_with_Band', 'Hip Lift with Band', 'legs', ARRAY['legs','legs']::text[], 'bands', 'powerlifting', 'beginner', 'After choosing a suitable band, lay down in the middle of the rack, after securing the band on either side of you. If your rack doesn''t have pegs, the band can be secured using heavy dumbbells or similar objects, just ensure they won''t move. Adjust your position so that the band is directly over your hips. Bend your knees and place your feet flat on the floor. Your hands can be on the floor or holding the band in position. Keeping your shoulders on the ground, drive through your heels to raise'),
('Hug_A_Ball', 'Hug A Ball', 'back', ARRAY['legs','legs']::text[], 'other', 'stretching', 'beginner', 'Seat yourself on the floor. Straddle an exercise ball between both legs and lower your hips down toward the floor. Hug your arms around the ball to support your body. Adjust your legs so that your feet are flat on the floor and your knees line up over your ankles. Keep a good grip on the ball so it doesn''t roll away from you and send you back onto your buttocks.'),
('Hug_Knees_To_Chest', 'Hug Knees To Chest', 'back', ARRAY['legs']::text[], 'other', 'stretching', 'beginner', 'Lie down on your back and pull both knees up to your chest. Hold your arms under the knees, not over (that would put to much pressure on your knee joints). Slowly pull the knees toward your shoulders. This also stretches your buttocks muscles.'),
('Hurdle_Hops', 'Hurdle Hops', 'legs', ARRAY['legs','legs','legs','legs','legs']::text[], 'other', 'plyometrics', 'beginner', 'Set up a row of hurdles or other small barriers, placing them a few feet apart. Stand in front of the first hurdle with your feet shoulder width apart. This will be your starting position. Begin by jumping with both feet over the first hurdle, swinging both arms as you jump. Absorb the impact of landing by bending the knees, rebounding out of the first leap by jumping over the next hurdle. Continue until you have jumped over all of the hurdles.'),
('Hyperextensions_Back_Extensions', 'Hyperextensions (Back Extensions)', 'back', ARRAY['legs','legs']::text[], 'other', 'strength', 'beginner', 'Lie face down on a hyperextension bench, tucking your ankles securely under the footpads. Adjust the upper pad if possible so your upper thighs lie flat across the wide pad, leaving enough room for you to bend at the waist without any restriction. With your body straight, cross your arms in front of you (my preference) or behind your head. This will be your starting position. Tip: You can also hold a weight plate for extra resistance in front of you under your crossed arms. Start bending forward'),
('Hyperextensions_With_No_Hyperextension_Bench', 'Hyperextensions With No Hyperextension Bench', 'back', ARRAY['legs','legs']::text[], 'bodyweight', 'strength', 'intermediate', 'With someone holding down your legs, slide yourself down to the edge a flat bench until your hips hang off the end of the bench. Tip: Your entire upper body should be hanging down towards the floor. Also, you will be in the same position as if you were on a hyperextension bench but the range of motion will be shorter due to the height of the flat bench vs. that of the hyperextension bench. With your body straight, cross your arms in front of you (my preference) or behind your head. This will be '),
('IT_Band_and_Glute_Stretch', 'IT Band and Glute Stretch', 'legs', ARRAY[]::text[], 'other', 'stretching', 'intermediate', 'Loop a belt, rope, or band around one of your feet, and swing that leg across your body to the opposite side, keeping the leg extended as you lay on the ground. This will be your starting position. Keeping your foot off of the floor, pull on the belt, using the tension to pull the toes up. Hold for 10-20 seconds, and repeat on the other side.'),
('Iliotibial_Tract-SMR', 'Iliotibial Tract-SMR', 'legs', ARRAY[]::text[], 'other', 'stretching', 'intermediate', 'Lay on your side, with the bottom leg placed onto a foam roller between the hip and the knee. The other leg can be crossed in front of you. Place as much of your weight as is tolerable onto your bottom leg; there is no need to keep your bottom leg in contact with the ground. Be sure to relax the muscles of the leg you are stretching. Roll your leg over the foam from you hip to your knee, pausing for 10-30 seconds at points of tension. Repeat with the opposite leg.'),
('Inchworm', 'Inchworm', 'legs', ARRAY[]::text[], 'bodyweight', 'stretching', 'beginner', 'Stand with your feet close together. Keeping your legs straight, stretch down and put your hands on the floor directly in front of you. This will be your starting position. Begin by walking your hands forward slowly, alternating your left and your right. As you do so, bend only at the hip, keeping your legs straight. Keep going until your body is parallel to the ground in a pushup position. Now, keep your hands in place and slowly take short steps with your feet, moving only a few inches at a ti'),
('Incline_Barbell_Triceps_Extension', 'Incline Barbell Triceps Extension', 'arms', ARRAY['arms']::text[], 'barbell', 'strength', 'intermediate', 'Hold a barbell with an overhand grip (palms down) that is a little closer together than shoulder width. Lie back on an incline bench set at any angle between 45-75-degrees. Bring the bar overhead with your arms extended and elbows in. The arms should be in line with the torso above the head. This will be your starting position. Now lower the bar in a semicircular motion behind your head until your forearms touch your biceps. Inhale as you perform this movement. Tip: Keep your upper arms stationa'),
('Incline_Bench_Pull', 'Incline Bench Pull', 'back', ARRAY['back','shoulders']::text[], 'barbell', 'strength', 'beginner', 'Grab a dumbbell in each hand and lie face down on an incline bench that is set to an incline that is approximately 30 degrees. Let the arms hang to your sides fully extended as they point to the floor. Turn the wrists until your hands have a pronated (palms down) grip. Now flare the elbows out. This will be your starting position. As you breathe out, start to pull the dumbbells up as if you are doing a reverse bench press. You will do this by bending at the elbows and bringing the upper arms up '),
('Incline_Cable_Chest_Press', 'Incline Cable Chest Press', 'chest', ARRAY['shoulders','arms']::text[], 'cable', 'strength', 'beginner', 'Adjust the weight to an appropriate amount and be seated, grasping the handles. Your upper arms should be about 45 degrees to the body, with your head and chest up. The elbows should be bent to about 90 degrees. This will be your starting position. Begin by extending through the elbow, pressing the handles together straight in front of you. Keep your shoulder blades retracted as you execute the movement. After pausing at full extension, return to the starting position, keeping tension on the cab'),
('Incline_Cable_Flye', 'Incline Cable Flye', 'chest', ARRAY['shoulders']::text[], 'cable', 'strength', 'intermediate', 'To get yourself into the starting position, set the pulleys at the floor level (lowest level possible on the machine that is below your torso). Place an incline bench (set at 45 degrees) in between the pulleys, select a weight on each one and grab a pulley on each hand. With a handle on each hand, lie on the incline bench and bring your hands together at arms length in front of your face. This will be your starting position. With a slight bend of your elbows (in order to prevent stress at the bi'),
('Incline_Dumbbell_Bench_With_Palms_Facing_In', 'Incline Dumbbell Bench With Palms Facing In', 'chest', ARRAY['shoulders','arms']::text[], 'dumbbell', 'strength', 'beginner', 'Lie back on an incline bench with a dumbbell on each hand on top of your thighs. The palms of your hand will be facing each other. By using your thighs to help you get the dumbbells up, clean the dumbbells one arm at a time so that you can hold them at shoulder width. Once at shoulder width, keep the palms of your hands with a neutral grip (palms facing each other). Keep your elbows flared out with the upper arms in line with the shoulders (perpendicular to the torso) and the elbows bent creatin'),
('Incline_Dumbbell_Curl', 'Incline Dumbbell Curl', 'arms', ARRAY[]::text[], 'dumbbell', 'strength', 'beginner', 'Sit back on an incline bench with a dumbbell in each hand held at arms length. Keep your elbows close to your torso and rotate the palms of your hands until they are facing forward. This will be your starting position. While holding the upper arm stationary, curl the weights forward while contracting the biceps as you breathe out. Only the forearms should move. Continue the movement until your biceps are fully contracted and the dumbbells are at shoulder level. Hold the contracted position for a'),
('Incline_Dumbbell_Flyes', 'Incline Dumbbell Flyes', 'chest', ARRAY['shoulders']::text[], 'dumbbell', 'strength', 'beginner', 'Hold a dumbbell on each hand and lie on an incline bench that is set to an incline angle of no more than 30 degrees. Extend your arms above you with a slight bend at the elbows. Now rotate the wrists so that the palms of your hands are facing you. Tip: The pinky fingers should be next to each other. This will be your starting position. As you breathe in, start to slowly lower the arms to the side while keeping the arms extended and while rotating the wrists until the palms of the hand are facing'),
('Incline_Dumbbell_Flyes_-_With_A_Twist', 'Incline Dumbbell Flyes - With A Twist', 'chest', ARRAY['shoulders']::text[], 'dumbbell', 'strength', 'beginner', 'Hold a dumbbell in each hand and lie on an incline bench that is set to an incline angle of no more than 30 degrees. Extend your arms above you with a slight bend at the elbows. Now rotate the wrists so that the palms of your hands are facing you. Tip: The pinky fingers should be next to each other. This will be your starting position. As you breathe in, start to slowly lower the arms to the side while keeping the arms extended and while rotating the wrists until the palms of the hand are facing'),
('Incline_Dumbbell_Press', 'Incline Dumbbell Press', 'chest', ARRAY['shoulders','arms']::text[], 'dumbbell', 'strength', 'beginner', 'Lie back on an incline bench with a dumbbell in each hand atop your thighs. The palms of your hands will be facing each other. Then, using your thighs to help push the dumbbells up, lift the dumbbells one at a time so that you can hold them at shoulder width. Once you have the dumbbells raised to shoulder width, rotate your wrists forward so that the palms of your hands are facing away from you. This will be your starting position. Be sure to keep full control of the dumbbells at all times. Then'),
('Incline_Hammer_Curls', 'Incline Hammer Curls', 'arms', ARRAY[]::text[], 'dumbbell', 'strength', 'beginner', 'Seat yourself on an incline bench with a dumbbell in each hand. You should pressed firmly against he back with your feet together. Allow the dumbbells to hang straight down at your side, holding them with a neutral grip. This will be your starting position. Initiate the movement by flexing at the elbow, attempting to keep the upper arm stationary. Continue to the top of the movement and pause, then slowly return to the start position.'),
('Incline_Inner_Biceps_Curl', 'Incline Inner Biceps Curl', 'arms', ARRAY[]::text[], 'dumbbell', 'strength', 'beginner', 'Hold a dumbbell in each hand and lie back on an incline bench. The dumbbells should be at arm''s length hanging at your sides and your palms should be facing out. This will be your starting position. Now as you exhale curl the weight outward and up while keeping your forearms in line with your side deltoids. Continue the curl until the dumbbells are at shoulder height and to the sides of your deltoids. Tip: The end of the movement should look similar to a double biceps pose. After a second contr'),
('Incline_Push-Up', 'Incline Push-Up', 'chest', ARRAY['shoulders','arms']::text[], 'bodyweight', 'strength', 'beginner', 'Stand facing bench or sturdy elevated platform. Place hands on edge of bench or platform, slightly wider than shoulder width. Position forefoot back from bench or platform with arms and body straight. Arms should be perpendicular to body. Keeping body straight, lower chest to edge of box or platform by bending arms. Push body up until arms are extended. Repeat.'),
('Incline_Push-Up_Close-Grip', 'Incline Push-Up Close-Grip', 'arms', ARRAY['chest','shoulders']::text[], 'bodyweight', 'strength', 'beginner', 'Stand facing a Smith machine bar or sturdy elevated platform at an appropriate height. Place your hands next to one another on the bar. Position your feet back from the bar with arms and body straight. This will be your starting position. Keeping your body straight, lower your chest to the bar by bending the arms. Return to the starting position by extending the elbows, pressing yourself back up.'),
('Incline_Push-Up_Depth_Jump', 'Incline Push-Up Depth Jump', 'chest', ARRAY['shoulders','arms']::text[], 'other', 'plyometrics', 'beginner', 'For this drill you will need a box about 12 inches high, and two thick mats or aerobics steps. Place the steps just outside of your shoulders, and place your feet on top of the box so that you are in an incline pushup position, your hands just inside the steps. This will be your starting position. Begin by bending at the elbows to lower your body, quickly reversing position to push your body off of the ground. As you leave the ground, move your hands onto the steps, bending your elbows to absorb'),
('Incline_Push-Up_Medium', 'Incline Push-Up Medium', 'chest', ARRAY['core','shoulders','arms']::text[], 'bodyweight', 'strength', 'beginner', 'Stand facing a Smith machine bar or sturdy elevated platform at an appropriate height. Place your hands on the bar, with your hands about shoulder width apart. Position your feet back from the bar with arms and body straight. This will be your starting position. Keeping your body straight, lower your chest to the bar by bending the arms. Return to the starting position by extending the elbows, pressing yourself back up.')
INSERT INTO exercises (external_id, name, muscle_group, secondary_muscles, equipment, category, level, instructions) VALUES
('Incline_Push-Up_Reverse_Grip', 'Incline Push-Up Reverse Grip', 'chest', ARRAY['core','shoulders','arms']::text[], 'bodyweight', 'strength', 'beginner', 'Stand facing a Smith machine bar or sturdy elevated platform at an appropriate height. Place your hands on the bar palms up, with your hands about shoulder width apart. Position your feet back from the bar with arms and body straight. This will be your starting position. Keeping your body straight, lower your chest to the bar by bending the arms. Return to the starting position by extending the elbows, pressing yourself back up.'),
('Incline_Push-Up_Wide', 'Incline Push-Up Wide', 'chest', ARRAY['core','shoulders','arms']::text[], 'bodyweight', 'strength', 'beginner', 'Stand facing a Smith machine bar or sturdy elevated platform at an appropriate height. Place your hands on the bar, with your hands wider than shoulder width. Position your feet back from the bar with arms and body straight. Your arms should be perpendicular to the body. This will be your starting position. Keeping your body straight, lower your chest to the bar by bending the arms. Return to the starting position by extending the elbows, pressing yourself back up.'),
('Intermediate_Groin_Stretch', 'Intermediate Groin Stretch', 'legs', ARRAY[]::text[], 'other', 'stretching', 'intermediate', 'Lie on your back with your legs extended. Loop a belt, rope, or band around one of your feet, and swing that leg as far to the side as you can. This will be your starting position. Pull gently on the belt to create tension in your groin and hamstring muscles. Hold for 10-20 seconds, and repeat on the other side.'),
('Intermediate_Hip_Flexor_and_Quad_Stretch', 'Intermediate Hip Flexor and Quad Stretch', 'legs', ARRAY[]::text[], 'other', 'stretching', 'intermediate', 'Lie face down on the floor, with a rope, belt, or band looped around one foot. Flex the knee and extend the hip of the leg to be stretched, using both hands to pull on the belt. Your knee and your hip should come off of the floor, creating tension in the hip flexors and quadriceps. Hold the stretch for 10-20 seconds, and repeat on the other leg.'),
('Internal_Rotation_with_Band', 'Internal Rotation with Band', 'shoulders', ARRAY[]::text[], 'bands', 'strength', 'beginner', 'Choke the band around a post. The band should be at the same height as your elbow. Stand with your right side to the band a couple of feet away. Grasp the end of the band with your right hand, and keep your elbow pressed firmly to your side. We recommend you hold a pad or foam roll in place with your elbow to keep it firmly in position. With your upper arm in position, your elbow should be flexed to 90 degrees with your hand reaching away from your torso. This will be your starting position. Exe'),
('Inverted_Row', 'Inverted Row', 'back', ARRAY['back']::text[], 'other', 'strength', 'beginner', 'Position a bar in a rack to about waist height. You can also use a smith machine. Take a wider than shoulder width grip on the bar and position yourself hanging underneath the bar. Your body should be straight with your heels on the ground with your arms fully extended. This will be your starting position. Begin by flexing the elbow, pulling your chest towards the bar. Retract your shoulder blades as you perform the movement. Pause at the top of the motion, and return yourself to the start posit'),
('Inverted_Row_with_Straps', 'Inverted Row with Straps', 'back', ARRAY['arms','back']::text[], 'other', 'strength', 'beginner', 'Hang a rope or suspension straps from a rack or other stable object. Grasp the ends and position yourself in a supine position hanging from the ropes. Your body should be straight with your heels on the ground with your arms fully extended. This will be your starting position. Begin by flexing the elbow, pulling your chest to your hands. Retract your shoulder blades as you perform the movement. Pause at the top of the motion, and return yourself to the start position. Repeat for the desired numb'),
('Iron_Cross', 'Iron Cross', 'shoulders', ARRAY['chest','legs','legs','back','legs','back']::text[], 'dumbbell', 'strength', 'intermediate', NULL),
('Iron_Crosses_stretch', 'Iron Crosses (stretch)', 'legs', ARRAY[]::text[], 'other', 'stretching', 'intermediate', 'Lie face down on the floor, with your arms extended out to your side, palms pressed to the floor. This will be your starting position. To begin, flex one knee and bring that leg across the back of your body, attempting to touch it to the ground near the opposite hand. Promptly return the leg to the starting postion, and quickly repeat with the other leg. Continue alternating for 10-20 repetitions.'),
('Isometric_Chest_Squeezes', 'Isometric Chest Squeezes', 'chest', ARRAY['shoulders','arms']::text[], 'bodyweight', 'plyometrics', 'beginner', 'While either seating or standing, bend your arms at a 90-degree angle and place the palms of your hands together in front of your chest. Tip: Your hands should be open with the palms together and fingers facing forward (perpendicular to your torso). Push both hands against each other as you contract your chest. Start with slow tension and increase slowly. Keep breathing normally as you execute this contraction. Hold for the recommended number of seconds. Now release the tension slowly. Rest for '),
('Isometric_Neck_Exercise_-_Front_And_Back', 'Isometric Neck Exercise - Front And Back', 'other', ARRAY[]::text[], 'bodyweight', 'strength', 'beginner', 'With your head and neck in a neutral position (normal position with head erect facing forward), place both of your hands on the front side of your head. Now gently push forward as you contract the neck muscles but resisting any movement of your head. Start with slow tension and increase slowly. Keep breathing normally as you execute this contraction. Hold for the recommended number of seconds. Now release the tension slowly. Rest for the recommended amount of time and repeat with your hands plac'),
('Isometric_Neck_Exercise_-_Sides', 'Isometric Neck Exercise - Sides', 'other', ARRAY[]::text[], 'bodyweight', 'strength', 'beginner', 'With your head and neck in a neutral position (normal position with head erect facing forward), place your left hand on the left side of your head. Now gently push towards the left as you contract the left neck muscles but resisting any movement of your head. Start with slow tension and increase slowly. Keep breathing normally as you execute this contraction. Hold for the recommended number of seconds. Now release the tension slowly. Rest for the recommended amount of time and repeat with your r'),
('Isometric_Wipers', 'Isometric Wipers', 'chest', ARRAY['core','shoulders','arms']::text[], 'bodyweight', 'strength', 'beginner', 'Assume a push-up position, supporting your weight on your hands and toes while keeping your body straight. Your hands should be just outside of shoulder width. This will be your starting position. Begin by shifting your body weight as far to one side as possible, allowing the elbow on that side to flex as you lower your body. Reverse the motion by extending the flexed arm, pushing yourself up and then dropping to the other side. Repeat for the desired number of repetitions.'),
('JM_Press', 'JM Press', 'arms', ARRAY['chest','shoulders']::text[], 'barbell', 'strength', 'beginner', 'Start the exercise the same way you would a close grip bench press. You will lie on a flat bench while holding a barbell at arms length (fully extended) with the elbows in. However, instead of having the arms perpendicular to the torso, make sure the bar is set in a direct line above the upper chest. This will be your starting position. Now beginning from a fully extended position lower the bar down as if performing a lying triceps extension. Inhale as you perform this movement. When you reach t'),
('Jackknife_Sit-Up', 'Jackknife Sit-Up', 'core', ARRAY[]::text[], 'bodyweight', 'strength', 'beginner', 'Lie flat on the floor (or exercise mat) on your back with your arms extended straight back behind your head and your legs extended also. This will be your starting position. As you exhale, bend at the waist while simultaneously raising your legs and arms to meet in a jackknife position. Tip: The legs should be extended and lifted at approximately a 35-45 degree angle from the floor and the arms should be extended and parallel to your legs. The upper torso should be off the floor. While inhaling,'),
('Janda_Sit-Up', 'Janda Sit-Up', 'core', ARRAY[]::text[], 'bodyweight', 'strength', 'beginner', 'Position your body on the floor in the basic sit-up position; knees to a ninety degree angle with feet flat on the floor and arms either crossed over your chest or to the sides. This will be your starting position. As you strongly tighten your glutes and hamstrings, fill your lungs with air and in a slow (three to six second count) ascent, slowly exhale. Tip: It is important to tighten the glutes and hamstrings as this will cause the hip flexors to be inactivated in a process called reciprocal i'),
('Jefferson_Squats', 'Jefferson Squats', 'legs', ARRAY['legs','legs','legs','back','back']::text[], 'barbell', 'strength', 'intermediate', 'Place a barbell on the floor. Stand in the middle of the bar length wise. Bend down by bending at the knees and keeping your back straight and grasp the front of the bar with your right hand. Your palm should be in (neutral grip) facing the left side. Grasp the rear of the bar with your left hand. The palm of your hand should be in neutral grip alignment (palms facing the right side). Tip: Ensure that your grip is even on the bar. Your torso should be positioned right in the middle of the bar an'),
('Jerk_Balance', 'Jerk Balance', 'shoulders', ARRAY['legs','legs','legs','arms']::text[], 'barbell', 'olympic weightlifting', 'intermediate', 'This drill helps you learn to drive yourself low enough during the jerk and corrects those who move backward during the movement. Begin with the bar racked in the jerk position, with the shoulders forward, torso upright, and the feet split slightly apart. Initiate the movement as you would a normal jerk, dipping at the knees while keeping your torso vertical, and driving back up forcefully, using momentum and not your arms to elevate the weight. Keep the rear foot in place, using it to drive you'),
('Jerk_Dip_Squat', 'Jerk Dip Squat', 'legs', ARRAY['core','legs']::text[], 'barbell', 'olympic weightlifting', 'intermediate', 'This movement strengthens the dip portion of the jerk. Begin with the bar racked in the jerk position, with the shoulders forward to create a shelf and the bar lightly contacting the throat. The feet should be directly under the hips, with the feet turned out as is comfortable. Keeping the torso vertical, dip by flexing the knees, allowing them to travel forward and without moving the hips to the rear. The dip should not be excessive. Return the weight to the starting position by driving forcefu'),
('Jogging_Treadmill', 'Jogging, Treadmill', 'legs', ARRAY['legs','legs']::text[], 'machine', 'cardio', 'beginner', 'To begin, step onto the treadmill and select the desired option from the menu. Most treadmills have a manual setting, or you can select a program to run. Typically, you can enter your age and weight to estimate the amount of calories burned during exercise. Elevation can be adjusted to change the intensity of the workout. Treadmills offer convenience, cardiovascular benefits, and usually have less impact than jogging outside. A 150 lb person will burn almost 250 calories jogging for 30 minutes, '),
('Keg_Load', 'Keg Load', 'back', ARRAY['core','arms','legs','arms','legs','legs','back','legs','shoulders','back']::text[], 'other', 'strongman', 'intermediate', 'To load kegs, place the desired number a distance from the loading platform, typically 30-50 feet. Begin by grabbing the close handle of the first keg, tilting it onto its side to grab the opposite edge of the bottom of the keg. Lift the keg up to your chest. The higher you can place the keg, the faster you should be able to move to the platform. Shouldering is usually not allowed. Be sure to keep a firm hold on the keg. Move as quickly as possible to the platform, and load it, extending through'),
('Kettlebell_Arnold_Press', 'Kettlebell Arnold Press', 'shoulders', ARRAY['arms']::text[], 'kettlebell', 'strength', 'intermediate', 'Clean a kettlebell to your shoulder. Clean the kettlebell to your shoulder by extending through the legs and hips as you raise the kettlebell towards your shoulder. The palm should be facing inward. Looking straight ahead, press the kettlebell out and overhead, rotating your wrist so that your palm faces forward at the top of the motion. Return the kettlebell to the starting position, with the palm facing in.'),
('Kettlebell_Dead_Clean', 'Kettlebell Dead Clean', 'legs', ARRAY['legs','legs','back','legs','back']::text[], 'kettlebell', 'strength', 'intermediate', 'Place kettlebell between your feet. To get in the starting position, push your butt back and look straight ahead. Clean the kettlebell to your shoulder. Clean the kettlebell to your shoulders by extending through the legs and hips as you raise the kettlebell towards your shoulder. The wrist should rotate as you do so. Lower the kettlebell, keeping the hamstrings loaded by keeping your back straight and your butt out.'),
('Kettlebell_Figure_8', 'Kettlebell Figure 8', 'core', ARRAY['legs','shoulders']::text[], 'kettlebell', 'strength', 'intermediate', 'Place one kettlebell between your legs and take a wider than shoulder width stance. Bend over by pushing your butt out and keeping your back flat. Pick up a kettlebell and pass it to your other hand between your legs. The receiving hand should reach from behind the legs. Go back and forth for several repetitions.'),
('Kettlebell_Hang_Clean', 'Kettlebell Hang Clean', 'legs', ARRAY['legs','legs','back','shoulders','back']::text[], 'kettlebell', 'strength', 'intermediate', 'Place kettlebell between your feet. To get in the starting position, push your butt back and look straight ahead. Clean kettlebell to your shoulder. Clean the kettlebell to your shoulders by extending through the legs and hips as you raise the kettlebell towards your shoulder. The wrist should rotate as you do so. Lower kettlebell to a hanging position between your legs while keeping the hamstrings loaded. Keep your head up at all times.'),
('Kettlebell_One-Legged_Deadlift', 'Kettlebell One-Legged Deadlift', 'legs', ARRAY['legs','back']::text[], 'kettlebell', 'strength', 'intermediate', 'Hold a kettlebell by the handle in one hand. Stand on one leg, on the same side that you hold the kettlebell. Keeping that knee slightly bent, perform a stiff legged deadlift by bending at the hip, extending your free leg behind you for balance. Continue lowering the kettlebell until you are parallel to the ground, and then return to the upright position.'),
('Kettlebell_Pass_Between_The_Legs', 'Kettlebell Pass Between The Legs', 'core', ARRAY['legs','legs','shoulders']::text[], 'kettlebell', 'strength', 'intermediate', 'Place one kettlebell between your legs and take a comfortable stance. Bend over by pushing your butt out and keeping your back flat. Pick up a kettlebell and pass it to your other hand between your legs, in the fashion of a "W". Go back and forth for several repetitions.'),
('Kettlebell_Pirate_Ships', 'Kettlebell Pirate Ships', 'shoulders', ARRAY['core']::text[], 'kettlebell', 'strength', 'beginner', 'With a wide stance, hold a kettlebell with both hands. Allow it to hang at waist level with your arms extended. This will be your starting position. Initiate the movement by turning to one side, swinging the kettlebell to head height. Briefly pause at the top of the motion. Allow the bell to drop as you rotate to the opposite side, again raising the kettlebell to head height. Repeat for the desired amount of repetitions.'),
('Kettlebell_Pistol_Squat', 'Kettlebell Pistol Squat', 'legs', ARRAY['legs','legs','legs','shoulders']::text[], 'kettlebell', 'strength', 'expert', 'Pick up a kettlebell with two hands and hold it by the horns. Hold one leg off of the floor and squat down on the other. Squat down by flexing the knee and sitting back with the hips, holding the kettlebell up in front of you. Hold the bottom position for a second and then reverse the motion, driving through the heel and keeping your head and chest up. Lower yourself again and repeat.'),
('Kettlebell_Seated_Press', 'Kettlebell Seated Press', 'shoulders', ARRAY['arms']::text[], 'kettlebell', 'strength', 'intermediate', 'Sit on the floor and spread your legs out comfortably. Clean one kettlebell to your shoulder. Press the kettlebell up and out until it is locked out overhead. Return to the starting position.'),
('Kettlebell_Seesaw_Press', 'Kettlebell Seesaw Press', 'shoulders', ARRAY['arms']::text[], 'kettlebell', 'strength', 'intermediate', 'Clean two kettlebells two your shoulders. Press one kettlebell. Lower the kettlebell and immediately press the other kettlebell. Make sure to do the same amount of reps on both sides.'),
('Kettlebell_Sumo_High_Pull', 'Kettlebell Sumo High Pull', 'back', ARRAY['legs','legs','legs','legs','shoulders']::text[], 'kettlebell', 'strength', 'intermediate', 'Place a kettlebell on the ground between your feet. Position your feet in a wide stance, and grasp the kettlebell with two hands. Set your hips back as far as possible, with your knees bent. Keep your chest and head up. This will be your starting position. Begin by extending the hips and knees, simultaneously pulling the kettlebell to your shoulders, raising your elbows as you do so. Reverse the motion to return to the starting position.'),
('Kettlebell_Thruster', 'Kettlebell Thruster', 'shoulders', ARRAY['legs','arms']::text[], 'kettlebell', 'strength', 'intermediate', 'Clean two kettlebells to your shoulders. Clean the kettlebells to your shoulders by extending through the legs and hips as you pull the kettlebells towards your shoulders. Rotate your wrists as you do so. This will be your starting position. Begin to squat by flexing your hips and knees, lowering your hips between your legs. Maintain an upright, straight back as you descend as low as you can. At the bottom, reverse direction and squat by extending your knees and hips, driving through your heels.'),
('Kettlebell_Turkish_Get-Up_Lunge_style', 'Kettlebell Turkish Get-Up (Lunge style)', 'shoulders', ARRAY['core','legs','legs','arms']::text[], 'kettlebell', 'strength', 'intermediate', 'Lie on your back on the floor and press a kettlebell to the top position by extending the elbow. Bend the knee on the same side as the kettlebell. Keeping the kettlebell locked out at all times, pivot to the opposite side and use your non- working arm to assist you in driving forward to the lunge position. Using your free hand, push yourself to a seated position, then progressing to one knee. While looking up at the kettlebell, slowly stand up. Reverse the motion back to the starting position an'),
('Kettlebell_Turkish_Get-Up_Squat_style', 'Kettlebell Turkish Get-Up (Squat style)', 'shoulders', ARRAY['core','legs','legs','legs','arms']::text[], 'kettlebell', 'strength', 'intermediate', 'Lie on your back on the floor and press a kettlebell to the top position by extending the elbow. Bend the knee on the same side as the kettlebell. Keeping the kettlebell locked out at all times, pivot to the opposite side and use your non- working arm to assist you in driving forward to the lunge position. Using your free hand, push yourself to a seated position, then progressing to your feet. While looking up at the kettlebell, slowly stand up. Reverse the motion back to the starting position a'),
('Kettlebell_Windmill', 'Kettlebell Windmill', 'core', ARRAY['legs','legs','shoulders','arms']::text[], 'kettlebell', 'strength', 'intermediate', 'Place a kettlebell in front of your lead foot and clean and press it overhead with your opposite arm. Clean the kettlebell to your shoulder by extending through the legs and hips as you pull the kettlebell towards your shoulders. Rotate your wrist as you do so, so that the palm faces forward. Press it overhead by extending the elbow. Keeping the kettlebell locked out at all times, push your butt out in the direction of the locked out kettlebell. Turn your feet out at a forty-five degree angle fr'),
('Kipping_Muscle_Up', 'Kipping Muscle Up', 'back', ARRAY['core','arms','arms','back','shoulders','back','arms']::text[], 'other', 'strength', 'intermediate', 'Grip the rings using a false grip, with the base of your palms on top of the rings. Begin with a movement swinging your legs backward slightly. Counter that movement by swinging your legs forward and up, jerking your chin and chest back, pulling yourself up with both arms as you do so. As you reach the top position of the pull-up, pull the rings to your armpits as you roll your shoulders forward, allowing your elbows to move straight back behind you. This puts you into the proper position to con'),
('Knee_Across_The_Body', 'Knee Across The Body', 'legs', ARRAY['legs','back']::text[], 'other', 'stretching', 'beginner', 'Lie down on the floor with your right leg straight. Bend your left leg and lower it across your body, holding the knee down toward the floor with your right hand. (The knee doesn''t need to touch the floor if you''re tight.) Place your left arm comfortably beside you and turn your head to the left. Imagine you have a weight tied to your tailbone. let your tailbone fall back toward the floor as your chest reaches in the opposite direction to stretch your lower back. Switch sides.'),
('Knee_Circles', 'Knee Circles', 'legs', ARRAY['legs','legs']::text[], 'bodyweight', 'stretching', 'beginner', 'Stand with your legs together and hands by your waist. Now move your knees in a circular motion as you breathe normally. Repeat for the recommended amount of repetitions.'),
('Knee_Hip_Raise_On_Parallel_Bars', 'Knee/Hip Raise On Parallel Bars', 'core', ARRAY[]::text[], 'other', 'strength', 'beginner', 'Position your body on the vertical leg raise bench so that your forearms are resting on the pads next to the torso and holding on to the handles. Your arms will be bent at a 90 degree angle. The torso should be straight with the lower back pressed against the pad of the machine and the legs extended pointing towards the floor. This will be your starting position. Now as you breathe out, lift your legs up as you keep them extended. Continue this movement until your legs are roughly parallel to th'),
('Knee_Tuck_Jump', 'Knee Tuck Jump', 'legs', ARRAY['legs','legs','legs','legs','legs']::text[], 'bodyweight', 'plyometrics', 'beginner', 'Begin in a comfortable standing position with your knees slightly bent. Hold your hands in front of you, palms down with your fingertips together at chest height. This will be your starting position. Rapidly dip down into a quarter squat and immediately explode upward. Drive the knees towards the chest, attempting to touch them to the palms of the hands. Jump as high as you can, raising your knees up, and then ensure a good land be re-extending your legs, absorbing impact through be allowing the'),
('Kneeling_Arm_Drill', 'Kneeling Arm Drill', 'shoulders', ARRAY['core']::text[], 'other', 'plyometrics', 'beginner', 'This drill helps increase arm efficiency during the run. Begin kneeling, left foot in front, right knee down. Apply pressure through the front heel to keep your glutes and hamstrings activated. Begin by blocking the arms in long, pendulum like swings. Close the arm angle, blocking with the arms as you would when jogging, progressing to a run and finally a sprint. As soon as your hands pass the hip, accelerate them forward during the sprinting motion to move them as quickly as possible. Switch kn'),
('Kneeling_Cable_Crunch_With_Alternating_Oblique_Twists', 'Kneeling Cable Crunch With Alternating Oblique Twists', 'core', ARRAY[]::text[], 'cable', 'strength', 'beginner', 'Connect a rope attachment to a high pulley cable and position a mat on the floor in front of it. Grab the rope with both hands and kneel approximately two feet back from the tower. Position the rope behind your head with your hands by your ears. Keep your hands in the same place, contract your abs and pull downward on the rope in a crunching movement until your elbows reach your knees. Pause briefly at the bottom and rise up in a slow and controlled manner until you reach the starting position. '),
('Kneeling_Cable_Triceps_Extension', 'Kneeling Cable Triceps Extension', 'arms', ARRAY[]::text[], 'cable', 'strength', 'intermediate', 'Place a bench sideways in front of a high pulley machine. Hold a straight bar attachment above your head with your hands about 6 inches apart with your palms facing down. Face away from the machine and kneel. Place your head and the back of your upper arms on the bench. Your elbows should be bent with the forearms pointing towards the high pulley. This will be your starting position. While keeping your upper arms close to your head at all times with the elbows in, press the bar out in a semicirc'),
('Kneeling_Forearm_Stretch', 'Kneeling Forearm Stretch', 'arms', ARRAY[]::text[], 'other', 'stretching', 'beginner', 'Start by kneeling on a mat with your palms flat and your fingers pointing back toward your knees. Slowly lean back keeping your palms flat on the floor until you feel a stretch in your wrists and forearms. Hold for 20-30 seconds.'),
('Kneeling_High_Pulley_Row', 'Kneeling High Pulley Row', 'back', ARRAY['arms','back']::text[], 'cable', 'strength', 'beginner', 'Select the appropriate weight using a pulley that is above your head. Attach a rope to the cable and kneel a couple of feet away, holding the rope out in front of you with both arms extended. This will be your starting position. Initiate the movement by flexing the elbows and fully retracting your shoulders, pulling the rope toward your upper chest with your elbows out. After pausing briefly, slowly return to the starting position.'),
('Kneeling_Hip_Flexor', 'Kneeling Hip Flexor', 'legs', ARRAY['legs']::text[], 'other', 'stretching', 'beginner', 'Kneel on a mat and bring your right knee up so the bottom of your foot is on the floor and extend your left leg out behind you so the top of your foot is on the floor. Shift your weight forward until you feel a stretch in your hip. Hold for 15 seconds, then repeat for your other side.'),
('Kneeling_Jump_Squat', 'Kneeling Jump Squat', 'legs', ARRAY['legs','legs','legs']::text[], 'barbell', 'olympic weightlifting', 'expert', 'Begin kneeling on the floor with a barbell racked across the back of your shoulders, or you can use your body weight for this exercise. This can be done inside of a power rack to make unracking easier. Sit back with your hips until your glutes touch your feet, keeping your head and chest up. Explode up with your hips, generating enough power to land with your feet flat on the floor. Continue with the squat by driving through your heels and extending the knees to come to a standing position.'),
('Kneeling_Single-Arm_High_Pulley_Row', 'Kneeling Single-Arm High Pulley Row', 'back', ARRAY['arms','back']::text[], 'cable', 'strength', 'beginner', 'Attach a single handle to a high pulley and make your weight selection. Kneel in front of the cable tower, taking the cable with one hand with your arm extended. This will be your starting position. Starting with your palm facing forward, pull the weight down to your torso by flexing the elbow and retract the shoulder blade. As you do so, rotate the wrist so that at the completion of the movement, your palm is now facing you. After a brief pause, return to the starting position.'),
('Kneeling_Squat', 'Kneeling Squat', 'legs', ARRAY['core','legs','back']::text[], 'barbell', 'powerlifting', 'intermediate', 'Set the bar to the proper height in a power rack. Kneel behind the bar; it may be beneficial to put a mat down to pad your knees. Slide under the bar, racking it across the back of your shoulders. Your shoulder blades should be retracted and the bar tight across your back. Unrack the weight. With your head looking forward, sit back with your butt until you touch your calves. Reverse the motion, returning the torso to an upright position.')
INSERT INTO exercises (external_id, name, muscle_group, secondary_muscles, equipment, category, level, instructions) VALUES
('Landmine_180s', 'Landmine 180''s', 'core', ARRAY['legs','back','shoulders']::text[], 'barbell', 'strength', 'beginner', 'Position a bar into a landmine or securely anchor it in a corner. Load the bar to an appropriate weight. Raise the bar from the floor, taking it to shoulder height with both hands with your arms extended in front of you. Adopt a wide stance. This will be your starting position. Perform the movement by rotating the trunk and hips as you swing the weight all the way down to one side. Keep your arms extended throughout the exercise. Reverse the motion to swing the weight all the way to the opposite'),
('Landmine_Linear_Jammer', 'Landmine Linear Jammer', 'shoulders', ARRAY['core','legs','chest','legs','legs','arms']::text[], 'barbell', 'strength', 'intermediate', 'Position a bar into landmine or, lacking one, securely anchor it in a corner. Load the bar to an appropriate weight and position the handle attachment on the bar. Raise the bar from the floor, taking the handles to your shoulders. This will be your starting position. In an athletic stance, squat by flexing your hips and setting your hips back, keeping your arms flexed. Reverse the motion by powerfully extending through the hips, knees, and ankles, while also extending the elbows to straighten th'),
('Lateral_Bound', 'Lateral Bound', 'legs', ARRAY['legs','legs','legs','legs','legs']::text[], 'bodyweight', 'plyometrics', 'beginner', 'Assume a half squat position facing 90 degrees from your direction of travel. This will be your starting position. Allow your lead leg to do a countermovement inward as you shift your weight to the outside leg. Immediately push off and extend, attempting to bound to the side as far as possible. Upon landing, immediately push off in the opposite direction, returning to your original start position. Continue back and forth for several repetitions.'),
('Lateral_Box_Jump', 'Lateral Box Jump', 'legs', ARRAY['legs','legs','legs','legs','legs']::text[], 'other', 'plyometrics', 'beginner', 'Assume a comfortable standing position, with a short box positioned next to you. This will be your starting position. Quickly dip into a quarter squat to initiate the stretch reflex, and immediately reverse direction to jump up and to the side. Bring your knees high enough to ensure your feet have good clearance over the box. Land on the center of the box, using your legs to absorb the impact. Carefully jump down to the other side of the box, and continue going back and forth for several repetit'),
('Lateral_Cone_Hops', 'Lateral Cone Hops', 'legs', ARRAY['legs','legs','legs','legs','legs']::text[], 'other', 'plyometrics', 'beginner', 'Position a number of cones in a row several feet apart. Stand next to the end of the cones, facing 90 degrees to the direction of travel. This will be your starting position. Begin the jump by dipping with the knees to initiate a stretch reflex, and immediately reverse direction to push off the ground, jumping up and sideways over the cone. Use your legs to absorb impact upon landing, and rebound into the next jump, continuing down the row of cones.'),
('Lateral_Raise_-_With_Bands', 'Lateral Raise - With Bands', 'shoulders', ARRAY[]::text[], 'bands', 'strength', 'beginner', 'To begin, stand on an exercise band so that tension begins at arm''s length. Grasp the handles using a pronated (palms facing your thighs) grip that is slightly less than shoulder width. The handles should be resting on the sides of your thighs. Your arms should be extended with a slight bend at the elbows and your back should be straight. This will be your starting position. Use your side shoulders to lift the handles to the sides as you exhale. Continue to lift the handles until they are sligh'),
('Latissimus_Dorsi-SMR', 'Latissimus Dorsi-SMR', 'back', ARRAY[]::text[], 'other', 'stretching', 'beginner', 'While lying on the floor, place a foam roll under your back and to one side, just behind your arm pit. This will be your starting position. Keep the arm of the side being stretched behind and to the side of you as you shift your weight onto your lats, keeping your upper body off of the ground. Hold for 10-30 seconds, and switch sides.'),
('Leg-Over_Floor_Press', 'Leg-Over Floor Press', 'chest', ARRAY['shoulders','arms']::text[], 'kettlebell', 'strength', 'intermediate', 'Lie on the floor with one kettlebell in place on your chest, holding it by the handle. Extend leg on working side over leg on non-working side.Your free arm can be extended out to your side for support. Press the kettlebll into a locked out position. Lower the weight until the elbow touches the ground, keeping the kettlebell above the elbow. Repeat for the desired number of repetitions.'),
('Leg-Up_Hamstring_Stretch', 'Leg-Up Hamstring Stretch', 'legs', ARRAY[]::text[], 'other', 'stretching', 'beginner', 'Lie flat on your back, bend one knee, and put that foot flat on the floor to stabilize your spine. Extend the other leg in the air. If you''re tight, you wont be able to straighten it. That''s okay. Extend the knee so that the sole of the lifted foot faces the ceiling (or as close as you can get it). Slowly straighten the legs as much as possible and then pull the leg toward your nose. Switch sides.'),
('Leg_Extensions', 'Leg Extensions', 'legs', ARRAY[]::text[], 'machine', 'strength', 'beginner', 'For this exercise you will need to use a leg extension machine. First choose your weight and sit on the machine with your legs under the pad (feet pointed forward) and the hands holding the side bars. This will be your starting position. Tip: You will need to adjust the pad so that it falls on top of your lower leg (just above your feet). Also, make sure that your legs form a 90-degree angle between the lower and upper leg. If the angle is less than 90-degrees then that means the knee is over th'),
('Leg_Lift', 'Leg Lift', 'legs', ARRAY['legs']::text[], 'bodyweight', 'strength', 'beginner', 'While standing up straight with both feet next to each other at around shoulder width, grab a sturdy surface such as the sides of a squat rack or the top of a chair to brace yourself and keep balance. With or without an ankle weight, lift one leg behind you as if performing a leg curl but standing up while keeping the other leg straight. Breathe out as you perform this movement. Slowly bring the raised leg back to the floor as you breathe in. Repeat for the recommended amount of repetitions. Rep'),
('Leg_Press', 'Leg Press', 'legs', ARRAY['legs','legs','legs']::text[], 'machine', 'strength', 'beginner', 'Using a leg press machine, sit down on the machine and place your legs on the platform directly in front of you at a medium (shoulder width) foot stance. (Note: For the purposes of this discussion we will use the medium stance described above which targets overall development; however you can choose any of the three stances described in the foot positioning section). Lower the safety bars holding the weighted platform in place and press the platform all the way up until your legs are fully exten'),
('Leg_Pull-In', 'Leg Pull-In', 'core', ARRAY[]::text[], 'bodyweight', 'strength', 'beginner', 'Lie on an exercise mat with your legs extended and your hands either palms facing down next to you or under your glutes. Tip: My preference is with the hands next to me. This will be your starting position. Bend your knees and pull your upper thighs into your midsection as you breathe out. Continue the motion until your knees are around chest level. Contract your abs as you execute this movement and hold for a second at the top. Tip: As you perform the motion, the lower legs (calves) should alwa'),
('Leverage_Chest_Press', 'Leverage Chest Press', 'chest', ARRAY['shoulders','arms']::text[], 'machine', 'strength', 'beginner', 'Load an appropriate weight onto the pins and adjust the seat for your height. The handles should be near the bottom or middle of the pectorals at the beginning of the motion. Your chest and head should be up and your shoulder blades retracted. This will be your starting position. Press the handles forward by extending through the elbow. After a brief pause at the top, return the weight just above the start position, keeping tension on the muscles by not returning the weight to the stops until th'),
('Leverage_Deadlift', 'Leverage Deadlift', 'legs', ARRAY['legs','legs']::text[], 'machine', 'strength', 'beginner', 'Load the pins to an appropriate weight. Position yourself directly between the handles. Grasp the bottom handles with a comfortable grip, and then lower your hips as you take a breath. Look forward with your head and keep your chest up. This will be your starting position. Return the weight to the starting position.'),
('Leverage_Decline_Chest_Press', 'Leverage Decline Chest Press', 'chest', ARRAY['shoulders','arms']::text[], 'machine', 'strength', 'beginner', 'Load an appropriate weight onto the pins and adjust the seat for your height. The handles should be near the bottom of the pectorals at the beginning of the motion. Your chest and head should be up and your shoulder blades retracted. This will be your starting position. Press the handles forward by extending through the elbow. After a brief pause at the top, return the weight just above the start position, keeping tension on the muscles by not returning the weight to the stops until the set is c'),
('Leverage_High_Row', 'Leverage High Row', 'back', ARRAY['back']::text[], 'machine', 'strength', 'beginner', 'Load an appropriate weight onto the pins and adjust the seat height so that you can just reach the handles above you. Adjust the knee pad to help keep you down. Grasp the handles with a pronated grip. This will be your starting position. Pull the handles towards your torso, retracting your shoulder blades as you flex the elbow. Pause at the bottom of the motion, and then slowly return the handles to the starting position. For multiple repetitions, avoid completely returning the weight to the sto'),
('Leverage_Incline_Chest_Press', 'Leverage Incline Chest Press', 'chest', ARRAY['shoulders','arms']::text[], 'machine', 'strength', 'beginner', 'Load an appropriate weight onto the pins and adjust the seat for your height. The handles should be near the top of the pectorals at the beginning of the motion. Your chest and head should be up and your shoulder blades retracted. This will be your starting position. Press the handles forward by extending through the elbow. After a brief pause at the top, return the weight just above the start position, keeping tension on the muscles by not returning the weight to the stops until the set is comp'),
('Leverage_Iso_Row', 'Leverage Iso Row', 'back', ARRAY['arms','back']::text[], 'machine', 'strength', 'beginner', 'Load an appropriate weight onto the pins and adjust the seat height so that the handles are at chest level. Grasp the handles with either a neutral or pronated grip. This will be your starting position. Pull the handles towards your torso, retracting your shoulder blades as you flex the elbow. Pause at the bottom of the motion, and then slowly return the handles to the starting position. For multiple repetitions, avoid completely returning the weight to the stops to keep tension on the muscles b'),
('Leverage_Shoulder_Press', 'Leverage Shoulder Press', 'shoulders', ARRAY['arms']::text[], 'machine', 'strength', 'beginner', 'Load an appropriate weight onto the pins and adjust the seat for your height. The handles should be near the top of the shoulders at the beginning of the motion. Your chest and head should be up and handles held with a pronated grip. This will be your starting position. Press the handles upward by extending through the elbow. After a brief pause at the top, return the weight to just above the start position, keeping tension on the muscles by not returning the weight to the stops until the set is'),
('Leverage_Shrug', 'Leverage Shrug', 'back', ARRAY['arms']::text[], 'machine', 'strength', 'beginner', 'Load the pins to an appropriate weight. Position yourself directly between the handles. Grasp the top handles with a comfortable grip, and then lower your hips as you take a breath. Look forward with your head and keep your chest up. Drive through the floor with your heels, extending your hips and knees as you rise to a standing position. Keep your arms straight throughout the movement, finishing with your shoulders back. This will be your starting position. Raise the weight by shrugging the sho'),
('Linear_3-Part_Start_Technique', 'Linear 3-Part Start Technique', 'legs', ARRAY['legs','legs']::text[], 'other', 'plyometrics', 'beginner', 'This drill helps you accelerate as quickly as possible into a sprint from a dead stop. It helps to use a line to start from. Begin with two feet on the line. Place your left foot with the toe next to your right ankle. Place your right foot 4-6 inches behind the left. Place your right hand onto the line, and thing bring your nose close to your left knee. Squat down as you lean foward, your head being lower than your hips and your weight loaded onto the left leg. This will be your starting positio'),
('Linear_Acceleration_Wall_Drill', 'Linear Acceleration Wall Drill', 'legs', ARRAY['legs','legs','legs']::text[], 'other', 'plyometrics', 'beginner', 'Lean at around 45 degrees against a wall. Your feet should be together, glutes contracted. Begin by lifting your right knee quickly, pausing, and then driving it straight down into the ground. Switch legs, raising the opposite knee, and then attacking the ground straight down. Repeat once more with your right leg, and as soon as the right foot strikes the ground hammer them out rapidly, alternating left and right as fast as you can.'),
('Linear_Depth_Jump', 'Linear Depth Jump', 'legs', ARRAY['legs','legs','legs']::text[], 'other', 'plyometrics', 'intermediate', 'You will need two boxes or benches spaced a few feet away from each other. Begin by standing on one box facing towards the other platform. To initiate the movement, gently drop down to the ground between your platforms, allowing the knees and hips to flex. Reverse the motion by exploding, extending through the hips, knees, and ankles to jump onto the other platform. Land softly, asborbing the impact through the legs.'),
('Log_Lift', 'Log Lift', 'shoulders', ARRAY['core','chest','legs','legs','back','back','legs','back','arms']::text[], 'other', 'strongman', 'intermediate', 'Begin standing with the log in front of you. Grasp the handles, and begin to clean the log. As you are bent over to start the clean, attempt to get the log as high as possible, pulling it into your chest. Extend through the hips and knees to bring it up to complete the clean. Push your head back and look up, creating a shelf on your chest to rest the log. Begin the press by dipping, flexing slightly through the knees and reversing the motion. This push press will generate momentum to start the l'),
('London_Bridges', 'London Bridges', 'back', ARRAY['arms','arms','back']::text[], 'other', 'strength', 'intermediate', 'Attach a climbing rope to a high beam or cross member. Below it, ensure that the smith machine bar is locked in place with the safeties and cannot move. Alternatively, a secure box could also be utilized. Stand on the bar, using the rope to balance yourself. This will be your starting position. Keeping your body straight, lean back and lower your body by slowly going hand over hand with the rope. Continue until you are perpendicular to the ground. Keeping your body straight, reverse the motion, '),
('Looking_At_Ceiling', 'Looking At Ceiling', 'legs', ARRAY[]::text[], 'other', 'stretching', 'beginner', 'Kneel on the floor, holding your heels with both hands. Lift your buttocks up and forward while bringing your head back to look up at the ceiling, to give an arch in your back.'),
('Low_Cable_Crossover', 'Low Cable Crossover', 'chest', ARRAY['shoulders']::text[], 'cable', 'strength', 'beginner', 'To move into the starting position, place the pulleys at the low position, select the resistance to be used and grasp a handle in each hand. Step forward, gaining tension in the pulleys. Your palms should be facing forward, hands below the waist, and your arms straight. This will be your starting position. With a slight bend in your arms, draw your hands upward and toward the midline of your body. Your hands should come together in front of your chest, palms facing up. Return your arms back to t'),
('Low_Cable_Triceps_Extension', 'Low Cable Triceps Extension', 'arms', ARRAY[]::text[], 'cable', 'strength', 'beginner', 'Select the desired weight and lay down face up on the bench of a seated row machine that has a rope attached to it. Your head should be pointing towards the attachment. Grab the outside of the rope ends with your palms facing each other (neutral grip). Position your elbows so that they are bent at a 90 degree angle and your upper arms are perpendicular (90 degree angle) to your torso. Tip: Keep the elbows in and make sure that the upper arms point to the ceiling while your forearms point towards'),
('Low_Pulley_Row_To_Neck', 'Low Pulley Row To Neck', 'shoulders', ARRAY['arms','back','back']::text[], 'cable', 'strength', 'beginner', 'Sit on a low pulley row machine with a rope attachment. Grab the ends of the rope using a palms-down grip and sit with your back straight and your knees slightly bent. Tip: Keep your back almost completely vertical and your arms fully extended in front of you. This will be your starting position. While keeping your torso stationary, lift your elbows and start bending them as you pull the rope towards your neck while exhaling. Throughout the movement your upper arms should remain parallel to the '),
('Lower_Back-SMR', 'Lower Back-SMR', 'back', ARRAY[]::text[], 'other', 'stretching', 'beginner', 'In a seated position, place a foam roll under your lower back. Cross your arms in front of you and protract your shoulders. This will be your starting position. Raise your hips off of the floor and lean back, keeping your weight on your lower back. Now shift your weight slightly to one side, keeping your weight off of the spine and on the muscles to the side of it. Roll over your lower back, holding points of tension for 10-30 seconds. Repeat on the other side.'),
('Lower_Back_Curl', 'Lower Back Curl', 'core', ARRAY[]::text[], 'bodyweight', 'stretching', 'beginner', 'Lie on your stomach with your arms out to your sides. This will be your starting position. Using your lower back muscles, extend your spine lifting your chest off of the ground. Do not use your arms to push yourself up. Keep your head up during the movement. Repeat for 10-20 repetitions.'),
('Lunge_Pass_Through', 'Lunge Pass Through', 'legs', ARRAY['legs','legs','legs']::text[], 'kettlebell', 'strength', 'intermediate', 'Stand with your torso upright holding a kettlebell in your right hand. This will be your starting position. Step forward with your left foot and lower your upper body down by flexing the hip and the knee, keeping the torso upright. Lower your back knee until it nearly touches the ground. As you lunge, pass the kettlebell under your front leg to your opposite hand. Pressing through the heel of your foot, return to the starting position. Repeat the movement for the recommended amount of repetition'),
('Lunge_Sprint', 'Lunge Sprint', 'legs', ARRAY['legs','legs','legs']::text[], 'machine', 'strength', 'intermediate', 'Adjust a bar in a Smith machine to an appropriate height. Position yourself under the bar, racking it across the back of your shoulders. Unrack the bar, and then split your feet, moving one foot forward and one foot back. This will be your starting position. Lower your back knee nearly to the ground, flexing the knees and lowering your hips as you do so. At the bottom of the descent, immediately reverse direction. Explosively drive through the heel of your front foot with light pressure from you'),
('Lying_Bent_Leg_Groin', 'Lying Bent Leg Groin', 'legs', ARRAY[]::text[], 'other', 'stretching', 'expert', 'Lie on your back with your knees bent and the soles of the feet pressed together. Have your partner hold your knees. This will be your starting position. Attempt to squeeze your knees together, while your partner prevents any movement from occurring. After 10-20 seconds, relax your muscles as your partner gently pushes your knees towards the floor. Be sure to inform your helper when the stretch is adequate to prevent injury or overstretching.'),
('Lying_Cable_Curl', 'Lying Cable Curl', 'arms', ARRAY[]::text[], 'cable', 'strength', 'intermediate', 'Grab a straight bar or E-Z bar attachment that is attached to the low pulley with both hands, using an underhand (palms facing up) shoulder-width grip. Lie flat on your back on top of an exercise mat in front of the weight stack with your feet flat against the frame of the pulley machine and your legs straight. With your arms extended and your elbows close to your body slightly bend your arms. This will be your starting position. While keeping your upper arms stationary and the elbows close to y'),
('Lying_Cambered_Barbell_Row', 'Lying Cambered Barbell Row', 'back', ARRAY['arms','back','back']::text[], 'barbell', 'strength', 'beginner', 'Place a cambered bar underneath an exercise bench. Lie face down on the exercise bench and grab the bar using a palms down (pronated grip) that is wider than shoulder width. This will be your starting position. As you exhale row the bar up as you keep the elbows close to your body to either your chest, in order to target the upper mid back, or to your stomach if targeting the lats is your goal. After a second hold at the top, lower back down to the starting position slowly as you inhale.'),
('Lying_Close-Grip_Bar_Curl_On_High_Pulley', 'Lying Close-Grip Bar Curl On High Pulley', 'arms', ARRAY[]::text[], 'cable', 'strength', 'beginner', 'Place a flat bench in front of a high pulley or lat pulldown machine. Hold the straight bar attachment using an underhand grip (palms up) that is about shoulder width. Lie on your back with your head over the end of the bench. Now extend your arms straight above your shoulders. Your torso and your arms should make a 90-degree angle and the elbows should be in. This will be your starting position. As you breathe out, curl the bar down in a semicircular motion until it touches your chin. Squeeze t'),
('Lying_Close-Grip_Barbell_Triceps_Extension_Behind_The_Head', 'Lying Close-Grip Barbell Triceps Extension Behind The Head', 'arms', ARRAY[]::text[], 'barbell', 'strength', 'intermediate', 'While holding a barbell or EZ Curl bar with a pronated grip (palms facing forward), lie on your back on a flat bench with your head close to the end of the bench. Tip: If you are holding a barbell grab it using a shoulder-width grip and if you are using an E-Z Bar grab it on the inner handles. Extend your arms in front of you and slowly bring the bar back in a semi circular motion (while keeping the arms extended) to a position over your head. At the end of this step your arms should be overhead'),
('Lying_Close-Grip_Barbell_Triceps_Press_To_Chin', 'Lying Close-Grip Barbell Triceps Press To Chin', 'arms', ARRAY[]::text[], 'barbell', 'strength', 'intermediate', 'While holding a barbell or EZ Curl bar with a pronated grip (palms facing forward), lie on your back on a flat bench with your head off the end of the bench. Tip: If you are holding a barbell grab it using a shoulder-width grip and if you are using an E-Z Bar grab it on the inner handles. Extend your arms in front of you as you hold the barbell over your chest. The arms should be perpendicular to your torso (90-degree angle). This will be your starting position. As you inhale, lower the bar in a'),
('Lying_Crossover', 'Lying Crossover', 'legs', ARRAY[]::text[], 'bodyweight', 'stretching', 'expert', 'Lie on your back with your legs extended. Cross one leg over your body with the knee bent, attempting to touch the knee to the ground. Your partner should kneel beside you, holding your shoulder down with one hand and controlling the crossed leg with the other. this will be your starting position. Attempt to raise the bent knee off of the ground as your partner prevents any actual movement. After 10-20 seconds, relax the leg as your partner gently presses the knee towards the floor. Repeat with '),
('Lying_Dumbbell_Tricep_Extension', 'Lying Dumbbell Tricep Extension', 'arms', ARRAY['chest','shoulders']::text[], 'dumbbell', 'strength', 'intermediate', 'Lie on a flat bench while holding two dumbbells directly in front of you. Your arms should be fully extended at a 90-degree angle from your torso and the floor. The palms should be facing in and the elbows should be tucked in. This is the starting position. As you breathe in and you keep the upper arms stationary with the elbows in, slowly lower the weight until the dumbbells are near your ears. At that point, while keeping the elbows in and the upper arms stationary, use the triceps to bring th'),
('Lying_Face_Down_Plate_Neck_Resistance', 'Lying Face Down Plate Neck Resistance', 'other', ARRAY[]::text[], 'other', 'strength', 'intermediate', 'Lie face down with your whole body straight on a flat bench while holding a weight plate behind your head. Tip: You will need to position yourself so that your shoulders are slightly above the end of a flat bench in order for the upper chest, neck and face to be off the bench. This will be your starting position. While keeping the plate secure on the back of your head slowly lower your head (as in saying "yes") as you breathe in. Raise your head back up to the starting position in a semi-circula'),
('Lying_Face_Up_Plate_Neck_Resistance', 'Lying Face Up Plate Neck Resistance', 'other', ARRAY[]::text[], 'other', 'strength', 'intermediate', 'Lie face up with your whole body straight on a flat bench while holding a weight plate on top of your forehead. Tip: You will need to position yourself so that your shoulders are slightly above the end of a flat bench in order for the traps, neck and head to be off the bench. This will be your starting position. While keeping the plate secure on your forehead slowly lower your head back in a semi-circular motion as you breathe in. Raise your head back up to the starting position in a semi-circul'),
('Lying_Glute', 'Lying Glute', 'legs', ARRAY['legs']::text[], 'bodyweight', 'stretching', 'expert', 'Lie on your back with your partner kneeling beside you. Flex the hip of one leg, raising it off of the floor. Rotate the leg so the foot is over the opposite hip, the lower leg perpendicular to your body. Your partner should hold the knee and ankle in place. This will be your starting position. Attempt to push your leg towards your partner, who should be preventing any actual movement of the leg. After 10-20 seconds, completely relax as your partner gently pushes the ankle and knee towards your '),
('Lying_Hamstring', 'Lying Hamstring', 'legs', ARRAY['legs']::text[], 'other', 'stretching', 'expert', 'Lie on your back with your legs extended. Your partner should be kneeling beside you. Raise one leg up towards the ceiling and have your partner hold the ankle. Your partner can use their shoulder to brace your leg if necessary. This will be your starting position. With your partner holding your leg in place, attempt to flex the knee, contracting the hamstrings for 10-20 seconds. Then relax your leg, allowing your partner to gently push the leg towards your head. Be sure to inform your helper wh'),
('Lying_High_Bench_Barbell_Curl', 'Lying High Bench Barbell Curl', 'arms', ARRAY[]::text[], 'barbell', 'strength', 'intermediate', 'Lie face forward on a tall flat bench while holding a barbell with a supinated grip (palms facing up). Tip: If you are holding a barbell grab it using a shoulder-width grip and if you are using an E-Z Bar grab it on the inner handles. Your upper body should be positioned in a way that the upper chest is over the end of the bench and the barbell is hanging in front of you with the arms extended and perpendicular to the floor. This will be your starting position. While keeping the elbows in and th'),
('Lying_Leg_Curls', 'Lying Leg Curls', 'legs', ARRAY[]::text[], 'machine', 'strength', 'beginner', 'Adjust the machine lever to fit your height and lie face down on the leg curl machine with the pad of the lever on the back of your legs (just a few inches under the calves). Tip: Preferably use a leg curl machine that is angled as opposed to flat since an angled position is more favorable for hamstrings recruitment. Keeping the torso flat on the bench, ensure your legs are fully stretched and grab the side handles of the machine. Position your toes straight (or you can also use any of the other'),
('Lying_Machine_Squat', 'Lying Machine Squat', 'legs', ARRAY['legs','legs','legs']::text[], 'machine', 'strength', 'intermediate', 'Adjust the leg machine to a height that will allow you to get inside it with your knees bent and the thighs slightly below parallel. Once you select the weight, position yourself inside the machine face up with the knees bent and thighs slightly below parallel to the platform. Make sure that the knees do not go past the toes. The angle created between the hamstrings and the calves should be one that is slightly less than 90 degrees (since your starting position requires you to start slightly bel'),
('Lying_One-Arm_Lateral_Raise', 'Lying One-Arm Lateral Raise', 'shoulders', ARRAY[]::text[], 'dumbbell', 'strength', 'intermediate', 'While holding a dumbbell in one hand, lay with your chest down on a flat bench. The other hand can be used to hold to the leg of the bench for stability. Position the palm of the hand that is holding the dumbbell in a neutral manner (palms facing your torso) as you keep the arm extended with the elbow slightly bent. This will be your starting position. Now raise the arm with the dumbbell to the side until your elbow is at shoulder height and your arm is roughly parallel to the floor as you exhal')
